INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "完成学业并从学校毕业的学生。", "primary_collocate": null, "pronunciation": "bì yè shēng", "ipa": "pi˥˩ ie˥˩ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "她是一名大学毕业生，在银行工作。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司今年要招十个毕业生。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业生拿着证书，笑得很开心。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多毕业生去了别的城市工作。", "target_word": "毕业生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个毕业生写过很多好文章。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请毕业生回来讲讲自己的故事。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业生找到工作了，家人很高兴。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是新毕业生，已经工作五年了。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的毕业生现在都在做什么？", "target_word": "毕业生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业生们在学校门口拍了合影。", "target_word": "毕业生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "大学毕业生", "label": "复合"}, {"form": "应届毕业生", "label": "复合"}], "register": "中性", "sense_fingerprint": "完成学业、已从学校毕业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa43149-2bed-4ace-a420-196d5d97c406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕业生", "is_correct": true, "explanation": "毕业生指已完成学业的人，“一名大学毕业生”与句意相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机与“大学”的身份不符，也不会在大学工作。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“大学厨师”不是通用说法，且与“在银行工作”矛盾。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士的工作地点是医院，与“在银行工作”的句意矛盾。"}], "explanations": {"毕业生": "毕业生指已完成学业的人，“一名大学毕业生”与句意相符。", "司机": "语义：司机与“大学”的身份不符，也不会在大学工作。", "厨师": "搭配：“大学厨师”不是通用说法，且与“在银行工作”矛盾。", "护士": "语义：护士的工作地点是医院，与“在银行工作”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "毕业生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毕业生都要参加期末考试。", "explanation": "这里应该用〈学生〉。毕业生已读完学业，不用再参加期末考试；参加期末考试的是在读学生。"}, {"text": "这位毕业生今年刚入学，还不熟悉校园。", "explanation": "这里应该用〈新生〉。毕业生已完成学业并从学校毕业，不会刚入学；刚入学、还不熟悉校园的是新生。"}, {"text": "这位毕业生明天还要到教室交作业。", "explanation": "这里应该用〈在校生〉。毕业生已完成学业并从学校毕业，不会再到教室交作业；需要到教室交作业的是在校生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业生", "is_correct": true, "explanation": "毕业生指已完成学业的人，能够“找到工作”，与句意相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不能工作，不可能“找到工作”。"}, {"text": "新生", "is_correct": false, "explanation": "语义：新生刚入学，还没有毕业，不会“找到工作”。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“找到工作”的主语应是成年人，小学生不找工作，与句意不搭。"}], "explanations": {"毕业生": "毕业生指已完成学业的人，能够“找到工作”，与句意相符。", "婴儿": "语义：婴儿还不能工作，不可能“找到工作”。", "新生": "语义：新生刚入学，还没有毕业，不会“找到工作”。", "小学生": "搭配：“找到工作”的主语应是成年人，小学生不找工作，与句意不搭。"}, "sentence_index": 6, "correct_answer": "毕业生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毕业生今年秋天要转入我们班插班学习。", "explanation": "这里应该用〈插班生〉。毕业生已完成学业并从学校毕业，不会转入班级插班学习；插班学习的是插班生。"}, {"text": "毕业生每周要上十几节课。", "explanation": "这里应该用〈本科生〉。毕业生已离开学校，不再每周上课；上课的是在读的本科生。"}, {"text": "这位毕业生今年要留级，重新读一年级。", "explanation": "这里应该用〈留级生〉。毕业生已完成学业并从学校毕业，不会留级重读；留级、重新读一年级的是留级生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三毕业生都找到了工作。", "corrected_sentence": "三名毕业生都找到了工作。", "error_description": "“三”与“毕业生”之间要有量词，应说“三名毕业生”，错误在漏掉量词“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐是一只大学毕业生。", "corrected_sentence": "我姐姐是一名大学毕业生。", "error_description": "量词错误：“毕业生”是人，量词应用“名”，“只”用于动物，不能用于此。应说“一名大学毕业生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
