INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "亲戚是和你家有关系的人，比如姑姑、舅舅。", "primary_collocate": null, "pronunciation": "qīn qi", "ipa": "tɕʰin⁵⁵ tɕʰi", "syllable_count": 2, "sentences": [{"text": "过年的时候,很多亲戚来我家。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个亲戚在上海工作。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姑姑和舅舅都是我的亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去看亲戚。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家的亲戚很多。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的亲戚住在农村。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的亲戚都很热情。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日那天,亲戚送了我一本书。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家有几个亲戚在北京?", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给亲戚打了一个电话。", "target_word": "亲戚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "亲戚朋友", "label": "复合"}, {"form": "親戚", "label": "繁体"}], "register": "口语", "sense_fingerprint": "和自己家有关系的人，如姑姑、舅舅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲戚", "is_correct": true, "explanation": "“亲戚”指有亲属关系的人，与“过年时很多亲戚来我家”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能来我家做客。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不会来我家。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“来”要求人作主语，汽车不能来我家做客。"}], "explanations": {"亲戚": "“亲戚”指有亲属关系的人，与“过年时很多亲戚来我家”的语境相符。", "石头": "语义：“石头”没有生命，不能来我家做客。", "课本": "语义：“课本”是书，不会来我家。", "汽车": "搭配：“来”要求人作主语，汽车不能来我家做客。"}, "sentence_index": 0, "correct_answer": "亲戚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在火车上碰到一个亲戚，他跟我们家没有任何关系。", "explanation": "这里应该用〈陌生人〉。亲戚是和你家有关系的人，这句说没有任何关系，应说“陌生人”。"}, {"text": "他是我的亲戚，我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈邻居〉。亲戚必须有血缘或婚姻关系，这句说没有任何关系，只能说“邻居”。"}, {"text": "我的亲戚只有父母和妹妹。", "explanation": "这里应该用〈亲人〉。父母、兄妹是直系亲属，不属于“亲戚”，应说“亲人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲戚", "is_correct": true, "explanation": "“亲戚”指有亲属关系的人，与“我们家的亲戚都很热情”的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用于家具。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”没有情感，不能说热情。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不会有热情的态度。"}], "explanations": {"亲戚": "“亲戚”指有亲属关系的人，与“我们家的亲戚都很热情”的语境相符。", "桌子": "搭配：“热情”形容人的态度，不能用于家具。", "窗户": "语义：“窗户”没有情感，不能说热情。", "书包": "语义：“书包”是物品，不会有热情的态度。"}, "sentence_index": 6, "correct_answer": "亲戚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛里，他是我的亲戚，但我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈对手〉。亲戚必须有血缘或婚姻关系，这句说没有关系，只能说是赛场上的对手。"}, {"text": "我同桌是我的亲戚，但我们之间没有任何血缘或婚姻关系，只是很要好的交情。", "explanation": "这里应该用〈朋友〉。亲戚必须有血缘或婚姻关系，这句说只是交情，应说“朋友”。"}, {"text": "我和他是同一家公司的亲戚，但我们之间没有任何血缘或婚姻关系。", "explanation": "这里应该用〈同事〉。亲戚必须有血缘或婚姻关系，这句说没有关系，只是同事关系，应说“同事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有一只亲戚在国外工作。", "corrected_sentence": "他家有一个亲戚在国外工作。", "error_description": "“只”多用于动物等，不能修饰人。修饰“亲戚”应用“个”，说“一个亲戚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末，我家来了好多亲戚们。", "corrected_sentence": "周末，我家来了好多亲戚。", "error_description": "“好多”已表示数量，后面不能再加“们”，应说“好多亲戚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
