INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "贼是偷别人东西的坏人。", "primary_collocate": null, "pronunciation": "zéi", "ipa": "tsei˧˥", "syllable_count": 1, "sentences": [{"text": "他不是好人，是个贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里来了一个贼，老板很生气。", "target_word": "贼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都怕那个贼再来。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贼偷了别人的东西，要受罚。", "target_word": "贼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上以前有很多贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的狗看见贼，就大叫起来。", "target_word": "贼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把贼带走了。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个贼偷了老人的自行车。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说：“贼走了，我们安全了。”", "target_word": "贼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，这里晚上有贼。", "target_word": "贼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小贼", "label": "复合"}, {"form": "盗贼", "label": "复合"}, {"form": "賊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "偷别人东西的坏人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa43149-2bed-4ace-a420-196d5d97c406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贼", "is_correct": true, "explanation": "贼指偷别人东西的坏人，与“不是好人”相符。"}, {"text": "好人", "is_correct": false, "explanation": "语义：前面说“不是好人”，后面又说“是个好人”，前后矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“是个”后接的应是人或职业名词，“桌子”是物品，不能用来指人。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不是人，与“他”的所指不合。"}], "explanations": {"贼": "贼指偷别人东西的坏人，与“不是好人”相符。", "好人": "语义：前面说“不是好人”，后面又说“是个好人”，前后矛盾。", "桌子": "搭配：“是个”后接的应是人或职业名词，“桌子”是物品，不能用来指人。", "花": "语义：花不是人，与“他”的所指不合。"}, "sentence_index": 0, "correct_answer": "贼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "贼每天在学校里给学生上课。", "explanation": "这里应该用〈老师〉。老师在学校给学生上课；贼是偷别人东西的人，不给学生上课。"}, {"text": "贼每天在花园里浇水、修剪花草。", "explanation": "这里应该用〈园丁〉。园丁负责给花园浇水、修剪花草；贼是偷别人东西的人，不做这些工作。"}, {"text": "路边坐着一个贼，伸手向路人要钱。", "explanation": "这里应该用〈乞丐〉。乞丐坐在路边向路人要钱，不偷东西；贼是偷别人东西的人，不会伸手向路人要钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贼", "is_correct": true, "explanation": "贼是偷东西的人，警察把他带走，与句意相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被警察带走，与句意不合。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能被警察带走，与句意不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“把……带走”的宾语应是可以移动的人或物，“空气”不能这样搭配。"}], "explanations": {"贼": "贼是偷东西的人，警察把他带走，与句意相符。", "太阳": "语义：太阳不能被警察带走，与句意不合。", "春天": "语义：春天是季节，不能被警察带走，与句意不合。", "空气": "搭配：“把……带走”的宾语应是可以移动的人或物，“空气”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "贼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "贼绑走了一个小孩子。", "explanation": "这里应该用〈绑架犯〉。贼是偷东西的人，绑人勒索的要用“绑架犯”。"}, {"text": "贼在厨房里炒了一盘好菜。", "explanation": "这里应该用〈厨师〉。厨师在厨房炒菜做饭；贼是偷别人东西的人，不做饭。"}, {"text": "贼每天早上在医院里给病人看病。", "explanation": "这里应该用〈医生〉。医生在医院给病人看病；贼是偷东西的人，不给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那群贼们都被抓了。", "corrected_sentence": "那群贼都被抓了。", "error_description": "“群”已表示多数，“贼”后面不能再加“们”，应说“那群贼”，错误在“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只贼偷了邻居的自行车。", "corrected_sentence": "那个贼偷了邻居的自行车。", "error_description": "“贼”指人，量词应用“个”，不能用“只”，应说“那个贼”，错误在量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
