INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "证明持有人身份的证件，上面有姓名、出生日期等信息。", "primary_collocate": null, "pronunciation": "shēn fèn zhèng", "ipa": "ʂən˥ fən˥˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "请把你的身份证给我看一下。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的身份证丢了，要去补办。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买火车票要带身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上有你的姓名和照片。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘带身份证，不能进银行。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张身份证是去年办的。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住酒店的时候要给前台看身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身份证上的出生日期写错了。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十八岁那年拿到了第一张身份证。", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说：“请出示您的身份证。”", "target_word": "身份证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "身份證", "label": "繁体"}, {"form": "身份证号", "label": "复合"}], "register": "中性", "sense_fingerprint": "证明身份、写有姓名和出生日期的证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d1bb30-3dc3-4c0f-bcac-045bc503ad42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：证明持有人身份的证件，与“请把你的……给我看一下”的句意相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不能拿出来给人看，与句意不符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“看”不能与“心情”搭配，句子读起来不通。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印不是可以拿给别人看的物品，与句意不符。"}], "explanations": {"身份证": "身份证：证明持有人身份的证件，与“请把你的……给我看一下”的句意相符。", "生日": "语义：生日不能拿出来给人看，与句意不符。", "心情": "搭配：“看”不能与“心情”搭配，句子读起来不通。", "脚印": "语义：脚印不是可以拿给别人看的物品，与句意不符。"}, "sentence_index": 0, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去展览馆要买身份证。", "explanation": "这里应该用〈门票〉。去展览馆要买门票，身份证不能用来买票。"}, {"text": "开会时大家互相交换身份证。", "explanation": "这里应该用〈名片〉。交换介绍用的是〈名片〉，身份证是政府发放的证件，不用于交换。"}, {"text": "他的身份证是医生。", "explanation": "这里应该用〈身份〉。身份证是证件，说人的身份或职业要用〈身份〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身份证", "is_correct": true, "explanation": "身份证：证明持有人身份的证件，与“住酒店的时候要给前台看……”的句意相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能与“声音”搭配，句子读起来不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能与“味道”搭配，句子读起来不通。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：给前台看梦想不符合酒店登记的语境，句意不通。"}], "explanations": {"身份证": "身份证：证明持有人身份的证件，与“住酒店的时候要给前台看……”的句意相符。", "声音": "搭配：“看”不能与“声音”搭配，句子读起来不通。", "味道": "搭配：“看”不能与“味道”搭配，句子读起来不通。", "梦想": "语义：给前台看梦想不符合酒店登记的语境，句意不通。"}, "sentence_index": 6, "correct_answer": "身份证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用身份证给手机充电。", "explanation": "这里应该用〈充电宝〉。身份证不能给手机充电。"}, {"text": "点菜时要看身份证。", "explanation": "这里应该用〈菜单〉。点菜要看菜单，身份证不用于点菜。"}, {"text": "他的身份证是护士。", "explanation": "这里应该用〈职业〉。身份证是证件，不能用来说明人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没带一本身份证，进不了银行。", "corrected_sentence": "我没带一张身份证，进不了银行。", "error_description": "错误：“一本身份证”；正确：“一张身份证”。身份证是卡片，量词用“张”，不用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
