INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95139, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "齐是都在，一个也不少。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "客人都到齐了，我们开饭吧。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人还没齐，再等一会儿。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜上齐了，大家可以吃了。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的人都来齐了吗？", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，作业本已经收齐了。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去旅行要带的东西，我都买齐了。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天一家人难得这么齐。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的十一个人都到齐了，比赛可以开始了。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天终于把这套书配齐了。", "target_word": "齐", "complexity_tier": "T3", "furigana": "wǒ jīn tiān zhōng yú bǎ zhè tào shū pèi qí le.", "sentence_source": "generated"}, {"text": "参加考试的学生还没到齐，不能发卷子。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "齐了", "label": "体标"}, {"form": "齐全", "label": "复合"}, {"form": "齊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "齐：人或东西都到了、都有了，一个也不缺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95139, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "齐", "is_correct": true, "explanation": "齐（第二声）意思是都在、一个不缺，是本词。"}, {"text": "启", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启。"}, {"text": "弃", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是放弃。"}, {"text": "妻", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是妻子。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。"}], "explanations": {"齐": "齐（第二声）意思是都在、一个不缺，是本词。", "启": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启。", "弃": "qì（第四声）与 qí（第二声）声调不同，意思是放弃。", "妻": "qī（第一声）与 qí（第二声）声调不同，意思是妻子。", "欺": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。"}, "sentence_index": null, "correct_answer": "齐"}, "level_3": {"options": [{"text": "齐", "is_correct": true, "explanation": "“齐”表示都到了、一个不缺，与“到……了”和“我们开饭吧”的语境相符。"}, {"text": "迟", "is_correct": false, "explanation": "语义：“到迟了”强调来得晚，与人已到齐、可以开饭的语境不符。"}, {"text": "满", "is_correct": false, "explanation": "搭配：“满”说装满、坐满，不说人“到满”。"}, {"text": "早", "is_correct": false, "explanation": "语义：“到早了”强调时间早，与人已全部到场、可以开饭的语境不符。"}], "explanations": {"齐": "“齐”表示都到了、一个不缺，与“到……了”和“我们开饭吧”的语境相符。", "迟": "语义：“到迟了”强调来得晚，与人已到齐、可以开饭的语境不符。", "满": "搭配：“满”说装满、坐满，不说人“到满”。", "早": "语义：“到早了”强调时间早，与人已全部到场、可以开饭的语境不符。"}, "sentence_index": 0, "correct_answer": "齐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套丛书的书脊排得很齐。", "explanation": "这里应该用〈整齐〉。齐在这里指排列平整，不是“都在、一个不缺”的义项，书脊的排列要用〈整齐〉。"}, {"text": "他考虑问题很齐。", "explanation": "这里应该用〈周全〉。齐在这里表示完备、面面俱到，并非“都在、一个不缺”的义项；考虑是否周全要用〈周全〉。"}, {"text": "这家店的生意很齐。", "explanation": "这里应该用〈兴隆〉。齐不能用来说生意的旺盛，生意兴旺要用〈兴隆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95139, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "齐", "is_correct": true, "explanation": "齐（第二声）意思是都在、一个不缺，是本词。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是空气。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。"}, {"text": "泣", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是哭泣。"}], "explanations": {"齐": "齐（第二声）意思是都在、一个不缺，是本词。", "起": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。", "气": "qì（第四声）与 qí（第二声）声调不同，意思是空气。", "七": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。", "泣": "qì（第四声）与 qí（第二声）声调不同，意思是哭泣。"}, "sentence_index": null, "correct_answer": "齐"}, "level_3": {"options": [{"text": "齐", "is_correct": true, "explanation": "“齐”表示一个不缺，与“今天一家人难得这么”的语境相符。"}, {"text": "散", "is_correct": false, "explanation": "语义：“散”指分开、不聚在一起，与“难得这么……”强调全家聚齐相反。"}, {"text": "少", "is_correct": false, "explanation": "语义：“少”指人数不多，与全家聚齐、难得一见的语境不符。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”说距离，不用来形容一家人聚集的状况。"}], "explanations": {"齐": "“齐”表示一个不缺，与“今天一家人难得这么”的语境相符。", "散": "语义：“散”指分开、不聚在一起，与“难得这么……”强调全家聚齐相反。", "少": "语义：“少”指人数不多，与全家聚齐、难得一见的语境不符。", "远": "搭配：“远”说距离，不用来形容一家人聚集的状况。"}, "sentence_index": 6, "correct_answer": "齐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这排房子的窗户装得很齐。", "explanation": "这里应该用〈整齐〉。齐在此指排列平整，与“都在、一个不缺”不是同一义项；窗户排得整齐要用〈整齐〉。"}, {"text": "他们的步调很齐。", "explanation": "这里应该用〈一致〉。齐在这里指步调统一，不是“都在、一个不缺”的义项，步调统一要用〈一致〉。"}, {"text": "这个小区的网速很齐。", "explanation": "这里应该用〈快〉。齐不能用来说网速，网速的快慢要用〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "东西都买了齐，我们走吧。", "corrected_sentence": "东西都买齐了，我们走吧。", "error_description": "“买了齐”错误，应为“买齐了”。结果补语“齐”要紧跟动词“买”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们都到了齐，可以开始上课了。", "corrected_sentence": "学生们都到齐了，可以开始上课了。", "error_description": "“到了齐”错误，应为“到齐了”。结果补语“齐”要紧跟动词“到”，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参差", "is_correct": true, "explanation": "参差指长短、高低不一，与“齐”的排列整齐相反，构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "与“齐”无反义关系：“高兴”指心情愉快，与排列整齐无关。"}, {"text": "柔软", "is_correct": false, "explanation": "与“齐”无反义关系：“柔软”说质地，不涉及排列。"}, {"text": "明亮", "is_correct": false, "explanation": "与“齐”无反义关系：“明亮”说光线或颜色，与排列无关。"}], "correct_answer": "参差", "explanations": {"参差": "参差指长短、高低不一，与“齐”的排列整齐相反，构成反义关系。", "高兴": "与“齐”无反义关系：“高兴”指心情愉快，与排列整齐无关。", "柔软": "与“齐”无反义关系：“柔软”说质地，不涉及排列。", "明亮": "与“齐”无反义关系：“明亮”说光线或颜色，与排列无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参差", "is_correct": true, "explanation": "参差指长短、高低不一，与“齐”的排列整齐相反，构成反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "与“齐”无反义关系：“干燥”说水分少，与整齐无关。"}, {"text": "沉重", "is_correct": false, "explanation": "与“齐”无反义关系：“沉重”说重量或心情，与排列无关。"}, {"text": "遥远", "is_correct": false, "explanation": "与“齐”无反义关系：“遥远”说距离，与排列整齐无关。"}], "correct_answer": "参差", "explanations": {"参差": "参差指长短、高低不一，与“齐”的排列整齐相反，构成反义关系。", "干燥": "与“齐”无反义关系：“干燥”说水分少，与整齐无关。", "沉重": "与“齐”无反义关系：“沉重”说重量或心情，与排列无关。", "遥远": "与“齐”无反义关系：“遥远”说距离，与排列整齐无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "整齐；全，完备。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "同学们排得很齐，老师很满意。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的牙齿长得很齐。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书摆得不太齐，你再整理一下。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把桌上的笔摆齐了。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们的步伐很齐，像一个人似的。", "target_word": "齐", "complexity_tier": "T3", "furigana": "shì bīng men de bù fá hěn qí, xiàng yí gè rén shì de.", "sentence_source": "generated"}, {"text": "这张纸剪得不齐，边上一高一低。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的树种得很齐，像一排小兵。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的歌声很齐，听起来很好听。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家把椅子排齐，不要歪着。", "target_word": "齐", "complexity_tier": "T3", "furigana": "qǐng dà jiā bǎ yǐ zi pái qí, bú yào wāi zhe.", "sentence_source": "generated"}, {"text": "他的头发剪得很齐，看起来很精神。", "target_word": "齐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整齐", "label": "复合"}, {"form": "齊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "齐：排列、边缘等平整，不歪斜、不参差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "齐", "is_correct": true, "explanation": "齐（第二声）意思是整齐、平齐，是本词。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是空气。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是日期、期望。"}], "explanations": {"齐": "齐（第二声）意思是整齐、平齐，是本词。", "起": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来、起身。", "气": "qì（第四声）与 qí（第二声）声调不同，意思是空气。", "七": "qī（第一声）与 qí（第二声）声调不同，意思是数字七。", "期": "qī（第一声）与 qí（第二声）声调不同，意思是日期、期望。"}, "sentence_index": null, "correct_answer": "齐"}, "level_3": {"options": [{"text": "齐", "is_correct": true, "explanation": "“齐”指排列整齐，与“排得很”相符，也与“老师很满意”一致。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”指杂乱，“排得很乱”与“老师很满意”相矛盾。"}, {"text": "歪", "is_correct": false, "explanation": "语义：“歪”指不正、斜向一边，排得歪斜不会让老师满意。"}, {"text": "散", "is_correct": false, "explanation": "搭配：“排”的结果是整齐的队列，不说“排得很散”。"}], "explanations": {"齐": "“齐”指排列整齐，与“排得很”相符，也与“老师很满意”一致。", "乱": "语义：“乱”指杂乱，“排得很乱”与“老师很满意”相矛盾。", "歪": "语义：“歪”指不正、斜向一边，排得歪斜不会让老师满意。", "散": "搭配：“排”的结果是整齐的队列，不说“排得很散”。"}, "sentence_index": 0, "correct_answer": "齐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这架天平两边的重量很齐。", "explanation": "这里应该用〈平衡〉。齐指排列整齐、边缘平整，两边重量或力量的均衡要用〈平衡〉。"}, {"text": "雨水在田里下得很齐。", "explanation": "这里应该用〈均匀〉。齐指排列整齐，雨水分布、厚薄平均要用〈均匀〉。"}, {"text": "这次聚会的人很齐。", "explanation": "齐在这里表示人都在，是“都在、一个不缺”的义项，与排列平整无关，并非本义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "齐", "is_correct": true, "explanation": "齐（第二声）意思是整齐、平齐，是本词。"}, {"text": "妻", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是妻子。"}, {"text": "汽", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。"}, {"text": "泣", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是哭泣。"}], "explanations": {"齐": "齐（第二声）意思是整齐、平齐，是本词。", "妻": "qī（第一声）与 qí（第二声）声调不同，意思是妻子。", "汽": "qì（第四声）与 qí（第二声）声调不同，意思是蒸汽。", "欺": "qī（第一声）与 qí（第二声）声调不同，意思是欺负。", "泣": "qì（第四声）与 qí（第二声）声调不同，意思是哭泣。"}, "sentence_index": null, "correct_answer": "齐"}, "level_3": {"options": [{"text": "齐", "is_correct": true, "explanation": "“齐”指排列整齐，与“像一排小兵”的整齐队列一致。"}, {"text": "斜", "is_correct": false, "explanation": "语义：“斜”指不正，与“像一排小兵”的整齐队列相矛盾。"}, {"text": "偏", "is_correct": false, "explanation": "搭配：“偏”多指位置偏离，说树木种得偏不自然，也与“一排小兵”相矛盾。"}, {"text": "错落", "is_correct": false, "explanation": "语义：“错落”指高低参差，与“像一排小兵”的整齐排列相矛盾。"}], "explanations": {"齐": "“齐”指排列整齐，与“像一排小兵”的整齐队列一致。", "斜": "语义：“斜”指不正，与“像一排小兵”的整齐队列相矛盾。", "偏": "搭配：“偏”多指位置偏离，说树木种得偏不自然，也与“一排小兵”相矛盾。", "错落": "语义：“错落”指高低参差，与“像一排小兵”的整齐排列相矛盾。"}, "sentence_index": 6, "correct_answer": "齐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几年物价很齐。", "explanation": "这里应该用〈稳定〉。齐指排列整齐、边缘平整，物价的平稳、不起伏要用〈稳定〉。"}, {"text": "他的脾气很齐。", "explanation": "这里应该用〈温和〉。齐指排列整齐、边缘平整，脾气、性格的平和要用〈温和〉。"}, {"text": "他的发言很齐。", "explanation": "这里应该用〈流畅〉。齐指排列整齐，语言表达的顺畅程度要用〈流畅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把碗筷摆了齐。", "corrected_sentence": "他把碗筷摆齐了。", "error_description": "“摆了齐”错误，应为“摆齐了”。结果补语“齐”要紧跟动词“摆”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队员们站得齐很。", "corrected_sentence": "队员们站得很齐。", "error_description": "“站得齐很”错误，程度副词“很”应放在“齐”前，应为“站得很齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
