INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95143, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修订是把书或文章改好。", "primary_collocate": null, "pronunciation": "xiū dìng", "ipa": "ɕioʊ˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "作者正在修订这本书。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们修订自己的作文。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章还要再修订一次。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧稿子重新修订了一遍。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社要求作者修订第二章。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典修订以后，多了很多新词。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花了三个月修订论文。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修订过这本小说的前几页。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先修订一下这份报告，再交给经理。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书修订好了，下个月就能买到。", "target_word": "修订", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修订了", "label": "体标"}, {"form": "修订过", "label": "体标"}, {"form": "修订本", "label": "复合"}, {"form": "修訂", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "修订：对书稿、文章等作品修改订正，使其更完善", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修订", "is_correct": true, "explanation": "“修订”指修改订正书稿，与“作者正在……这本书”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃这本书”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于花果、叶子等，不用于书。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物吃东西，与作者处理书稿的语境不符。"}], "explanations": {"修订": "“修订”指修改订正书稿，与“作者正在……这本书”相符。", "吃": "搭配：“吃”的对象是食物，不能说“吃这本书”。", "摘": "搭配：“摘”用于花果、叶子等，不用于书。", "喂": "语义：“喂”指给人或动物吃东西，与作者处理书稿的语境不符。"}, "sentence_index": 0, "correct_answer": "修订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把坏了的自行车修订了一遍。", "explanation": "这里应该用〈修理〉。修订只用于书稿、文章、规章等文字，自行车等器物的修理要用〈修理〉。"}, {"text": "学校去年修订了教学楼。", "explanation": "这里应该用〈修缮〉。修订用于文字作品，房屋等建筑的修补要用〈修缮〉。"}, {"text": "文物修订得很好。", "explanation": "这里应该用〈修复〉。修订指修改文字作品，文物恢复原样要用〈修复〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修订", "is_correct": true, "explanation": "“修订”指修改订正文稿，与“花了三个月”的写作修改语境相符。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”用于食物，不能说“烤论文”。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”同样用于食物，与“论文”不搭配。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指切开，与“花了三个月”的写作修改语境不符。"}], "explanations": {"修订": "“修订”指修改订正文稿，与“花了三个月”的写作修改语境相符。", "烤": "搭配：“烤”用于食物，不能说“烤论文”。", "煎": "搭配：“煎”同样用于食物，与“论文”不搭配。", "切": "语义：“切”指切开，与“花了三个月”的写作修改语境不符。"}, "sentence_index": 6, "correct_answer": "修订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水管修订好了。", "explanation": "这里应该用〈修补〉。修订只用于书稿、文章等文字，水管等器物的补漏、修补要用〈修补〉。"}, {"text": "园丁修订好了花枝。", "explanation": "这里应该用〈修剪〉。修订指修改文字作品，修剪花枝要用〈修剪〉。"}, {"text": "电梯修订好了，可以坐了。", "explanation": "这里应该用〈维修〉。修订用于文字，电梯等机器设备的检修要用〈维修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "编辑修订了过这份报告。", "corrected_sentence": "编辑修订过这份报告。", "error_description": "错误：修订了过。正确：修订过。动词后的「了」与「过」不能同时使用，表示曾经修订应只用「过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她修订地很仔细。", "corrected_sentence": "她修订得很仔细。", "error_description": "“修订地很仔细”错误，应为“修订得很仔细”。描述修订的程度要用“得”引出补语，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
