INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两个国家。", "primary_collocate": null, "pronunciation": "liǎng guó", "ipa": "ljɑŋ˨˩ kwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "中国和日本，这两国我都想去。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的电影在这里很受欢迎。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的饭菜有的像，有的不像。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两国中间只隔着一座山。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国人民常常来往，关系很近。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的商人做了很多生意。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在两国都住过，会说两种话。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国开通了一条新的铁路。", "target_word": "两国", "complexity_tier": "T3", "furigana": "liǎng guó kāitōng le yī tiáo xīn de tiělù。", "sentence_source": "generated"}, {"text": "老师给我们讲了两国的历史。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的学生在网上交了朋友。", "target_word": "两国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指两个国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10b2f6b-6e2b-4fc3-8a1e-105a8b61b983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书店", "is_correct": false, "explanation": "语义：前文是“中国和日本”两个国家，“书店”不能与之并列作为想去的对象。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。这里指中国和日本，“这两国我都想去”语义通顺，符合语境。"}, {"text": "牙膏", "is_correct": false, "explanation": "搭配：“想去”的对象要是地方，“牙膏”不能与“想去”搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是小地方，不能与“中国和日本”并列作为想去的国家。"}], "explanations": {"书店": "语义：前文是“中国和日本”两个国家，“书店”不能与之并列作为想去的对象。", "两国": "两国：两个国家。这里指中国和日本，“这两国我都想去”语义通顺，符合语境。", "牙膏": "搭配：“想去”的对象要是地方，“牙膏”不能与“想去”搭配。", "花园": "语义：花园是小地方，不能与“中国和日本”并列作为想去的国家。"}, "sentence_index": 0, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两国都是我们班的同学。", "explanation": "这里应该用〈两个同学〉。“两国”指两个国家，不能用来指人。"}, {"text": "这座楼有两国。", "explanation": "这里应该用〈两层〉。“两国”指两个国家，不能用来数楼的层数，说楼的层要用“层”。"}, {"text": "北京和上海是两国。", "explanation": "这里应该用〈两座城市〉。北京和上海都是城市，不是国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“住过”的地方要能住人，汽车不是住的地方，与语境不符。"}, {"text": "两国", "is_correct": true, "explanation": "两国：两个国家。“她在两国都住过，会说两种话”指她在两个国家生活过，符合语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能住人，“住过”的地点不能是窗户。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“在……住过”的地点与“课本”不搭配。"}], "explanations": {"汽车": "语义：“住过”的地方要能住人，汽车不是住的地方，与语境不符。", "两国": "两国：两个国家。“她在两国都住过，会说两种话”指她在两个国家生活过，符合语境。", "窗户": "语义：窗户不能住人，“住过”的地点不能是窗户。", "课本": "搭配：“在……住过”的地点与“课本”不搭配。"}, "sentence_index": 6, "correct_answer": "两国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两国在操场上跑步。", "explanation": "这里应该用〈两个学生〉。“两国”指国家，国家不能在操场上跑步。"}, {"text": "我爸爸是两国。", "explanation": "这里不能用“两国”指人。“两国”只指两个国家，不能用来描述一个人。"}, {"text": "我把这两国放进了冰箱。", "explanation": "这里应该用〈两瓶〉。国家不能放进冰箱，“两国”只指两个国家，不能指两件东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个两国的音乐很好听。", "corrected_sentence": "这两国的音乐很好听。", "error_description": "错误在量词“个”。“两”是数词，“两国”前面直接用“这”即可，应说“这两国”，不说“这个两国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两国们的人民很友好。", "corrected_sentence": "这两国的人民很友好。", "error_description": "错误在“们”。“两国”是指国家的名词，后面不能加表示复数的“们”，应说“这两国的人民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复合", "is_correct": true, "explanation": "复合：恋人分手后重新和好、恢复关系，与“结束恋爱关系”相反。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚：指正式成为夫妻，是关系的发展，与分手不构成反义。"}, {"text": "相识", "is_correct": false, "explanation": "相识：指彼此认识，与分手不构成反义。"}, {"text": "约会", "is_correct": false, "explanation": "约会：指事先约好见面，与分手不构成反义。"}], "correct_answer": "复合", "explanations": {"复合": "复合：恋人分手后重新和好、恢复关系，与“结束恋爱关系”相反。", "结婚": "结婚：指正式成为夫妻，是关系的发展，与分手不构成反义。", "相识": "相识：指彼此认识，与分手不构成反义。", "约会": "约会：指事先约好见面，与分手不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和好", "is_correct": true, "explanation": "和好：恋人闹别扭后重新和好，与“结束恋爱关系”相对。"}, {"text": "照顾", "is_correct": false, "explanation": "照顾：指关心、料理他人，与分手不构成反义。"}, {"text": "同居", "is_correct": false, "explanation": "同居：指生活在一起，与分手不构成反义。"}, {"text": "求婚", "is_correct": false, "explanation": "求婚：指向对方提出结婚的请求，与分手不构成反义。"}], "correct_answer": "和好", "explanations": {"和好": "和好：恋人闹别扭后重新和好，与“结束恋爱关系”相对。", "照顾": "照顾：指关心、料理他人，与分手不构成反义。", "同居": "同居：指生活在一起，与分手不构成反义。", "求婚": "求婚：指向对方提出结婚的请求，与分手不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分手是两个人不再在一起了。", "primary_collocate": null, "pronunciation": "fēn shǒu", "ipa": "fən˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们昨天分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和女朋友分手三个月了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他们因为工作分手了。", "target_word": "分手", "complexity_tier": "T3", "furigana": "fēn shǒu", "sentence_source": "generated"}, {"text": "她不想分手，可是他很坚决。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分手以后，他们还是好朋友。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们为什么要分手？", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱了三年的两个人，最后还是分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提出分手，他一句话也没说。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈了五年恋爱，他们决定分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是常吵架，两个人就容易分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分手了", "label": "体标"}, {"form": "分过手", "label": "体标"}], "register": "口语", "sense_fingerprint": "恋人结束恋爱关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。"}, {"text": "分数", "is_correct": false, "explanation": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。"}, {"text": "分食", "is_correct": false, "explanation": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。"}, {"text": "分售", "is_correct": false, "explanation": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。"}, {"text": "分寸", "is_correct": false, "explanation": "分寸（fēn cùn）：第二个音节的声母、韵母和声调都不同，意思是说话做事的分寸。"}], "explanations": {"分手": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。", "分数": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。", "分食": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。", "分售": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。", "分寸": "分寸（fēn cùn）：第二个音节的声母、韵母和声调都不同，意思是说话做事的分寸。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指两人结束恋爱关系，与“他们昨天……了”相符。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：怀孕只能指女性，不能用“他们”作主语。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：出嫁指女子结婚后离开娘家，不能用于“他们”。"}, {"text": "登基", "is_correct": false, "explanation": "语域：登基指帝王即位，用在日常叙述里很不协调。"}], "explanations": {"分手": "正确：分手指两人结束恋爱关系，与“他们昨天……了”相符。", "怀孕": "语义：怀孕只能指女性，不能用“他们”作主语。", "出嫁": "搭配：出嫁指女子结婚后离开娘家，不能用于“他们”。", "登基": "语域：登基指帝王即位，用在日常叙述里很不协调。"}, "sentence_index": 0, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两块磁铁分手了。", "explanation": "这里的“分手”用于恋人等有感情关系的人，不能用于磁铁。这里应该用〈分离〉。"}, {"text": "人群在广场上分手了。", "explanation": "分手的主语是两个人（恋人），人群散开应该用〈散开〉，不用〈分手〉。"}, {"text": "两队在中场分手了，比分还是平的。", "explanation": "这里应该用〈休息〉。分手只用于两个人（恋人）结束关系，两队在中场休息时不能说分手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。"}, {"text": "分时", "is_correct": false, "explanation": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。"}, {"text": "分身", "is_correct": false, "explanation": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。"}, {"text": "分量", "is_correct": false, "explanation": "分量（fēn liàng）：第二个音节的声母、韵母和声调都不同，意思是重量或份量。"}], "explanations": {"分手": "分手（fēn shǒu）：两个人不再在一起，结束恋爱关系。", "分期": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。", "分时": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。", "分身": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。", "分量": "分量（fēn liàng）：第二个音节的声母、韵母和声调都不同，意思是重量或份量。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指两人结束恋爱关系，与“爱了三年的两个人，最后还是……了”相符。"}, {"text": "分娩", "is_correct": false, "explanation": "语义：分娩只能指女性生孩子，不能用于“两个人”。"}, {"text": "嫁", "is_correct": false, "explanation": "搭配：嫁只用于女性出嫁，不能说“两个人嫁了”。"}, {"text": "退位", "is_correct": false, "explanation": "语域：退位指帝王让出君位，用在恋爱叙述里很不协调。"}], "explanations": {"分手": "正确：分手指两人结束恋爱关系，与“爱了三年的两个人，最后还是……了”相符。", "分娩": "语义：分娩只能指女性生孩子，不能用于“两个人”。", "嫁": "搭配：嫁只用于女性出嫁，不能说“两个人嫁了”。", "退位": "语域：退位指帝王让出君位，用在恋爱叙述里很不协调。"}, "sentence_index": 6, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个好朋友因为一件小事分手了，之后再也不说话。", "explanation": "分手专指恋人结束恋爱关系，朋友之间闹翻应该用〈绝交〉，不用〈分手〉。"}, {"text": "小王一个人分手了，觉得很轻松。", "explanation": "分手需要两个人共同结束关系，主语只有一个人时不能用，这里应该用〈离开〉。"}, {"text": "这两只小狗分手了，各自去玩。", "explanation": "分手只用于恋爱中的人，小狗不能用，这里应该用〈分开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把男朋友分手了，很伤心。", "corrected_sentence": "她跟男朋友分手了，很伤心。", "error_description": "错误：“把男朋友分手了”；正确：“跟男朋友分手了”。分手是不及物动词，后面不能带宾语，也不能用把字句；表示与某人分手，要用介词“跟”引出对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上个月和男朋友分手着。", "corrected_sentence": "她上个月和男朋友分手了。", "error_description": "错误：“分手着”；正确：“分手了”。“分手”表示已经完成的结束关系，要用完成标记“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相聚", "is_correct": true, "explanation": "相聚：指团聚、见面，与分别、分手的意思相反。"}, {"text": "出发", "is_correct": false, "explanation": "出发：指动身启程，与分手不构成反义。"}, {"text": "研究", "is_correct": false, "explanation": "研究：指探讨问题，与分手没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：指动脑筋想问题，与分手没有反义关系。"}], "correct_answer": "相聚", "explanations": {"相聚": "相聚：指团聚、见面，与分别、分手的意思相反。", "出发": "出发：指动身启程，与分手不构成反义。", "研究": "研究：指探讨问题，与分手没有反义关系。", "思考": "思考：指动脑筋想问题，与分手没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
