INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分别；也指恋人结束关系。", "primary_collocate": null, "pronunciation": "fēn shǒu", "ipa": "fən˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们在车站分手，说好明年再见。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，同学们在校门口分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在路口分手，各回各家。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了机场，我们就要分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分手时，他送给我一本书。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人在门口分手，没有回头。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在这里分手，你往东，我往西。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵了很久，最后决定分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和男朋友因为不合适分手了。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业后，不少恋人选择分手。", "target_word": "分手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分手了", "label": "体标"}, {"form": "分过手", "label": "体标"}], "register": "口语", "sense_fingerprint": "人与人分开告别，也指恋人分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02d36763-8831-45a5-9b61-1e9a276bb895') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：人与人分开告别，也指恋人结束关系。"}, {"text": "分数", "is_correct": false, "explanation": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。"}, {"text": "分食", "is_correct": false, "explanation": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。"}, {"text": "分售", "is_correct": false, "explanation": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。"}, {"text": "分寸", "is_correct": false, "explanation": "分寸（fēn cùn）：第二个音节的声母、韵母和声调都不同，意思是说话做事的分寸。"}], "explanations": {"分手": "分手（fēn shǒu）：人与人分开告别，也指恋人结束关系。", "分数": "分数（fēn shù）：第二个音节 shǒu 与 shù 的韵母和声调都不同，意思是分数。", "分食": "分食（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调都不同，意思是分着吃。", "分售": "分售（fēn shòu）：shǒu（第三声）与 shòu（第四声）声调不同，意思是分开出售。", "分寸": "分寸（fēn cùn）：第二个音节的声母、韵母和声调都不同，意思是说话做事的分寸。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指人与人分开告别，与“说好明年再见”的语境相符。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：迎接是欢迎来人，与“说好明年再见”的告别语境相反。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：车站不是结婚的场所，“在车站结婚”与句中的告别情境不搭配。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：道歉指承认错误，不是车站告别的动作，与句意不符。"}], "explanations": {"分手": "正确：分手指人与人分开告别，与“说好明年再见”的语境相符。", "迎接": "语义：迎接是欢迎来人，与“说好明年再见”的告别语境相反。", "结婚": "搭配：车站不是结婚的场所，“在车站结婚”与句中的告别情境不搭配。", "道歉": "语义：道歉指承认错误，不是车站告别的动作，与句意不符。"}, "sentence_index": 0, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两张桌子在屋里分手了。", "explanation": "分手的主语是人，桌子不能分手，这里应该用〈分开〉。"}, {"text": "他一个人在车站分手了。", "explanation": "分手需要两方共同分别，主语只有一个人时不能说，这里应该用〈离开〉。"}, {"text": "人群在广场上分手了。", "explanation": "分手的主语是两方（两个人），人群散开应该用〈散开〉，不用〈分手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分手", "is_correct": true, "explanation": "分手（fēn shǒu）：人与人分开告别，也指恋人结束关系。"}, {"text": "分期", "is_correct": false, "explanation": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。"}, {"text": "分时", "is_correct": false, "explanation": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。"}, {"text": "分身", "is_correct": false, "explanation": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。"}, {"text": "分量", "is_correct": false, "explanation": "分量（fēn liàng）：第二个音节的声母、韵母和声调都不同，意思是重量或份量。"}], "explanations": {"分手": "分手（fēn shǒu）：人与人分开告别，也指恋人结束关系。", "分期": "分期（fēn qī）：第二个音节的声母、韵母和声调都不同，意思是分期付款。", "分时": "分时（fēn shí）：shǒu（第三声）与 shí（第二声）的韵母和声调不同，意思是按时间分段。", "分身": "分身（fēn shēn）：韵母和声调都不同，意思是分身、化身。", "分量": "分量（fēn liàng）：第二个音节的声母、韵母和声调都不同，意思是重量或份量。"}, "sentence_index": null, "correct_answer": "分手"}, "level_3": {"options": [{"text": "分手", "is_correct": true, "explanation": "正确：分手指人与人分开、各走各路，与“你往东，我往西”的方向相符。"}, {"text": "会合", "is_correct": false, "explanation": "语义：会合指会面到一起，与“你往东，我往西”的分开方向相反。"}, {"text": "会师", "is_correct": false, "explanation": "语域：会师多用于军队或队伍，此处语域不协调，且与方向矛盾。"}, {"text": "汇合", "is_correct": false, "explanation": "语义：汇合指水流或人群集中到一起，与“你往东，我往西”的方向矛盾。"}], "explanations": {"分手": "正确：分手指人与人分开、各走各路，与“你往东，我往西”的方向相符。", "会合": "语义：会合指会面到一起，与“你往东，我往西”的分开方向相反。", "会师": "语域：会师多用于军队或队伍，此处语域不协调，且与方向矛盾。", "汇合": "语义：汇合指水流或人群集中到一起，与“你往东，我往西”的方向矛盾。"}, "sentence_index": 6, "correct_answer": "分手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个老师在办公室里分手了，吵得很厉害。", "explanation": "这里应该用〈吵架〉。分手只表示分别或恋人结束关系，不能用来表示争吵。"}, {"text": "我和我自己分手了。", "explanation": "分手需要两个不同的人或两方，不能和自己分手，这里应该用〈分开〉。"}, {"text": "两个国家在谈判桌前分手了。", "explanation": "分手多用于人与人之间的关系，国家之间断绝往来应该用〈断交〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把机场分手，各自回家。", "corrected_sentence": "我们在机场分手，各自回家。", "error_description": "错误：“把机场分手”；正确：“在机场分手”。分手不能带宾语，也不能用把字句；表示地点要用介词“在”放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我他在路口分手，各自回家。", "corrected_sentence": "我跟他在路口分手，各自回家。", "error_description": "错误：“我他在路口分手”；正确：“我跟他在路口分手”。分手表示两方分开，涉及对方时要用“跟”引出，漏掉“跟”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d4a723-6bba-4caf-94c5-1b3eb93ee5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
