INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前进时要走的路，常指被挡住的前路。", "primary_collocate": null, "pronunciation": "qù lù", "ipa": "tɕʰy˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "一棵大树倒在路中间，挡住了我们的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的桥断了，车队没有了去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的大雪封住了登山队的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一群羊站在马路上，拦住了汽车的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水冲断了小桥，大家没有了去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察站在路口，不让那辆车往前走，挡住了它的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出手臂，拦住了我的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾太浓，司机看不清前面的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的河水很深，我们过不去，去路被挡住了。", "target_word": "去路", "complexity_tier": "T3", "furigana": "qián miàn de hé shuǐ hěn shēn, wǒ men guò bu qù, qù lù bèi dǎng zhù le", "sentence_source": "generated"}, {"text": "大石头滚下来，堵住了他们的去路。", "target_word": "去路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "前进时要走的路，常指被挡住的前路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95158, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "去路", "is_correct": true, "explanation": "去路：前进的道路，指被挡住的前路。"}, {"text": "目录", "is_correct": false, "explanation": "mù 与 qù 声母不同，mù lù 意思是“目录”，不是道路。"}, {"text": "速录", "is_correct": false, "explanation": "sù 与 qù 声母不同，sù lù 意思是“速录”，即用速记方式快速记录。"}, {"text": "护路", "is_correct": false, "explanation": "hù 与 qù 声母不同，hù lù 意思是“保护道路”。"}, {"text": "预录", "is_correct": false, "explanation": "yù 与 qù 声母不同，yù lù 意思是“预先录制”。"}], "explanations": {"去路": "去路：前进的道路，指被挡住的前路。", "目录": "mù 与 qù 声母不同，mù lù 意思是“目录”，不是道路。", "速录": "sù 与 qù 声母不同，sù lù 意思是“速录”，即用速记方式快速记录。", "护路": "hù 与 qù 声母不同，hù lù 意思是“保护道路”。", "预录": "yù 与 qù 声母不同，yù lù 意思是“预先录制”。"}, "sentence_index": null, "correct_answer": "去路"}, "level_3": {"options": [{"text": "去路", "is_correct": true, "explanation": "去路：前进要走的路，被大树挡住了，句意通顺。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是内心的感受，不能被大树挡住。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“挡住”后接有形的道路，不说“挡住了方向”。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程是学习内容，与倒在路上的大树无关。"}], "explanations": {"去路": "去路：前进要走的路，被大树挡住了，句意通顺。", "心情": "语义：心情是内心的感受，不能被大树挡住。", "方向": "搭配：“挡住”后接有形的道路，不说“挡住了方向”。", "课程": "语义：课程是学习内容，与倒在路上的大树无关。"}, "sentence_index": 0, "correct_answer": "去路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写作文时理清了去路，文章很通顺。", "explanation": "这里应该用〈思路〉。思路指思考问题的条理，去路指前进的道路，不能用来说文章的条理。"}, {"text": "我们沿着一座去路往前走。", "explanation": "这里应该用〈条〉。去路用“条”量，“座”用于桥、山等大型建筑或物体，不用于道路。"}, {"text": "这次旅行的去路是北京。", "explanation": "这里应该用〈去向〉。去向指要去的地方，去路指前往的道路，不能说“去路是北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去路", "is_correct": true, "explanation": "去路：拦住的是前进的路，句意通顺。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象的时段，不能用手臂拦住。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“拦住”后接的是人或道路这样的实体，不说“拦住方向”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，与伸手拦人的动作无关。"}], "explanations": {"去路": "去路：拦住的是前进的路，句意通顺。", "时间": "语义：时间是抽象的时段，不能用手臂拦住。", "方向": "搭配：“拦住”后接的是人或道路这样的实体，不说“拦住方向”。", "作业": "语义：作业是学习任务，与伸手拦人的动作无关。"}, "sentence_index": 6, "correct_answer": "去路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋大楼的去路在东西两边，你从哪边进都行。", "explanation": "这里应该用〈出口〉。出口指建筑的出入处，去路指前往的道路，不能用来说大楼的出入口。"}, {"text": "这道题很难，但他的去路很清楚，一步一步解了出来。", "explanation": "这里应该用〈思路〉。思路指思考问题的条理，去路不能指解题的思路。"}, {"text": "这把去路很长，我们走了一下午。", "explanation": "这里应该用〈条〉。去路用“条”量，“把”用于有柄的器具，不用于道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面有一座去路，被大石头堵住了。", "corrected_sentence": "前面有一条去路，被大石头堵住了。", "error_description": "“去路”的量词应为“条”，“座”用于桥、山等大型建筑或物体，不用于道路。错误形式是“一座去路”，正确形式是“一条去路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场大雪堵住了前面的一片去路，我们只好折回。", "corrected_sentence": "一场大雪堵住了前面的一条去路，我们只好折回。", "error_description": "“去路”的量词应为“条”，“片”多用于树叶、雪地等平面的东西，不用于道路。错误形式是“一片去路”，正确形式是“一条去路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
