INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某方面很有本事、有权势的人。", "primary_collocate": null, "pronunciation": "dà ná", "ipa": "ta˥˩ na˧˥", "syllable_count": 2, "sentences": [{"text": "他在这个行业里是个大拿，谁都得给他面子。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说新来的经理是上面的大拿，大家都很小心。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的生意，都由几位大拿说了算。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认识很多大拿，办什么事都很方便。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在村里，他是说话最有分量的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大拿一开口，下面的人都不敢出声。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要办成这件事，得先找到能做主的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小穷苦，后来成了地方上的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会上来了好几位大拿，气氛很紧张。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想得罪那位在行里有权势的大拿。", "target_word": "大拿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "在某方面有本事、有权势、说话有分量的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指有本事、有权势的人，与“谁都得给他面子”相符。"}, {"text": "学徒", "is_correct": false, "explanation": "语义：“学徒”指还在学艺、没有权势的人，与“谁都得给他面子”矛盾。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“游客”指旅游的人，不能说“在这个行业里是个游客”。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”只是搭车的人，没有权势，与“谁都得给他面子”矛盾。"}], "explanations": {"大拿": "正确。“大拿”指有本事、有权势的人，与“谁都得给他面子”相符。", "学徒": "语义：“学徒”指还在学艺、没有权势的人，与“谁都得给他面子”矛盾。", "游客": "搭配：“游客”指旅游的人，不能说“在这个行业里是个游客”。", "乘客": "语义：“乘客”只是搭车的人，没有权势，与“谁都得给他面子”矛盾。"}, "sentence_index": 0, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子是家里的大拿，谁都得给它让座。", "explanation": "这里把“大拿”用于椅子，指的不是人。“大拿”指某方面有权势、说了算的人，不能用来称呼家具。"}, {"text": "他是修车方面的大拿，什么毛病都能修好。", "explanation": "这里的“大拿”指在某件事上特别厉害的人，是另一义项；句中强调的是技术，而不是权势。"}, {"text": "这辆摩托车是村里的大拿，谁都得听它的。", "explanation": "这里把“大拿”用于摩托车，指的不是人。“大拿”指有权势的人，不能用来称呼交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指某方面有本事、有权势的人。"}, {"text": "大麻", "is_correct": false, "explanation": "“大麻”与“大拿”只有第二个音节的声母不同（m 与 n），意思是一种植物。"}, {"text": "打那", "is_correct": false, "explanation": "“打那”与“大拿”两个音节的声调都不同，意思是从那时起，属于口语词。"}, {"text": "打哪", "is_correct": false, "explanation": "“打哪”与“大拿”两个音节的声调都不同，意思是从哪里，是疑问表达。"}], "explanations": {"大拿": "正确。“大拿”指某方面有本事、有权势的人。", "大麻": "“大麻”与“大拿”只有第二个音节的声母不同（m 与 n），意思是一种植物。", "打那": "“打那”与“大拿”两个音节的声调都不同，意思是从那时起，属于口语词。", "打哪": "“打哪”与“大拿”两个音节的声调都不同，意思是从哪里，是疑问表达。"}, "sentence_index": null, "correct_answer": "大拿"}, "level_3": {"options": [{"text": "大拿", "is_correct": true, "explanation": "正确。“大拿”指有本事、有权势的人，与“能做主”相符。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：“旁观者”只看不管，不能做主，与“能做主的”矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”与这件事无关，没有决定权，与句意矛盾。"}, {"text": "病号", "is_correct": false, "explanation": "搭配：“病号”指生病的人，不能用于“能做主的……”这类身份说法。"}], "explanations": {"大拿": "正确。“大拿”指有本事、有权势的人，与“能做主”相符。", "旁观者": "语义：“旁观者”只看不管，不能做主，与“能做主的”矛盾。", "路人": "语义：“路人”与这件事无关，没有决定权，与句意矛盾。", "病号": "搭配：“病号”指生病的人，不能用于“能做主的……”这类身份说法。"}, "sentence_index": 6, "correct_answer": "大拿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子是家具大拿，用了十年还很结实。", "explanation": "“大拿”只指人，不能用来指家具。桌子结实应直接描述，不能称桌子为大拿。"}, {"text": "那辆卡车是运输大拿，跑得又稳又快。", "explanation": "“大拿”只指人，不能用来指车辆。卡车的性能应直接描述，不能用“大拿”来形容。"}, {"text": "这座房子是建筑大拿，住着很舒服。", "explanation": "“大拿”只指人，不能用来指建筑物。房子舒服与否应直接描述，不能称房子为大拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里这几位大拿们都很有分量。", "corrected_sentence": "村里这几位大拿都很有分量。", "error_description": "有“几位”修饰时，名词后不能再加“们”。应去掉“们”，说“这几位大拿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是村里一只有名的大拿。", "corrected_sentence": "他是村里一位有名的大拿。", "error_description": "“大拿”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对的东西）。正确的说法是“他是村里一位有名的大拿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一些人被选出来，一起去别的地方做事，他们就是一个队。", "primary_collocate": null, "pronunciation": "dài biǎo tuán", "ipa": "tai˥˩ piɑu˨˩˦ tʰuan˧˥", "syllable_count": 3, "sentences": [{"text": "学校派了一个代表团去参加比赛。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有三个人加入了代表团。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团坐火车去了上海。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个代表团要去外地学习。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组成代表团，一起去别的城市。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里选出一个代表团，去城里说明情况。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团的人都穿着白衬衫。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团今天早上坐船出发了。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是工人代表团里的一个人。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表团回来后，给大家讲了路上的事。", "target_word": "代表团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "代表團", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "代表团：选出来一起去外地办事的一队人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是练习题，不能被派去参加比赛。"}, {"text": "奖杯", "is_correct": false, "explanation": "搭配：“派”一般接人或团体，不能说派出奖杯。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能去参加比赛。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是为办事派出的一队人，可以“派去参加比赛”。"}], "explanations": {"作业": "语义：作业是练习题，不能被派去参加比赛。", "奖杯": "搭配：“派”一般接人或团体，不能说派出奖杯。", "书包": "语义：书包是装东西的袋子，不能去参加比赛。", "代表团": "正确：代表团是为办事派出的一队人，可以“派去参加比赛”。"}, "sentence_index": 0, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们全家组成一个代表团，去海边玩。", "explanation": "这里应该用〈旅游团〉。代表团是为会议或办事派出的团体，全家出游不用此词。"}, {"text": "我们班派了一个代表团去教室后面打扫卫生。", "explanation": "这里应该用〈小组〉。代表团是被选派到别处办事的团体，在教室后面打扫卫生应说〈小组〉。"}, {"text": "我们班派了一个代表团在教室里唱歌。", "explanation": "这里应该用〈合唱团〉。代表团是被选派到别处办事的团体，在教室里唱歌应说〈合唱团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子的人”说不通，桌子不是人或团体。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不能指一群穿衣服的人。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“……的人都”要求前面是人或团体，花园不能这样修饰。"}, {"text": "代表团", "is_correct": true, "explanation": "正确：代表团是由一群人组成的团体，“代表团的人”通顺。"}], "explanations": {"桌子": "语义：“桌子的人”说不通，桌子不是人或团体。", "窗户": "语义：窗户是墙上的开口，不能指一群穿衣服的人。", "花园": "搭配：“……的人都”要求前面是人或团体，花园不能这样修饰。", "代表团": "正确：代表团是由一群人组成的团体，“代表团的人”通顺。"}, "sentence_index": 6, "correct_answer": "代表团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是一个代表团。", "explanation": "这里应该用〈代表〉。代表团是由几个人组成的团体，只有一个人时应说〈代表〉。"}, {"text": "我们班的代表团每周五在教室里活动。", "explanation": "这里应该用〈社团〉。代表团是为会议或访问临时派出的，不是长期活动的组织。"}, {"text": "这个代表团是我们几个朋友自发组织的，平时一起打牌。", "explanation": "这里应该用〈小圈子〉。代表团是被选出来去办事的团体，几个朋友自发组织、平时打牌的聚会不属于这一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校派了一双代表团去外地。", "corrected_sentence": "学校派了一个代表团去外地。", "error_description": "错误：一双代表团。正确：一个代表团。〈双〉用于成对的东西，代表团是一群人组成的团体，应用〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "代表团们昨天下午坐车回来了。", "corrected_sentence": "代表团昨天下午坐车回来了。", "error_description": "错误：代表团们。正确：代表团。〈代表团〉是集体名词，不能再加〈们〉表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
