INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95187, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "把自己所有的力气都用上。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他全力推开了那扇门。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李全力向终点跑去。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我全力拉住了那只狗。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她全力把箱子搬上楼。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始后，他全力往前冲。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子全力踢了一脚球。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你全力推一下这辆车。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他全力跳起来，摸到了篮球架。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟全力游到了对岸。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人全力拉着绳子不放手。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全力以赴", "label": "复合"}, {"form": "尽全力", "label": "复合"}], "register": "中性", "sense_fingerprint": "把身体的力气全部用上做动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指把力气全部用上，与“推开了那扇门”相符。"}, {"text": "全速", "is_correct": false, "explanation": "语义：“全速”说的是速度最快，与句中用力推门的意思不符。"}, {"text": "轻轻", "is_correct": false, "explanation": "语义：“轻轻”说动作很轻，与句中全力推门的意思相反。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”说速度慢，与句中用力推门的意思相反。"}], "explanations": {"全力": "正确。“全力”指把力气全部用上，与“推开了那扇门”相符。", "全速": "语义：“全速”说的是速度最快，与句中用力推门的意思不符。", "轻轻": "语义：“轻轻”说动作很轻，与句中全力推门的意思相反。", "慢慢": "语义：“慢慢”说速度慢，与句中用力推门的意思相反。"}, "sentence_index": 0, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们全力为客户服务，让大家满意。", "explanation": "这里的“全力”指竭尽所能地去做事，是另一义项；句中谈的是服务，而不是用尽身体的力气。"}, {"text": "这次公司全力为他提供了资金和资源。", "explanation": "这里的“全力”指竭尽所能地支持或帮助，是另一义项；句中并没有用力的动作。"}, {"text": "这箱子全力搬上楼。", "explanation": "“全力”需要有人主动使劲，箱子不能使出力气。应说明是谁把箱子搬上楼的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指竭尽全部力气，与“请你……推一下这辆车”的语境相符。"}, {"text": "尽情", "is_correct": false, "explanation": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“推一下”这样的动作。"}, {"text": "轻轻", "is_correct": false, "explanation": "语义：“轻轻”说动作很轻，与请对方全力推车的意思相反。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不在意，与请对方用力帮忙的意思矛盾。"}], "explanations": {"全力": "正确。“全力”指竭尽全部力气，与“请你……推一下这辆车”的语境相符。", "尽情": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“推一下”这样的动作。", "轻轻": "语义：“轻轻”说动作很轻，与请对方全力推车的意思相反。", "随便": "语义：“随便”表示不在意，与请对方用力帮忙的意思矛盾。"}, "sentence_index": 6, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全力打了个喷嚏，把大家都吓了一跳。", "explanation": "“全力”表示有意竭尽力气去做，打喷嚏是不由自主的动作，不能用“全力”。"}, {"text": "她全力睡着了，一直到天亮。", "explanation": "“全力”表示有意竭尽力气去做，睡着是不由自主的状态，不能用“全力”。"}, {"text": "他全力发抖，冷得说不出话。", "explanation": "“全力”表示有意竭尽力气去做，发抖是身体不由自主的反应，不能用“全力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很全力搬起了那张桌子。", "corrected_sentence": "他全力搬起了那张桌子。", "error_description": "副词“全力”前面不能加程度副词“很”。应去掉“很”，说“他全力搬起了那张桌子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的全力推开了那扇窗。", "corrected_sentence": "他全力推开了那扇窗。", "error_description": "副词“全力”前面不能加结构助词“的”，“的”在这里使“全力”变成了名词性成分。应去掉“的”，说“他全力推开了那扇窗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
