INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "竭尽所能地去做某件事，多指帮助、支持或完成任务。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们会全力帮助你。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司全力支持这个计划。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在全力抢救病人。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了考试，她全力准备了三个月。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师全力教我们学汉语。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家全力工作，希望按时完成。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察全力寻找丢失的孩子。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说会全力照顾好父母。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队全力争取这场比赛的胜利。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我一定全力去做。", "target_word": "全力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全力以赴", "label": "复合"}, {"form": "尽全力", "label": "复合"}], "register": "中性", "sense_fingerprint": "竭尽所能地去帮助、支持或完成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指竭尽所能，与“我们会……帮助你”的承诺相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”说的是次数少，与“会……帮助你”的承诺不符。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不认真，与郑重的承诺不符。"}, {"text": "尽情", "is_correct": false, "explanation": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“帮助”。"}], "explanations": {"全力": "正确。“全力”指竭尽所能，与“我们会……帮助你”的承诺相符。", "偶尔": "语义：“偶尔”说的是次数少，与“会……帮助你”的承诺不符。", "随便": "语义：“随便”表示不认真，与郑重的承诺不符。", "尽情": "搭配：“尽情”多修饰玩乐、表演等，不能修饰“帮助”。"}, "sentence_index": 0, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他全力跳起来，摸到了天花板。", "explanation": "这里的“全力”表示用尽身体的力气，属于另一义项；本词此处指竭尽所能地去做某事。"}, {"text": "我全力抬起了那块石头。", "explanation": "这里的“全力”表示用尽身体的力气，属于另一义项；本词此处指竭尽所能地去做某事。"}, {"text": "她全力打了个哈欠，大家都笑了。", "explanation": "“全力”表示有意竭尽所能，打哈欠是不由自主的动作，不能用“全力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全力", "is_correct": true, "explanation": "正确。“全力”指竭尽所能，与“警察……寻找丢失的孩子”的紧迫语境相符。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带去做，与“寻找丢失的孩子”作为主要任务的意思矛盾。"}, {"text": "随手", "is_correct": false, "explanation": "搭配：“随手”多修饰顺手拿、写之类的动作，不能修饰“寻找”。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”说态度随便，与警方寻找孩子的紧迫性不符。"}], "explanations": {"全力": "正确。“全力”指竭尽所能，与“警察……寻找丢失的孩子”的紧迫语境相符。", "顺便": "语义：“顺便”表示附带去做，与“寻找丢失的孩子”作为主要任务的意思矛盾。", "随手": "搭配：“随手”多修饰顺手拿、写之类的动作，不能修饰“寻找”。", "随意": "语义：“随意”说态度随便，与警方寻找孩子的紧迫性不符。"}, "sentence_index": 6, "correct_answer": "全力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全力晕倒在了路边。", "explanation": "“全力”表示有意竭尽所能去做，晕倒是不由自主的状态，不能用“全力”。"}, {"text": "她全力发烧了一整夜。", "explanation": "“全力”表示有意竭尽所能去做，发烧是身体的状态，不能用“全力”。"}, {"text": "他全力打了个寒战。", "explanation": "“全力”表示有意竭尽所能去做，打寒战是身体不由自主的反应，不能用“全力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们会全力了配合你的工作。", "corrected_sentence": "我们会全力配合你的工作。", "error_description": "助词“了”不能直接加在副词“全力”后面，应去掉“了”。错误形式是“全力了配合”，正确形式是“全力配合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很全力准备了很多天。", "corrected_sentence": "他全力准备了很多天。", "error_description": "副词“全力”前面不能加程度副词“很”。应去掉“很”，说“他全力准备了很多天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
