INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存款时，银行在一定期限内付给储户的利息与本金的比率。", "primary_collocate": null, "pronunciation": "lì lǜ", "ipa": "li˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "银行的利率今年比去年高。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行存款的利率是多少？", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率高的银行，我多存一些钱。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把钱存在利率高的银行。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每家银行的利率都不一样。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过今天银行的利率吗？", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利率太低，存钱不赚钱。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天都看银行的利率。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月银行的利率没有变。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸问银行的利率是多少。", "target_word": "利率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存款利率", "label": "复合"}, {"form": "银行利率", "label": "复合"}], "register": "中性", "sense_fingerprint": "存款时银行多付给你的钱的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高指人或动物的身高，银行没有身高，句子不通。"}, {"text": "利率", "is_correct": true, "explanation": "正确。利率是利息与本金的比率，银行的利率可以逐年变化。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄说“大”或“小”，不说“高”。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的费用，与银行无关。"}], "explanations": {"身高": "语义：身高指人或动物的身高，银行没有身高，句子不通。", "利率": "正确。利率是利息与本金的比率，银行的利率可以逐年变化。", "年龄": "搭配：年龄说“大”或“小”，不说“高”。", "学费": "语义：学费是学生交给学校的费用，与银行无关。"}, "sentence_index": 0, "correct_answer": "利率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔存款的利率是一百元。", "explanation": "这里应该用〈利息〉。利率是比例，要说百分之几；说具体的钱数要用利息。"}, {"text": "这种商品的利率是百分之十。", "explanation": "这里应该用〈税率〉。利率说的是存款或贷款的利息比例，商品的比例要用税率。"}, {"text": "我们班这次的利率比上次高。", "explanation": "这里应该用〈及格率〉。利率只指利息与本金之比，考试通过的比例要用及格率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体重量，与存钱赚钱无关。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩是考试或工作的结果，不能解释存钱不赚钱。"}, {"text": "利率", "is_correct": true, "explanation": "正确。利率太低，存款的利息就少，所以存钱不赚钱。"}, {"text": "年份", "is_correct": false, "explanation": "搭配：年份说“早”或“晚”，不说“低”。"}], "explanations": {"体重": "语义：体重是人的身体重量，与存钱赚钱无关。", "成绩": "语义：成绩是考试或工作的结果，不能解释存钱不赚钱。", "利率": "正确。利率太低，存款的利息就少，所以存钱不赚钱。", "年份": "搭配：年份说“早”或“晚”，不说“低”。"}, "sentence_index": 6, "correct_answer": "利率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美元对人民币的利率今年升了。", "explanation": "这里应该用〈汇率〉。利率是存贷款的利息比例，两种货币之间的兑换比例要用汇率。"}, {"text": "这台机器的利率很高。", "explanation": "这里应该用〈效率〉。利率只用于利息，机器做事快慢的比例要用效率。"}, {"text": "这条路的公交发车利率很高。", "explanation": "这里应该用〈频率〉。利率指利息比例，发车的密度要用频率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "银行的利率今年提高到了三个。", "corrected_sentence": "银行的利率今年提高到了百分之三。", "error_description": "错误：“三个”是用来数人或物的量词短语，不能表示利率的数值；利率应说“百分之三”。正确：银行的利率今年提高到了百分之三。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "银行推出的这只利率很有吸引力。", "corrected_sentence": "银行推出的这种利率很有吸引力。", "error_description": "错误：“只”是用于动物或小件物品的量词，不用于利率；利率应用量词“种”。正确：银行推出的这种利率很有吸引力。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
