INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一个东西分成两份里的一份。", "primary_collocate": null, "pronunciation": "bàn gè", "ipa": "pan˥˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我把苹果切开，给妹妹半个。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有半个西瓜，你吃吧。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把月饼分成两块，自己吃了半个。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个面包太大了，我只吃半个。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我半个橙子，谢谢。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把鸡蛋切开，每个人都得到半个。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还剩半个梨，留给爸爸吧。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕只剩下半个了，快来吃。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着半个馒头，坐在门口。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人分一个西瓜，一人半个。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一个东西分成两份后的其中一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "半个", "is_correct": true, "explanation": "半个：切开后的一份，正好是一半，句意通顺。"}, {"text": "三个", "is_correct": false, "explanation": "语义：苹果已经切开，只能给一份，给三个说不通。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，苹果不用“根”量。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长或成条的东西，苹果不用“条”量。"}], "explanations": {"半个": "半个：切开后的一份，正好是一半，句意通顺。", "三个": "语义：苹果已经切开，只能给一份，给三个说不通。", "一根": "搭配：“根”用于细长的东西，苹果不用“根”量。", "一条": "搭配：“条”用于细长或成条的东西，苹果不用“条”量。"}, "sentence_index": 0, "correct_answer": "半个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他撕下了半个纸。", "explanation": "这里应该用“半张”。纸用“张”量，不用“个”。"}, {"text": "我买了半个书。", "explanation": "这里应该用“半本”。书用“本”量，不用“个”；“半个”多用于可以切开的东西。"}, {"text": "他喝了半个水。", "explanation": "这里应该用“半杯”。水用“杯”“瓶”等容器量，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半个", "is_correct": true, "explanation": "半个：剩下的一半，句意通顺。"}, {"text": "一双", "is_correct": false, "explanation": "搭配：“双”用于成对的东西如鞋袜，不用于梨。"}, {"text": "一台", "is_correct": false, "explanation": "搭配：“台”用于机器等，不能用来数梨。"}, {"text": "一次", "is_correct": false, "explanation": "语义：“次”表示次数，不能用来计量梨。"}], "explanations": {"半个": "半个：剩下的一半，句意通顺。", "一双": "搭配：“双”用于成对的东西如鞋袜，不用于梨。", "一台": "搭配：“台”用于机器等，不能用来数梨。", "一次": "语义：“次”表示次数，不能用来计量梨。"}, "sentence_index": 6, "correct_answer": "半个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她买了半个衣服。", "explanation": "这里应该用“半件”。衣服用“件”量，不用“个”。"}, {"text": "她吃了半个饭。", "explanation": "这里应该用“半碗”。饭用“碗”量，不用“个”。"}, {"text": "妈妈买了半个床。", "explanation": "这里应该用“半张”。床用“张”量，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把半个个橘子分给弟弟。", "corrected_sentence": "我把半个橘子分给弟弟。", "error_description": "量词重复：“半个”后面多加了一个“个”，应去掉多余的“个”。错误形式是“半个个橘子”，正确形式是“半个橘子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把半条月饼留给我。", "corrected_sentence": "妈妈把半个月饼留给我。", "error_description": "量词搭配错误：“条”用于细长的东西，不用来计量月饼，应改为“个”。错误形式是“半条月饼”，正确形式是“半个月饼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
