INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95194, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一个的一半。", "primary_collocate": null, "pronunciation": "bàn gè", "ipa": "pan˥˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我只等了你半个小时，不算太久。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去北京出差半个月了。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半个班的同学都去看电影了。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半个学校的人都认识他。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只花了半个上午就做完了作业。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟睡了半个下午，现在才起床。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在这里住过半个世纪。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了半个晚上的书。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天锻炼半个钟头。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半个月前，我们在公园里见过面。", "target_word": "半个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量上相当于一个的一半，常用在时间或集体名词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "半个", "is_correct": true, "explanation": "半个：一小时的一半，即半小时，句意通顺。"}, {"text": "半条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不用来量小时。"}, {"text": "半只", "is_correct": false, "explanation": "语义：“只”指单个的动物或器物，与时间的长度不相干。"}, {"text": "半块", "is_correct": false, "explanation": "搭配：“块”指成块的东西，不用来量时间。"}], "explanations": {"半个": "半个：一小时的一半，即半小时，句意通顺。", "半条": "搭配：“条”用于细长的东西，不用来量小时。", "半只": "语义：“只”指单个的动物或器物，与时间的长度不相干。", "半块": "搭配：“块”指成块的东西，不用来量时间。"}, "sentence_index": 0, "correct_answer": "半个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在屋里挂了半个画。", "explanation": "这里应该用“半幅”。画用“幅”量，不用“个”。"}, {"text": "妈妈买了半个鞋。", "explanation": "这里应该用“半只”。鞋要成双计量，单只用“只”，不用“个”。"}, {"text": "我借了半个书。", "explanation": "这里应该用“半本”。书用“本”量，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半个", "is_correct": true, "explanation": "半个：半个世纪即五十年，句意通顺。"}, {"text": "半代", "is_correct": false, "explanation": "搭配：“代”指一代人，不与“世纪”搭配，应说“半个世纪”。"}, {"text": "半页", "is_correct": false, "explanation": "搭配：“页”用于书页等，不用来量年代。"}, {"text": "半场", "is_correct": false, "explanation": "语义：“场”指一场比赛或演出，与世纪的长度不相符。"}], "explanations": {"半个": "半个：半个世纪即五十年，句意通顺。", "半代": "搭配：“代”指一代人，不与“世纪”搭配，应说“半个世纪”。", "半页": "搭配：“页”用于书页等，不用来量年代。", "半场": "语义：“场”指一场比赛或演出，与世纪的长度不相符。"}, "sentence_index": 6, "correct_answer": "半个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了半个裤子。", "explanation": "这里应该用“半条”。裤子用“条”量，不用“个”。"}, {"text": "她喝了半个汤。", "explanation": "这里应该用“半碗”。汤用“碗”量，不用“个”。"}, {"text": "他写了半个信。", "explanation": "这里应该用“半封”。信用“封”量，不用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只陪了你半个个钟头，就得走了。", "corrected_sentence": "我只陪了你半个钟头，就得走了。", "error_description": "量词重复：“半个”后面多加了一个“个”，应去掉多余的“个”。错误形式是“半个个钟头”，正确形式是“半个钟头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在厨房忙了半条早上，才把饭做好。", "corrected_sentence": "妈妈在厨房忙了半个早上，才把饭做好。", "error_description": "量词搭配错误：“条”不用于计量时间，应改为“个”。错误形式是“半条早上”，正确形式是“半个早上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
