INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发声演唱歌曲。", "primary_collocate": null, "pronunciation": "chàng gē", "ipa": "ʈʂʰaŋ˥˩ kɤ˥", "syllable_count": 2, "sentences": [{"text": "他很喜欢唱歌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们晚上一起去唱歌吧。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的声音很好听。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在台上唱歌，大家都鼓掌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会唱歌，只会听歌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末朋友们一起唱歌、跳舞。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一边做饭一边唱歌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当歌手，每天都练习唱歌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会唱歌？", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在教室里唱歌。", "target_word": "唱歌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "唱过歌", "label": "体标"}, {"form": "唱了歌", "label": "体标"}], "register": "中性", "sense_fingerprint": "演唱歌曲的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d1bb30-3dc3-4c0f-bcac-045bc503ad42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": true, "explanation": "这里要填“唱歌”，与“很喜欢”搭配，指喜欢演唱歌曲。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：没有人喜欢摔倒，与“很喜欢”矛盾。"}, {"text": "生病", "is_correct": false, "explanation": "语义：没有人喜欢生病，句意不通。"}, {"text": "挨骂", "is_correct": false, "explanation": "搭配：“挨骂”表示被骂，不能与“很喜欢”搭配表示喜欢做的事。"}], "explanations": {"唱歌": "这里要填“唱歌”，与“很喜欢”搭配，指喜欢演唱歌曲。", "摔倒": "语义：没有人喜欢摔倒，与“很喜欢”矛盾。", "生病": "语义：没有人喜欢生病，句意不通。", "挨骂": "搭配：“挨骂”表示被骂，不能与“很喜欢”搭配表示喜欢做的事。"}, "sentence_index": 0, "correct_answer": "唱歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子在台上唱歌，大家都鼓掌。", "explanation": "这里应该用〈响〉。“唱歌”只指人用嘴发声演唱，椅子发出的响声不能说唱歌。"}, {"text": "小明在台上唱数学，大家都鼓掌。", "explanation": "这里应该用〈讲〉。“唱”指演唱歌曲，不能用于数学，讲解数学要用“讲”。"}, {"text": "小明在台上唱了一幅画，大家都鼓掌。", "explanation": "这里应该用〈展示〉。“唱”不能用于画作，展示画作要用“展示”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": true, "explanation": "这里要填“唱歌”，与“一边做饭一边”搭配，指做饭时同时唱歌。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：做饭时不能同时去游泳，与句意矛盾。"}, {"text": "爬山", "is_correct": false, "explanation": "语义：做饭时不能同时去爬山，句意不通。"}, {"text": "打架", "is_correct": false, "explanation": "配价：“打架”需要与对方发生关系，单独说“一边做饭一边打架”不完整。"}], "explanations": {"唱歌": "这里要填“唱歌”，与“一边做饭一边”搭配，指做饭时同时唱歌。", "游泳": "语义：做饭时不能同时去游泳，与句意矛盾。", "爬山": "语义：做饭时不能同时去爬山，句意不通。", "打架": "配价：“打架”需要与对方发生关系，单独说“一边做饭一边打架”不完整。"}, "sentence_index": 6, "correct_answer": "唱歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在教室里唱歌，却一点声音也没有。", "explanation": "这里应该用〈比划〉。“唱歌”必须发出声音，没有声音的动作不能说唱歌。"}, {"text": "孩子们在教室里唱了作业，大家都很认真。", "explanation": "这里应该用〈做〉。“唱”一般指演唱歌曲，做作业要用“做”。"}, {"text": "教室里的黑板在唱歌，孩子们都很开心。", "explanation": "这里应该用〈响〉。“唱歌”的主语必须是能发声演唱的人，黑板发出的响声不能说唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他唱歌得很好。", "corrected_sentence": "他唱歌唱得很好。", "error_description": "错误：“唱歌得很好”；正确：“唱歌唱得很好”。表示动作做得怎么样，要用“动词＋得＋补语”，动词“唱”需要重复一次，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们唱歌过很多次。", "corrected_sentence": "我们唱过很多次。", "error_description": "错误：“唱歌过”；正确：“唱过”。“唱歌”是动宾结构，体标“过”不能插在“唱”和“歌”之间，应直接接在动词“唱”后，宾语“歌”可省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '211c7e03-6b6a-4629-a270-6209694dec67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
