INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "象征一个国家的旗帜。", "primary_collocate": null, "pronunciation": "guó qí", "ipa": "kuo˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "国旗是一个国家的象征。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到国旗，他心里很激动。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗的颜色有特别的意义。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了国旗的故事。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们保护国旗，就像保护自己的国家。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗上的星星代表什么？", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱国歌的时候，大家看着国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外看见国旗，我觉得很亲切。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的国旗。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为国旗的设计想了很久。", "target_word": "国旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一面国旗", "label": "量词"}], "register": "中性", "sense_fingerprint": "象征国家的旗帜，带有尊严与情感意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指象征国家的旗帜。"}, {"text": "国籍", "is_correct": false, "explanation": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。"}, {"text": "活期", "is_correct": false, "explanation": "huóqī 与 guóqí 第一个音节声母不同（h 与 g），第二个音节声调也不同（qī 第一声，qí 第二声），意思是活期存款。"}, {"text": "贵气", "is_correct": false, "explanation": "guìqì 与 guóqí 两个音节声调都不同，意思是高贵的气质。"}, {"text": "锅气", "is_correct": false, "explanation": "guōqì 与 guóqí 两个音节声调都不同，意思是锅里烹饪时产生的香气。"}], "explanations": {"国旗": "正确。国旗 guó qí 指象征国家的旗帜。", "国籍": "guójí 与 guóqí 第二个音节声母不同（j 与 q），声调相同，意思是国籍。", "活期": "huóqī 与 guóqí 第一个音节声母不同（h 与 g），第二个音节声调也不同（qī 第一声，qí 第二声），意思是活期存款。", "贵气": "guìqì 与 guóqí 两个音节声调都不同，意思是高贵的气质。", "锅气": "guōqì 与 guóqí 两个音节声调都不同，意思是锅里烹饪时产生的香气。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗是国家的象征，是一个国家的旗帜。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，与“一个国家的象征”不相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日常用品，不能象征一个国家。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：“老铁”是口语网络用语，不适合用在这样的书面定义句中。"}], "explanations": {"国旗": "正确。国旗是国家的象征，是一个国家的旗帜。", "课本": "语义：课本是学习用的书，与“一个国家的象征”不相符。", "雨伞": "语义：雨伞是日常用品，不能象征一个国家。", "老铁": "语域：“老铁”是口语网络用语，不适合用在这样的书面定义句中。"}, "sentence_index": 0, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "升旗时，大家一起唱起了国旗。", "explanation": "这里应该用〈国歌〉。唱的是国歌，国旗是用来升、挂、举的旗子，不能用“唱”。"}, {"text": "这个图案是我们学校的国旗，象征着校风。", "explanation": "这里应该用〈标志〉。“国旗”只指国家的旗子，学校的图案应该称为“标志”。"}, {"text": "我买了一辆国旗，挂在了窗口。", "explanation": "这里应该用〈面〉。国旗的量词是“面”，“辆”用于车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。国旗 guó qí 指象征国家的旗帜。"}, {"text": "过期", "is_correct": false, "explanation": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。"}, {"text": "国际", "is_correct": false, "explanation": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。"}, {"text": "过气", "is_correct": false, "explanation": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。"}, {"text": "国企", "is_correct": false, "explanation": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}], "explanations": {"国旗": "正确。国旗 guó qí 指象征国家的旗帜。", "过期": "guòqī 与 guóqí 两个音节声调都不同，意思是超过期限。", "国际": "guójì 与 guóqí 第二个音节声母与声调都不同（j 与 q，第四声与第二声），意思是国际。", "过气": "guòqì 与 guóqí 两个音节声调都不同，意思是过时、不再流行。", "国企": "guóqǐ 与 guóqí 第二个音节声调不同（qǐ 第三声，qí 第二声），意思是国有企业。"}, "sentence_index": null, "correct_answer": "国旗"}, "level_3": {"options": [{"text": "国旗", "is_correct": true, "explanation": "正确。唱国歌时，大家通常看着国旗。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能用于“声音”，声音是看不见的。"}, {"text": "作业", "is_correct": false, "explanation": "语义：唱国歌是庄严的场合，“作业”与此场合不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱与唱国歌的庄重场合不相关，句子无法成立。"}], "explanations": {"国旗": "正确。唱国歌时，大家通常看着国旗。", "声音": "搭配：“看”不能用于“声音”，声音是看不见的。", "作业": "语义：唱国歌是庄严的场合，“作业”与此场合不符。", "冰箱": "语义：冰箱与唱国歌的庄重场合不相关，句子无法成立。"}, "sentence_index": 6, "correct_answer": "国旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直是我们班的国旗，大家都很敬佩他。", "explanation": "这里应该用〈旗帜〉。“旗帜”可以比喻某个群体的代表，“国旗”只指国家的旗子，不能用来比喻人。"}, {"text": "他每次升旗都负责担任国旗。", "explanation": "这里应该用〈旗手〉。担任职务的是人，“国旗”是物，不能担任。"}, {"text": "桌上摆着一朵国旗。", "explanation": "这里应该用〈面〉。“朵”用于花、云等，国旗应该用“面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把国旗好叠了。", "corrected_sentence": "他把国旗叠好了。", "error_description": "错误形式是“好叠”，正确形式是“叠好”。结果补语“好”要紧跟在动词之后，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把国旗挂的很高。", "corrected_sentence": "妈妈把国旗挂得很高。", "error_description": "错误形式是“挂的很高”，正确形式是“挂得很高”。表示程度的补语要用助词“得”连接在动词之后，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
