INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比地面高一点的平平的台子。", "primary_collocate": null, "pronunciation": "dì tái", "ipa": "ti˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我家客厅有一个地台，孩子喜欢坐在上面玩。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卧室里的地台比地面高一点，上面放着床垫。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间茶室做了一个地台，大家脱鞋坐在上面喝茶。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗边搭了一个木头地台，当书桌用。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小地台上摆着一盆花。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从地台上跳下来，高兴地笑了。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地台只有一步高，老人也能走上去。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把地台擦干净，再铺上一块毯子。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日式房间里常有一个矮矮的地台，可以睡觉。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地台下面有抽屉，可以放被子和衣服。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地台床", "label": "复合"}], "register": "中性", "sense_fingerprint": "室内比地面略高的平台子，可坐可睡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，孩子不能坐在上面玩。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是冷藏食物的电器，不能让孩子坐着玩。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台是比地面高的平台，孩子可以坐在上面玩。"}, {"text": "水池", "is_correct": false, "explanation": "搭配：“坐在……上面”要求可以承重的平台或家具，水池不能这样用。"}], "explanations": {"窗户": "语义：窗户是墙上的开口，孩子不能坐在上面玩。", "冰箱": "语义：冰箱是冷藏食物的电器，不能让孩子坐着玩。", "地台": "正确：地台是比地面高的平台，孩子可以坐在上面玩。", "水池": "搭配：“坐在……上面”要求可以承重的平台或家具，水池不能这样用。"}, "sentence_index": 0, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位新来的地台很能干，大家都很喜欢他。", "explanation": "这里应该用〈同事〉。地台是比地面高一点的平台，不能指人，也不能用来称呼一个人。"}, {"text": "我每天用这个地台刷牙。", "explanation": "这里应该用〈洗漱台〉。地台是比地面高一点的平台，不能用来刷牙，刷牙应在〈洗漱台〉前。"}, {"text": "他用地台把门撑开了。", "explanation": "这里应该用〈门挡〉。地台是平台，不能用来撑门，撑门要用〈门挡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柜子", "is_correct": false, "explanation": "语义：柜子不是可以走上去的平台，“走上去”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不能说“走上去”。"}, {"text": "电视", "is_correct": false, "explanation": "配价：“走上去”需要一个能让人踩上去的地方，电视不能承受人走上去。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台高出地面一步，老人能走上去。"}], "explanations": {"柜子": "语义：柜子不是可以走上去的平台，“走上去”说不通。", "雨伞": "语义：雨伞是遮雨的用具，不能说“走上去”。", "电视": "配价：“走上去”需要一个能让人踩上去的地方，电视不能承受人走上去。", "地台": "正确：地台高出地面一步，老人能走上去。"}, "sentence_index": 6, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在客厅铺了一块地台。", "explanation": "这里应该用〈地毯〉。地台是固定在室内的平台，不是能铺在地上的东西。"}, {"text": "我们坐地台去了火车站。", "explanation": "这里应该用〈地铁〉。地台是固定的平台，不能用来乘坐前往别处。"}, {"text": "他喝了一杯地台。", "explanation": "这里应该用〈茶〉。地台是家具式的平台，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卧室的窗边有一双地台，可以放书。", "corrected_sentence": "卧室的窗边有一个地台，可以放书。", "error_description": "错误：一双地台。正确：一个地台。〈双〉用于成对的东西，地台是单个的平台，应用〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把地台们擦了一遍。", "corrected_sentence": "我们把地台擦了一遍。", "error_description": "错误：地台们。正确：地台。〈地台〉是单个的平台，不能加〈们〉表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
