INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高出地面的平台。", "primary_collocate": null, "pronunciation": "dì tái", "ipa": "ti˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "广场中间有一个很大的地台，歌手在上面唱歌。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在仓库里做了一个水泥地台，用来放机器。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览馆的地台上放着一辆红色的汽车。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站在教室前面的地台上讲课。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨天院子里会积水，所以他们建了一个地台。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地台高出地面三十厘米，上面可以摆很多东西。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爬上地台，看远处的表演。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在地台四周围了一圈栏杆。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈队在公园的地台上练习跳舞。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市门口的地台上堆着很多水果。", "target_word": "地台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "水泥地台", "label": "复合"}], "register": "中性", "sense_fingerprint": "户外或场所中高出地面、用来站立或摆放东西的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树", "is_correct": false, "explanation": "语义：树长在地上，不是可以站人的平台，歌手不能站在树上唱歌。"}, {"text": "喷泉", "is_correct": false, "explanation": "语义：喷泉是喷水的景观，不能让歌手站在上面唱歌。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台是高出地面的平台，歌手可以站在上面唱歌。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“在……上面唱歌”要求可以站人的场所，雕像不能这样用。"}], "explanations": {"树": "语义：树长在地上，不是可以站人的平台，歌手不能站在树上唱歌。", "喷泉": "语义：喷泉是喷水的景观，不能让歌手站在上面唱歌。", "地台": "正确：地台是高出地面的平台，歌手可以站在上面唱歌。", "雕像": "搭配：“在……上面唱歌”要求可以站人的场所，雕像不能这样用。"}, "sentence_index": 0, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "顾客站在地台前面付钱。", "explanation": "这里应该用〈柜台〉。付钱要在柜台或收银处，地台是高出地面的平台，不用于收钱。"}, {"text": "公园的地台里装满了水，孩子们在里面游泳。", "explanation": "这里应该用〈游泳池〉。地台是高出地面的平台，不能装水让人游泳，应说〈游泳池〉。"}, {"text": "他是我们班的地台，每天带大家练跑步。", "explanation": "这里应该用〈队长〉。地台是平台，不能指人，也不能当职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，孩子不能爬上去。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云在天上，孩子无法爬上云朵。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“爬上”的对象要能承受人的体重，墨水是液体，不能爬上。"}, {"text": "地台", "is_correct": true, "explanation": "正确：地台可以爬上去，孩子们能在上面看表演。"}], "explanations": {"书包": "语义：书包是装东西的袋子，孩子不能爬上去。", "云朵": "语义：云在天上，孩子无法爬上云朵。", "墨水": "搭配：“爬上”的对象要能承受人的体重，墨水是液体，不能爬上。", "地台": "正确：地台可以爬上去，孩子们能在上面看表演。"}, "sentence_index": 6, "correct_answer": "地台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着一个地台去学校。", "explanation": "这里应该用〈自行车〉。地台是固定的平台，不能骑着去学校。"}, {"text": "这个地台上挂着一幅画。", "explanation": "这里应该用〈墙〉。画要挂在墙上，地台是地面上的平台，不能挂画。"}, {"text": "后院的地台里装满了垃圾。", "explanation": "这里应该用〈垃圾桶〉。地台是平台，不是能装东西的容器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人们在地台们上下棋。", "corrected_sentence": "老人们在地台上下棋。", "error_description": "错误：地台们。正确：地台。〈地台〉不能加〈们〉表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一双地台上放着几箱水果。", "corrected_sentence": "一个地台上放着几箱水果。", "error_description": "错误：一双地台。正确：一个地台。〈双〉用于成对的东西，地台是单个的平台，应用〈个〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
