INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非常喜欢一个人，觉得他特别了不起。", "primary_collocate": null, "pronunciation": "chóng bài", "ipa": "ʈʂʰʊŋ˧˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟特别崇拜他的哥哥。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明崇拜足球明星，每天都看他的比赛。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她崇拜那个歌手，买了他所有的唱片。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹崇拜她的老师，说老师最了不起。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩们都崇拜会打篮球的人。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他崇拜着自己的爷爷。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候崇拜过一个电影明星。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太崇拜这位作家了。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们崇拜他，因为他什么都会。", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么崇拜他？", "target_word": "崇拜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "崇拜了", "label": "体标"}, {"form": "崇拜过", "label": "体标"}, {"form": "崇拜着", "label": "体标"}, {"form": "崇拜者", "label": "复合"}], "register": "中性", "sense_fingerprint": "非常喜欢某人并觉得他了不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0d37556-ca61-4ff7-a93f-9f6b9ec23596') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崇拜", "is_correct": true, "explanation": "“崇拜”表示非常喜欢并觉得了不起，与“弟弟特别”和“他的哥哥”搭配，符合句意。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”针对机器或设备，不能用来修理一个人。"}, {"text": "核对", "is_correct": false, "explanation": "搭配：“核对”的对象是数据或信息，不能说“核对他的哥哥”。"}, {"text": "讲解", "is_correct": false, "explanation": "配价：“讲解”要以讲解的内容作宾语，不能直接以人作宾语。"}], "explanations": {"崇拜": "“崇拜”表示非常喜欢并觉得了不起，与“弟弟特别”和“他的哥哥”搭配，符合句意。", "维修": "语义：“维修”针对机器或设备，不能用来修理一个人。", "核对": "搭配：“核对”的对象是数据或信息，不能说“核对他的哥哥”。", "讲解": "配价：“讲解”要以讲解的内容作宾语，不能直接以人作宾语。"}, "sentence_index": 0, "correct_answer": "崇拜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很崇拜这碗汤。", "explanation": "这里应该用〈喜欢〉。崇拜表示非常喜欢并觉得了不起，对一碗汤只能说喜欢。"}, {"text": "我很崇拜他的运气。", "explanation": "这里应该用〈羡慕〉。崇拜是敬佩某人，对别人的运气只能说羡慕。"}, {"text": "我很崇拜那家商店的价格。", "explanation": "这里应该用〈满意〉。崇拜针对人或值得敬佩的事，对商店的价格只能说满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崇拜", "is_correct": true, "explanation": "“崇拜”表示非常喜欢并觉得了不起，与“我小时候”和“一个电影明星”搭配，符合句意。"}, {"text": "检修", "is_correct": false, "explanation": "语义：“检修”的对象是设备或机器，不能用于一位明星。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”用于破损的物件，不能用来表示对人的喜爱与敬佩。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆或飞机，不能说“驾驶一个电影明星”。"}], "explanations": {"崇拜": "“崇拜”表示非常喜欢并觉得了不起，与“我小时候”和“一个电影明星”搭配，符合句意。", "检修": "语义：“检修”的对象是设备或机器，不能用于一位明星。", "修补": "语义：“修补”用于破损的物件，不能用来表示对人的喜爱与敬佩。", "驾驶": "搭配：“驾驶”的对象是车辆或飞机，不能说“驾驶一个电影明星”。"}, "sentence_index": 6, "correct_answer": "崇拜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很崇拜这条裙子的颜色。", "explanation": "这里应该用〈欣赏〉。崇拜表示非常喜欢并觉得了不起，对裙子的颜色只能说欣赏。"}, {"text": "我很崇拜那段时光。", "explanation": "这里应该用〈怀念〉。崇拜是对人的敬佩，对过去的时光只能说怀念。"}, {"text": "我很崇拜他的难处。", "explanation": "这里应该用〈体谅〉。崇拜是敬佩，对别人的难处要说体谅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来不崇拜了他。", "corrected_sentence": "我从来不崇拜他。", "error_description": "体标错误：「从来不」表示长期不这样做，不能与「了」同用。应去掉「了」，说「我从来不崇拜他」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我崇拜过他。", "corrected_sentence": "明天我崇拜他。", "error_description": "时态错误：“过”表示已经经历过的动作，不能用于将来的“明天”，应去掉“过”，说“明天我崇拜他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a1ab578-e040-454d-bfb1-7b7d4afb444a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
