INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理一座城市大事小事的地方。", "primary_collocate": null, "pronunciation": "shì zhèng fǔ", "ipa": "ʂɻ̩˥˩ ʈʂɤŋ˥˩ fu˨˩˦", "syllable_count": 3, "sentences": [{"text": "市政府就在这条路的北边。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁去市政府。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府门口有一个大广场。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府旁边是一家银行。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市政府附近租了房子。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府的楼很高，也很新。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，市政府怎么走？", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末市政府前面有很多人。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸每天走路去市政府上班。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从学校到市政府要二十分钟。", "target_word": "市政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市政府大楼", "label": "复合"}], "register": "正式", "sense_fingerprint": "城市管理者办公的地点和建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a001c3af-04ca-47d3-b9a6-71ae202c95e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不是建筑或场所，不能位于路的北边。"}, {"text": "市政府", "is_correct": true, "explanation": "正确。市政府是城市行政机关的办公地点，可以位于某条路的北边。"}, {"text": "学期", "is_correct": false, "explanation": "搭配：学期是时间，不能用“在……北边”表示位置。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是地点，不能位于路的北边。"}], "explanations": {"空气": "语义：空气不是建筑或场所，不能位于路的北边。", "市政府": "正确。市政府是城市行政机关的办公地点，可以位于某条路的北边。", "学期": "搭配：学期是时间，不能用“在……北边”表示位置。", "天气": "语义：天气是气象状况，不是地点，不能位于路的北边。"}, "sentence_index": 0, "correct_answer": "市政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去市政府借了几本书。", "explanation": "这里应该用〈图书馆〉。市政府是办公的地方，借书要去图书馆。"}, {"text": "我们走进了一只市政府。", "explanation": "这里应该用〈座〉。市政府作为建筑要用“座”或“栋”，“只”是用于动物或小东西的量词。"}, {"text": "这条路上有一个大市政府，很多人在那里买菜。", "explanation": "这里应该用〈市场〉。市政府是办公的地方，买菜要去市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不是可以前往的地点，不能问“怎么走”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“怎么走”用于地点或路线，不能用于心情。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是活动，不是地点，不能问“怎么走”。"}, {"text": "市政府", "is_correct": true, "explanation": "正确。问“怎么走”问的是去某个地点的路线，市政府是地点。"}], "explanations": {"工资": "语义：工资是报酬，不是可以前往的地点，不能问“怎么走”。", "心情": "搭配：“怎么走”用于地点或路线，不能用于心情。", "考试": "语义：考试是活动，不是地点，不能问“怎么走”。", "市政府": "正确。问“怎么走”问的是去某个地点的路线，市政府是地点。"}, "sentence_index": 6, "correct_answer": "市政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天去市政府上课。", "explanation": "这里应该用〈学校〉。市政府是行政机关，不是上课的地方，上课要去学校。"}, {"text": "周末我们去市政府吃饭。", "explanation": "这里应该用〈餐厅〉。市政府是办公的地方，吃饭要去餐厅。"}, {"text": "我妈妈昨天去市政府看病。", "explanation": "这里应该用〈医院〉。市政府不提供诊疗，看病要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只市政府很大。", "corrected_sentence": "那座市政府很大。", "error_description": "错误：“只”是用于动物或小东西的量词，不能用来数建筑；市政府作为建筑应说“座”。正确：那座市政府很大。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈在一张市政府工作。", "corrected_sentence": "我妈妈在市政府工作。", "error_description": "错误：“张”用于平面的东西，不能用来数机关；“一张”不应放在“市政府”前。正确：我妈妈在市政府工作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26c9eb25-9e0e-44fe-9dd4-5fd0cdbcab10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
