INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写着花了多少钱的小本子或记录。", "primary_collocate": null, "pronunciation": "zhàng", "ipa": "ʈʂɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他有一本账，每天都写花了多少钱。", "target_word": "账", "complexity_tier": "T3", "furigana": "tā yǒu yì běn zhàng, měi tiān dōu xiě huā le duōshao qián", "sentence_source": "generated"}, {"text": "这本账上写着我每天花的钱。", "target_word": "账", "complexity_tier": "T3", "furigana": "zhè běn zhàng shàng xiě zhe wǒ měi tiān huā de qián", "sentence_source": "generated"}, {"text": "妈妈每个月都在账上写下买菜的钱。", "target_word": "账", "complexity_tier": "T3", "furigana": "mā ma měi gè yuè dōu zài zhàng shàng xiě xià mǎi cài de qián", "sentence_source": "generated"}, {"text": "你看一下账，这个月花了多少？", "target_word": "账", "complexity_tier": "T3", "furigana": "nǐ kàn yí xià zhàng, zhè ge yuè huā le duōshao", "sentence_source": "generated"}, {"text": "爸爸每天晚上记账，写下花的钱。", "target_word": "账", "complexity_tier": "T3", "furigana": "bà ba měi tiān wǎnshang jì zhàng, xiě xià huā de qián", "sentence_source": "generated"}, {"text": "他丢了那本账，不知道花了多少钱。", "target_word": "账", "complexity_tier": "T3", "furigana": "tā diū le nà běn zhàng, bù zhī dào huā le duōshao qián", "sentence_source": "generated"}, {"text": "小王的账上写着买书三十块。", "target_word": "账", "complexity_tier": "T3", "furigana": "Xiǎo Wáng de zhàng shàng xiě zhe mǎi shū sānshí kuài", "sentence_source": "generated"}, {"text": "这个小本子是我的账，每笔花费都写在里面。", "target_word": "账", "complexity_tier": "T3", "furigana": "zhè ge xiǎo běn zi shì wǒ de zhàng, měi bǐ huāfèi dōu xiě zài lǐmiàn", "sentence_source": "generated"}, {"text": "她翻开账，看看上个月买了什么。", "target_word": "账", "complexity_tier": "T3", "furigana": "tā fān kāi zhàng, kànkan shàng ge yuè mǎi le shénme", "sentence_source": "generated"}, {"text": "我想看看你的账，知道钱花在哪儿。", "target_word": "账", "complexity_tier": "T3", "furigana": "wǒ xiǎng kànkan nǐ de zhàng, zhīdào qián huā zài nǎr", "sentence_source": "generated"}], "morphological_forms": [{"form": "賬", "label": "繁体"}, {"form": "一本账", "label": "量词"}, {"form": "记账", "label": "复合"}], "register": "口语", "sense_fingerprint": "记着每天花了多少钱的小本子或记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95223, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "账", "is_correct": true, "explanation": "正确：zhàng，即本词条的读音与释义。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是上升、增加。"}, {"text": "章", "is_correct": false, "explanation": "zhāng（第一声）与 zhàng（第四声）声调不同，意思是章节、印章。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}, {"text": "张", "is_correct": false, "explanation": "zhāng（第一声）与 zhàng 声调不同，意思是张开，也是量词。"}, {"text": "掌", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàng 声调不同，意思是手掌。"}], "explanations": {"账": "正确：zhàng，即本词条的读音与释义。", "涨": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是上升、增加。", "章": "zhāng（第一声）与 zhàng（第四声）声调不同，意思是章节、印章。", "站": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。", "张": "zhāng（第一声）与 zhàng 声调不同，意思是张开，也是量词。", "掌": "zhǎng（第三声）与 zhàng 声调不同，意思是手掌。"}, "sentence_index": null, "correct_answer": "账"}, "level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：地图记录路线和地点，不记每天花的钱，与“写花了多少钱”不符。"}, {"text": "账", "is_correct": true, "explanation": "正确：账是记录钱款的本子，与“每天都写花了多少钱”相符。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典收录词条和释义，不会每天写花销。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：钱包一般用“个”，不说“一本钱包”，也不用来写账。"}], "explanations": {"地图": "语义：地图记录路线和地点，不记每天花的钱，与“写花了多少钱”不符。", "账": "正确：账是记录钱款的本子，与“每天都写花了多少钱”相符。", "词典": "语义：词典收录词条和释义，不会每天写花销。", "钱包": "搭配：钱包一般用“个”，不说“一本钱包”，也不用来写账。"}, "sentence_index": 0, "correct_answer": "账"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一只账，专门记每天的花销。", "explanation": "这里应该用〈本〉。账是记账的本子，量词用本，不用只（只多用于动物等）。"}, {"text": "医生每天都要看病人的体温账。", "explanation": "这里应该用〈记录〉。账只指钱款收支的账目，体温等数据要说记录，不能说账。"}, {"text": "我每天都在账上安排工作。", "explanation": "这里应该用〈日程〉。账是钱款的账目，安排工作要用日程，不能写在账上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95223, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "账", "is_correct": true, "explanation": "正确：zhàng，即本词条的读音与释义。"}, {"text": "长", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是生长、长大。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是战斗。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}], "explanations": {"账": "正确：zhàng，即本词条的读音与释义。", "长": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是生长、长大。", "战": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是战斗。", "站": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}, "sentence_index": null, "correct_answer": "账"}, "level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用书，不会记买书花了多少钱。"}, {"text": "账", "is_correct": true, "explanation": "正确：账是记录钱款的本子，与“写着买书三十块”相符。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：作文是文章，“写着买书三十块”的记账用途不搭。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片只写姓名和联系方式，不记买书花销。"}], "explanations": {"课本": "语义：课本是学习用书，不会记买书花了多少钱。", "账": "正确：账是记录钱款的本子，与“写着买书三十块”相符。", "作文": "搭配：作文是文章，“写着买书三十块”的记账用途不搭。", "名片": "语义：名片只写姓名和联系方式，不记买书花销。"}, "sentence_index": 6, "correct_answer": "账"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包里有一把账，写着每天的花销。", "explanation": "这里应该用〈本〉。账是本子，量词用本，不用把（把多用于有柄的东西）。"}, {"text": "我在银行开了一个账，存了一千块。", "explanation": "这里应该用〈账户〉。银行的户头叫账户，账指记录钱款的账目，不能这样用。"}, {"text": "他每天晚上都写账，记下当天的心情。", "explanation": "这里应该用〈日记〉。账只记钱款的收支，记录心情要用日记，不能说账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上都账记，把花的钱写下来。", "corrected_sentence": "我每天晚上都记账，把花的钱写下来。", "error_description": "离合词语序错误：“记账”是动宾式，不能说“账记”，应说“记账”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想看看你的一把账，知道钱花在哪儿。", "corrected_sentence": "我想看看你的一本账，知道钱花在哪儿。", "error_description": "量词错误：账是本子，应说“一本账”，不说“一把账”（把多用于有柄的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
