INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记录钱物出入的账目。", "primary_collocate": null, "pronunciation": "zhàng", "ipa": "ʈʂɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "公司每个月都要查账。", "target_word": "账", "complexity_tier": "T3", "furigana": "gōngsī měi gè yuè dōu yào chá zhàng", "sentence_source": "generated"}, {"text": "这笔账我算不清楚。", "target_word": "账", "complexity_tier": "T3", "furigana": "zhè bǐ zhàng wǒ suàn bu qīngchu", "sentence_source": "generated"}, {"text": "小店的老板每天晚上都记账。", "target_word": "账", "complexity_tier": "T3", "furigana": "xiǎo diàn de lǎo bǎn měi tiān wǎnshang dōu jì zhàng", "sentence_source": "generated"}, {"text": "账上的钱和你说的不一样。", "target_word": "账", "complexity_tier": "T3", "furigana": "zhàng shàng de qián hé nǐ shuō de bù yí yàng", "sentence_source": "generated"}, {"text": "会计在核对这个月的账。", "target_word": "账", "complexity_tier": "T3", "furigana": "kuàijì zài héduì zhè ge yuè de zhàng", "sentence_source": "generated"}, {"text": "他每天花多少钱，账上都写得很清楚。", "target_word": "账", "complexity_tier": "T3", "furigana": "tā měi tiān huā duōshao qián, zhàng shàng dōu xiě de hěn qīngchu", "sentence_source": "generated"}, {"text": "年底了，大家都忙着算账。", "target_word": "账", "complexity_tier": "T3", "furigana": "nián dǐ le, dàjiā dōu máng zhe suàn zhàng", "sentence_source": "generated"}, {"text": "上个月的账已经算清楚了。", "target_word": "账", "complexity_tier": "T3", "furigana": "shàng ge yuè de zhàng yǐjīng suàn qīngchu le", "sentence_source": "generated"}, {"text": "妻子把家里的账管得很好。", "target_word": "账", "complexity_tier": "T3", "furigana": "qīzi bǎ jiā lǐ de zhàng guǎn de hěn hǎo", "sentence_source": "generated"}, {"text": "这家店的账很清楚，每笔钱都有记录。", "target_word": "账", "complexity_tier": "T3", "furigana": "zhè jiā diàn de zhàng hěn qīngchu, měi bǐ qián dōu yǒu jìlù", "sentence_source": "generated"}], "morphological_forms": [{"form": "賬", "label": "繁体"}, {"form": "一笔账", "label": "量词"}, {"form": "算账", "label": "复合"}], "register": "中性", "sense_fingerprint": "钱物进出的账目，可以记、算、查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "账", "is_correct": true, "explanation": "正确：zhàng，即本词条的读音与释义。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是上升、增加。"}, {"text": "章", "is_correct": false, "explanation": "zhāng（第一声）与 zhàng（第四声）声调不同，意思是章节、印章。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}, {"text": "张", "is_correct": false, "explanation": "zhāng（第一声）与 zhàng 声调不同，意思是张开，也是量词。"}], "explanations": {"账": "正确：zhàng，即本词条的读音与释义。", "涨": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是上升、增加。", "章": "zhāng（第一声）与 zhàng（第四声）声调不同，意思是章节、印章。", "站": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。", "张": "zhāng（第一声）与 zhàng 声调不同，意思是张开，也是量词。"}, "sentence_index": null, "correct_answer": "账"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，公司不会每月去查作业。"}, {"text": "账", "is_correct": true, "explanation": "正确：账是钱物出入的账目，公司每月要查的正是这个。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学生用书，与公司查账无关。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“查”多用于账目、资料，不说“查节目”。"}], "explanations": {"作业": "语义：作业是学生的功课，公司不会每月去查作业。", "账": "正确：账是钱物出入的账目，公司每月要查的正是这个。", "课本": "语义：课本是学生用书，与公司查账无关。", "节目": "搭配：“查”多用于账目、资料，不说“查节目”。"}, "sentence_index": 0, "correct_answer": "账"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只账我算不清楚，每笔钱都对不上。", "explanation": "这里应该用〈笔〉。账目按笔算，量词用笔，不用只（只多用于动物等）。"}, {"text": "他这次考试的账很高。", "explanation": "这里应该用〈分数〉。账指钱物的账目，考试得分要说分数，不能说账。"}, {"text": "我的账这个月增加了三公斤。", "explanation": "这里应该用〈体重〉。账指钱物的账目，身体的重量要说体重，不能说账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "账", "is_correct": true, "explanation": "正确：zhàng，即本词条的读音与释义。"}, {"text": "长", "is_correct": false, "explanation": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是生长、长大。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是战斗。"}, {"text": "站", "is_correct": false, "explanation": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}], "explanations": {"账": "正确：zhàng，即本词条的读音与释义。", "长": "zhǎng（第三声）与 zhàng（第四声）声调不同，意思是生长、长大。", "战": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是战斗。", "站": "zhàn 与 zhàng 只有韵母不同（an 与 ang），意思是站立。"}, "sentence_index": null, "correct_answer": "账"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“算”的对象是账目、数字，天气不需要年底去算。"}, {"text": "账", "is_correct": true, "explanation": "正确：年底大家忙着算的是账目，与“算”搭配。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“算”的对象是账目、数字，不是名字。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“算”可搭配账、数、题，不搭配房间。"}], "explanations": {"天气": "语义：“算”的对象是账目、数字，天气不需要年底去算。", "账": "正确：年底大家忙着算的是账目，与“算”搭配。", "名字": "语义：“算”的对象是账目、数字，不是名字。", "房间": "搭配：“算”可搭配账、数、题，不搭配房间。"}, "sentence_index": 6, "correct_answer": "账"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这副账我算不清楚，每笔钱都对不上。", "explanation": "这里应该用〈笔〉。账目按笔算，量词用笔，不用副（副多用于成套的东西）。"}, {"text": "这台账上记着每笔钱，很清楚。", "explanation": "这里应该用〈笔〉。账目按笔计，量词用笔，不用台（台多用于机器）。"}, {"text": "这笔存款每年都会产生账。", "explanation": "这里应该用〈利息〉。存款产生的收益叫利息，账是账目，不能说产生账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月底大家都忙着账算。", "corrected_sentence": "这个月底大家都忙着算账。", "error_description": "离合词语序错误：“算账”是动宾式，不能说“账算”，应说“算账”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月的一把账已经算清楚了。", "corrected_sentence": "上个月的一笔账已经算清楚了。", "error_description": "量词错误：账目按笔计，应说“一笔账”，不说“一把账”（把多用于有柄的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
