INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "跟着老师学本领的人。", "primary_collocate": null, "pronunciation": "dì zi", "ipa": "ti˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "她是一位著名画家的弟子，学画画已经五年了。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老木匠的弟子做出了漂亮的桌子。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是京剧名师的弟子。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅很喜欢这个爱学习的弟子。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王拜了一位书法家做老师，成了他的弟子。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生的弟子们都学会了他的手艺。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位琴师的弟子在音乐会上演奏了一首曲子。", "target_word": "弟子", "complexity_tier": "T3", "furigana": "zhè wèi qín shī de dì zi zài yīn yuè huì shàng yǎn zòu le yì shǒu qǔ zi", "sentence_source": "generated"}, {"text": "他的弟子学得很快，一年就会做菜了。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位厨师有两个弟子，都在饭店里工作。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为那位舞蹈家的弟子，向她学跳舞。", "target_word": "弟子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大弟子", "label": "复合"}, {"form": "入室弟子", "label": "复合"}], "register": "中性", "sense_fingerprint": "跟随老师学习手艺、技艺或艺术的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95225, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弟子", "is_correct": true, "explanation": "正确答案：dì zi，指跟随老师学本领的人。"}, {"text": "地址", "is_correct": false, "explanation": "dì zhǐ 与 dì zi 第二音节声母不同（zh 与 z），意思是住址，不是弟子。"}, {"text": "笛子", "is_correct": false, "explanation": "dí zi 与 dì zi 第一音节声调不同（第二声与第四声），意思是笛子。"}, {"text": "底子", "is_correct": false, "explanation": "dǐ zi 与 dì zi 第一音节声调不同（第三声），意思是底子，指基础。"}], "explanations": {"弟子": "正确答案：dì zi，指跟随老师学本领的人。", "地址": "dì zhǐ 与 dì zi 第二音节声母不同（zh 与 z），意思是住址，不是弟子。", "笛子": "dí zi 与 dì zi 第一音节声调不同（第二声与第四声），意思是笛子。", "底子": "dǐ zi 与 dì zi 第一音节声调不同（第三声），意思是底子，指基础。"}, "sentence_index": null, "correct_answer": "弟子"}, "level_3": {"options": [{"text": "弟子", "is_correct": true, "explanation": "正确：“弟子”指跟随老师学手艺的人，与“著名画家”“学画画”相符。"}, {"text": "作品", "is_correct": false, "explanation": "语义：“作品”是物，不能指人，“她是……的作品”句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不能用来说明一个人跟随画家学画的身份。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是物品，不能指学画画的人，与句意不符。"}], "explanations": {"弟子": "正确：“弟子”指跟随老师学手艺的人，与“著名画家”“学画画”相符。", "作品": "语义：“作品”是物，不能指人，“她是……的作品”句意不通。", "身材": "体貌：“身材”指外形，不能用来说明一个人跟随画家学画的身份。", "颜料": "语义：“颜料”是物品，不能指学画画的人，与句意不符。"}, "sentence_index": 0, "correct_answer": "弟子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司里有五百名弟子。", "explanation": "这里应该用〈员工〉。弟子指跟随师父学习的人，不指公司里工作的人。"}, {"text": "这把伞是我的弟子，我每天都带着。", "explanation": "这里应该用〈伞〉。弟子指跟随师父学习的人，不指伞这类物品。"}, {"text": "景区门口摆满了弟子，都在卖纪念品。", "explanation": "这里应该用〈小贩〉。弟子指跟随师父学习的人，不指做买卖的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弟子", "is_correct": true, "explanation": "正确：“弟子”是人，能在音乐会上演奏，符合句意。"}, {"text": "合同", "is_correct": false, "explanation": "语义：“合同”是文件，不能在音乐会上演奏曲子。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是装东西的箱包，不能充当“演奏”的施事，句意不通。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“菜”不是人，也不能在音乐会上演奏。"}], "explanations": {"弟子": "正确：“弟子”是人，能在音乐会上演奏，符合句意。", "合同": "语义：“合同”是文件，不能在音乐会上演奏曲子。", "行李": "语义：“行李”是装东西的箱包，不能充当“演奏”的施事，句意不通。", "菜": "语义：“菜”不是人，也不能在音乐会上演奏。"}, "sentence_index": 6, "correct_answer": "弟子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器少了一个弟子，需要换一个新的。", "explanation": "这里应该用〈零件〉。弟子指跟随师父学习的人，不指机器上的部件。"}, {"text": "桌子上放着两个弟子，都是空的。", "explanation": "这里应该用〈盘子〉。弟子指跟随师父学习的人，不指盘子这类器皿。"}, {"text": "车厢里堆着很多弟子，都是行李。", "explanation": "这里应该用〈包裹〉。弟子指跟随师父学习的人，不指行李或包裹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几个弟子们跟着老木匠学做家具。", "corrected_sentence": "几个弟子跟着老木匠学做家具。", "error_description": "“几个”表示数量，后面不能再加“们”。应说“几个弟子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家收了一只弟子，每周教他画画。", "corrected_sentence": "这位画家收了一个弟子，每周教他画画。", "error_description": "“弟子”指人，量词应用“个”。“只”多用于动物，不能用于指人的“弟子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
