INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把小块的东西合在一起，变成一个大的。", "primary_collocate": null, "pronunciation": "pīn", "ipa": "pʰin˥", "syllable_count": 1, "sentences": [{"text": "弟弟用积木拼了一座小房子。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子碎了，怎么也拼不好。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把两张桌子拼在一起吧。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把碎纸片一块一块拼起来。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了一个下午拼这张地图。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这几块木板拼成一个书架。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在桌上拼着一辆小汽车。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小块布拼起来，就是一条被子。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四块小地毯拼在一起，正好铺满房间。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拼了很久，还差最后一块。", "target_word": "拼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拼了", "label": "体标"}, {"form": "拼着", "label": "体标"}, {"form": "拼过", "label": "体标"}, {"form": "拼图", "label": "复合"}, {"form": "拼接", "label": "复合"}], "register": "中性", "sense_fingerprint": "把小块的东西拼合成一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拼", "is_correct": true, "explanation": "正确。拼 pīn 指把小块的东西合在一起。"}, {"text": "品", "is_correct": false, "explanation": "pǐn（第三声）与 pīn（第一声）声调不同，意思是物品、品质。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 pīn（第一声）声调不同，意思是频率、频繁。"}, {"text": "平", "is_correct": false, "explanation": "píng（第二声）与 pīn 韵母与声调都不同（ing 与 in），意思是平坦。"}, {"text": "攀", "is_correct": false, "explanation": "pān（第一声）与 pīn 韵母不同（an 与 in），声调相同，意思是攀登。"}], "explanations": {"拼": "正确。拼 pīn 指把小块的东西合在一起。", "品": "pǐn（第三声）与 pīn（第一声）声调不同，意思是物品、品质。", "频": "pín（第二声）与 pīn（第一声）声调不同，意思是频率、频繁。", "平": "píng（第二声）与 pīn 韵母与声调都不同（ing 与 in），意思是平坦。", "攀": "pān（第一声）与 pīn 韵母不同（an 与 in），声调相同，意思是攀登。"}, "sentence_index": null, "correct_answer": "拼"}, "level_3": {"options": [{"text": "拼", "is_correct": true, "explanation": "正确。拼：把小块的积木合在一起，搭成一座房子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：积木是玩具，不能吃，也不能用“吃”把积木变成房子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱不能把积木变成房子，句子不成立。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能与“一座小房子”搭配，房子不是用来写的。"}], "explanations": {"拼": "正确。拼：把小块的积木合在一起，搭成一座房子。", "吃": "语义：积木是玩具，不能吃，也不能用“吃”把积木变成房子。", "唱": "语义：唱不能把积木变成房子，句子不成立。", "写": "搭配：“写”不能与“一座小房子”搭配，房子不是用来写的。"}, "sentence_index": 0, "correct_answer": "拼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯果汁是我刚拼好的。", "explanation": "这里应该用〈榨〉。果汁是榨出来的，“拼”指把小块的东西合成一个整体，不能用于液体。"}, {"text": "她每天花半小时拼茶。", "explanation": "这里应该用〈喝〉。喝茶要用“喝”，“拼”指把小块的东西合成一个整体，不能用于饮用。"}, {"text": "她把衣服一件件拼进了箱子。", "explanation": "这里应该用〈装〉。把衣服放进箱子应该用“装”，“拼”指把小块的东西合成整体，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95235, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拼", "is_correct": true, "explanation": "正确。拼 pīn 指把小块的东西合在一起。"}, {"text": "宾", "is_correct": false, "explanation": "bīn（第一声）与 pīn 声母不同（b 与 p），声调相同，意思是宾客。"}, {"text": "贫", "is_correct": false, "explanation": "pín（第二声）与 pīn 声调不同，意思是贫穷。"}, {"text": "聘", "is_correct": false, "explanation": "pìn（第四声）与 pīn 声调不同，意思是聘请、聘用。"}], "explanations": {"拼": "正确。拼 pīn 指把小块的东西合在一起。", "宾": "bīn（第一声）与 pīn 声母不同（b 与 p），声调相同，意思是宾客。", "贫": "pín（第二声）与 pīn 声调不同，意思是贫穷。", "聘": "pìn（第四声）与 pīn 声调不同，意思是聘请、聘用。"}, "sentence_index": null, "correct_answer": "拼"}, "level_3": {"options": [{"text": "拼", "is_correct": true, "explanation": "正确。“拼着一辆小汽车”指把零件拼装成车。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是把东西分开，不能把小汽车切出来。"}, {"text": "煎", "is_correct": false, "explanation": "语义：煎用于食物，不能用于玩具汽车。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于人或动物，不能与“小汽车”搭配。"}], "explanations": {"拼": "正确。“拼着一辆小汽车”指把零件拼装成车。", "切": "语义：“切”是把东西分开，不能把小汽车切出来。", "煎": "语义：煎用于食物，不能用于玩具汽车。", "喂": "搭配：“喂”用于人或动物，不能与“小汽车”搭配。"}, "sentence_index": 6, "correct_answer": "拼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上拼了一首歌。", "explanation": "这里应该用〈唱〉。唱歌要用“唱”，“拼”指把小块的东西合成一个整体，不能用于歌曲。"}, {"text": "他把一束花拼进了花瓶。", "explanation": "这里应该用〈插〉。把花放进花瓶应该用“插”，“拼”不能这样用。"}, {"text": "他把垃圾拼进了垃圾桶。", "explanation": "这里应该用〈扔〉。把垃圾扔进垃圾桶应该用“扔”，“拼”指把小块的东西合成整体，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把碎纸片好拼了。", "corrected_sentence": "她把碎纸片拼好了。", "error_description": "错误形式是“好拼”，正确形式是“拼好”。结果补语“好”要紧跟在动词之后，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几块木板拼起去，就能做成一张桌子。", "corrected_sentence": "这几块木板拼起来，就能做成一张桌子。", "error_description": "错误形式是“拼起去”，正确形式是“拼起来”。“拼起来”表示把分散的部分聚合在一起，应用“来”；“去”表示离开，不能这样用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
