INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家定下的规矩，大家都要照着做。", "primary_collocate": null, "pronunciation": "fǎ zhì", "ipa": "fa˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "国家的法制，每个人都要遵守。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不了解法制，所以做错了事。", "target_word": "法制", "complexity_tier": "T3", "furigana": "tā bù liǎojiě fǎzhì, suǒyǐ zuòcuòle shì.", "sentence_source": "generated"}, {"text": "无论是谁，都不能无视国家的法制。", "target_word": "法制", "complexity_tier": "T3", "furigana": "wúlùn shì shuí, dōu bù néng wúshì guójiā de fǎzhì.", "sentence_source": "generated"}, {"text": "生活在这里，就要照着国家的法制做事。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都应该尊重国家的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，法制是大家都要照着做的规矩。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板也要遵守国家的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人和孩子都要知道国家的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他违反了国家的法制，受到了处罚。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人来中国，也要遵守中国的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法制化", "label": "派生"}, {"form": "法制观念", "label": "复合"}], "register": "书面语", "sense_fingerprint": "国家制定、人人必须遵守的规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95245, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法制", "is_correct": true, "explanation": "法制 fǎzhì，指国家定下的规矩，大家都要照着做，正是这里要听的词。"}, {"text": "法子", "is_correct": false, "explanation": "法子 fǎzi，第二个音节声母是 z，不是 zh，意思是办法、方法。"}, {"text": "法式", "is_correct": false, "explanation": "法式 fǎshì，第二个音节声母是 sh，不是 zh，意思是式样、风格。"}, {"text": "反制", "is_correct": false, "explanation": "反制 fǎnzhì，第一个音节多一个韵尾 n（fǎn），意思是反过来制约。"}, {"text": "码制", "is_correct": false, "explanation": "码制 mǎzhì，第一个音节声母是 m，不是 f，声调为第三声，意思是编码的制式。"}], "explanations": {"法制": "法制 fǎzhì，指国家定下的规矩，大家都要照着做，正是这里要听的词。", "法子": "法子 fǎzi，第二个音节声母是 z，不是 zh，意思是办法、方法。", "法式": "法式 fǎshì，第二个音节声母是 sh，不是 zh，意思是式样、风格。", "反制": "反制 fǎnzhì，第一个音节多一个韵尾 n（fǎn），意思是反过来制约。", "码制": "码制 mǎzhì，第一个音节声母是 m，不是 f，声调为第三声，意思是编码的制式。"}, "sentence_index": null, "correct_answer": "法制"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是规矩，不能遵守。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色是外貌状态，不是要遵守的规定。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“遵守”不能用于身高，身高是自然条件。"}, {"text": "法制", "is_correct": true, "explanation": "法制：国家定下的规矩，大家都要照着做，可以“遵守”。"}], "explanations": {"天气": "语义：天气不是规矩，不能遵守。", "脸色": "体貌：脸色是外貌状态，不是要遵守的规定。", "身高": "搭配：“遵守”不能用于身高，身高是自然条件。", "法制": "法制：国家定下的规矩，大家都要照着做，可以“遵守”。"}, "sentence_index": 0, "correct_answer": "法制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家的法制很多，孩子们都不敢乱说话。", "explanation": "这里应该用〈规矩〉。法制指国家定下的法律制度，家里的约定只能说规矩。"}, {"text": "他在路上捡到一个法制，交给了警察。", "explanation": "这里应该用〈钱包〉。法制指国家定下的规矩，不是具体的物品。"}, {"text": "他养成了好法制，每天都很自律。", "explanation": "这里应该用〈习惯〉。法制是国家制度，养成的是习惯，不能说养成好法制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情不是规定，不能遵守。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“遵守”后面不能接年龄。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“遵守”不能接体重，体重是身体的数值。"}, {"text": "法制", "is_correct": true, "explanation": "法制：国家定下的规矩，与“遵守”搭配。"}], "explanations": {"心情": "语义：心情不是规定，不能遵守。", "年龄": "搭配：“遵守”后面不能接年龄。", "体重": "搭配：“遵守”不能接体重，体重是身体的数值。", "法制": "法制：国家定下的规矩，与“遵守”搭配。"}, "sentence_index": 6, "correct_answer": "法制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法制依据证据，判他三年徒刑。", "explanation": "这里应该用〈法官〉。法制是抽象的制度，不能依据证据判决，判决要由法官作出。"}, {"text": "学生每天要复习数学法制。", "explanation": "这里应该用〈课程〉。法制不是学科，复习的应该是数学课程。"}, {"text": "学校的法制要求学生穿校服。", "explanation": "这里应该用〈规定〉。法制指国家层面的法律制度，学校的要求只能说规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国家有一条完整的法制，人人都要遵守。", "corrected_sentence": "国家有一套完整的法制，人人都要遵守。", "error_description": "“法制”指整体的制度，不能按“条”计数，这里应该用量词“套”，说“一套完整的法制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直很尊重了国家的法制。", "corrected_sentence": "他一直很尊重国家的法制。", "error_description": "“很”后面的动词“尊重”不能直接加“了”，去掉“了”，说“他一直很尊重国家的法制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
