INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律和制度的总称，指依法办事的制度。", "primary_collocate": null, "pronunciation": "fǎ zhì", "ipa": "fa˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的法制很健全。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要努力健全法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法制是社会安定的基础。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了这个国家的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习中国法制的历史。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法制不健全，人们就没有安全感。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的法制越来越完善了。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过很多国家的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法制完善了，外国公司也愿意来这里工作。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家要发展，必须有健全的法制。", "target_word": "法制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法制化", "label": "派生"}, {"form": "法制观念", "label": "复合"}], "register": "书面语", "sense_fingerprint": "法律与制度的总称，依法办事的制度体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05603155-7014-437f-be97-76a86cc3743a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法制", "is_correct": true, "explanation": "法制 fǎzhì，指法律和制度的总称，正是这里要听的词。"}, {"text": "法子", "is_correct": false, "explanation": "法子 fǎzi，第二个音节声母是 z，不是 zh，意思是办法、方法。"}, {"text": "法式", "is_correct": false, "explanation": "法式 fǎshì，第二个音节声母是 sh，不是 zh，意思是式样、风格。"}, {"text": "反制", "is_correct": false, "explanation": "反制 fǎnzhì，第一个音节多一个韵尾 n（fǎn），意思是反过来制约。"}, {"text": "码制", "is_correct": false, "explanation": "码制 mǎzhì，第一个音节声母是 m，不是 f，声调为第三声，意思是编码的制式。"}], "explanations": {"法制": "法制 fǎzhì，指法律和制度的总称，正是这里要听的词。", "法子": "法子 fǎzi，第二个音节声母是 z，不是 zh，意思是办法、方法。", "法式": "法式 fǎshì，第二个音节声母是 sh，不是 zh，意思是式样、风格。", "反制": "反制 fǎnzhì，第一个音节多一个韵尾 n（fǎn），意思是反过来制约。", "码制": "码制 mǎzhì，第一个音节声母是 m，不是 f，声调为第三声，意思是编码的制式。"}, "sentence_index": null, "correct_answer": "法制"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“健全”用于制度、体系，不能说天气很健全。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“健全”不能修饰价格，价格只说高低或合理。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是一项活动，不是可以“健全”的对象。"}, {"text": "法制", "is_correct": true, "explanation": "法制：法律和制度的总称，可以说“很健全”。"}], "explanations": {"天气": "搭配：“健全”用于制度、体系，不能说天气很健全。", "价格": "搭配：“健全”不能修饰价格，价格只说高低或合理。", "比赛": "语义：比赛是一项活动，不是可以“健全”的对象。", "法制": "法制：法律和制度的总称，可以说“很健全”。"}, "sentence_index": 0, "correct_answer": "法制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的法制很好听。", "explanation": "这里应该用〈旋律〉。法制指法律和制度，不能用来形容歌曲。"}, {"text": "这起案子，法制判他无罪了。", "explanation": "这里应该用〈法院〉。法制是抽象的制度，不能审理或判决案件，判决要由法院作出。"}, {"text": "学校的法制规定，学生不能带手机。", "explanation": "这里应该用〈校规〉。法制指国家的法律制度，学校自己定的规定只能说校规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "搭配：“完善”用于制度、设施，不能说心情越来越完善。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“完善”不能修饰体重，体重只说增加或减少。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口是人数，不能“完善”，只能说增长或减少。"}, {"text": "法制", "is_correct": true, "explanation": "法制：法律和制度的总称，可以说“越来越完善”。"}], "explanations": {"心情": "搭配：“完善”用于制度、设施，不能说心情越来越完善。", "体重": "搭配：“完善”不能修饰体重，体重只说增加或减少。", "人口": "语义：人口是人数，不能“完善”，只能说增长或减少。", "法制": "法制：法律和制度的总称，可以说“越来越完善”。"}, "sentence_index": 6, "correct_answer": "法制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了早睡的法制。", "explanation": "这里应该用〈习惯〉。法制是国家的法律制度，养成的是习惯，不能说养成法制。"}, {"text": "这张桌子的法制很结实，可以放很多书。", "explanation": "这里应该用〈结构〉。法制指法律和制度，不能用来形容家具。"}, {"text": "学生每天要学习数学法制。", "explanation": "这里应该用〈课程〉。法制是国家的法律制度，不是学科，数学和法制不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的法制正在逐步健康。", "corrected_sentence": "这个国家的法制正在逐步健全。", "error_description": "“法制”后面应该用“健全”，不能用“健康”。“健康”多用于人体和身心状况，说制度的完备程度要用“健全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年我们将继续完善了法制。", "corrected_sentence": "明年我们将继续完善法制。", "error_description": "“明年”表示将来，“完善”后面不能加“了”。去掉“了”，说“明年我们将继续完善法制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3cda98-d206-416d-a4f6-3e028f9b65a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
