INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "逐项列出物品或事项的单子。", "primary_collocate": null, "pronunciation": "qīng dān", "ipa": "tɕʰiŋ˥ tan˥", "syllable_count": 2, "sentences": [{"text": "公司把货物清单发给了客户。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要看今天的工作清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我们检查了一遍物品清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清单上有五个任务，我已经做完了三个。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按清单上的名字一个一个念。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份清单列出了房间里所有的家具。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员正在核对货物清单。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈列了一份清单，把过年要做的事都写了上去。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的愿望清单上有一台新电脑。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店送来了一份费用清单，我们看了很久。", "target_word": "清单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "清單", "label": "繁体"}, {"form": "货物清单", "label": "复合"}], "register": "中性", "sense_fingerprint": "逐项列出物品、费用、任务、名单或愿望等事项的单子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d9b002-279d-4c1b-818b-f1dbb4164f90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清单", "is_correct": true, "explanation": "正确：“货物清单”逐项列出货物，可以发给客户核对，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“发给”的对象应是文件或物品，“心情”不能发给别人。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”是人，不是可以发给客户的东西。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不能被发给客户。"}], "explanations": {"清单": "正确：“货物清单”逐项列出货物，可以发给客户核对，符合句意。", "心情": "搭配：“发给”的对象应是文件或物品，“心情”不能发给别人。", "同事": "语义：“同事”是人，不是可以发给客户的东西。", "身材": "体貌：“身材”指外形，不能被发给客户。"}, "sentence_index": 0, "correct_answer": "清单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的清单很大，一家人住得很舒服。", "explanation": "这里应该用〈房子〉。清单是逐项列出物品或事项的单子，不能用来住人。"}, {"text": "我每天早上打开收音机，听清单播报今天的天气。", "explanation": "这里应该用〈天气预报〉。清单只逐项列出事项，不会播报天气。"}, {"text": "我们在客厅挂了一张清单，画得很有意境。", "explanation": "这里应该用〈画〉。清单是逐项列出物品或事项的单子，不是画作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清单", "is_correct": true, "explanation": "正确：“核对货物清单”是常见搭配，指逐项查对货物，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“核对”的对象应是可以逐项查对的材料或数据，“天气”无法核对。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“核对”不能用于“脾气”这类性格状态。"}, {"text": "大海", "is_correct": false, "explanation": "语义：海关不核对大海，句意不通。"}], "explanations": {"清单": "正确：“核对货物清单”是常见搭配，指逐项查对货物，符合句意。", "天气": "搭配：“核对”的对象应是可以逐项查对的材料或数据，“天气”无法核对。", "脾气": "搭配：“核对”不能用于“脾气”这类性格状态。", "大海": "语义：海关不核对大海，句意不通。"}, "sentence_index": 6, "correct_answer": "清单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员端上来一份清单，我们吃得很开心。", "explanation": "这里应该用〈菜〉。清单是逐项列出物品或事项的单子，不能用来吃。"}, {"text": "医生用清单给我做了手术。", "explanation": "这里应该用〈手术刀〉。清单是逐项列出物品或事项的单子，不能用来切割。"}, {"text": "他上台领奖，拿到的那张清单其实是一纸奖状。", "explanation": "这里应该用〈奖状〉。清单是逐项列出物品或事项的单子，不是颁给获奖者的证明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把任务清单上有五项，我已经做完了两项。", "corrected_sentence": "这份任务清单上有五项，我已经做完了两项。", "error_description": "“清单”应与“份”或“张”搭配。“把”用于有柄的器具，不用于清单。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几份清单们都已经核对完了。", "corrected_sentence": "几份清单都已经核对完了。", "error_description": "“清单”不是人，不能加“们”表示复数；“几份”已经表示数量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ba432b-6b60-4de4-80a9-9667943b2f05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
