INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在物质生产过程中结成的社会关系。", "primary_collocate": null, "pronunciation": "shēng chǎn guān xì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "生产关系是社会里最重要的关系之一。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课本讲了什么是生产关系。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，生产关系会影响人们的生活。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的生产关系和农村不一样。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会变了，生产关系也跟着变了。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书研究的是古代的生产关系。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产关系决定谁拿多少东西。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上问了生产关系是什么意思。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产关系和生产工具都很重要。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的生产关系让工人的生活好了。", "target_word": "生产关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產關係", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物质生产中形成的社会关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10b2f6b-6e2b-4fc3-8a1e-105a8b61b983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产力", "is_correct": false, "explanation": "语义：生产力指生产中的力量，不是社会关系，不能说是“关系之一”。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“……之一”要求前面是关系类名词，“水果”不能与“关系之一”搭配。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：人们在物质生产过程中结成的社会关系，正是“社会里最重要的关系之一”，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是社会关系，不能是“社会里最重要的关系之一”。"}], "explanations": {"生产力": "语义：生产力指生产中的力量，不是社会关系，不能说是“关系之一”。", "水果": "搭配：“……之一”要求前面是关系类名词，“水果”不能与“关系之一”搭配。", "生产关系": "生产关系：人们在物质生产过程中结成的社会关系，正是“社会里最重要的关系之一”，符合语境。", "天气": "语义：天气不是社会关系，不能是“社会里最重要的关系之一”。"}, "sentence_index": 0, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班同学的生产关系很好。", "explanation": "这里应该用〈人际关系〉。生产关系指物质生产中人与人的关系，不用来说同学之间的交往。"}, {"text": "他和叔叔是生产关系。", "explanation": "这里应该用〈亲戚关系〉。生产关系指物质生产中人与人的分工和分配关系，不指亲属之间的关系。"}, {"text": "生产关系是一台新机器。", "explanation": "生产关系是人与人之间的关系，不是机器，不能用“一台”来计量，也不能说是机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能决定分配，不符合“决定谁拿多少东西”的语境。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：牙膏与分配东西毫无关系，不能作“决定谁拿多少东西”的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“决定谁拿多少东西”的主语要是制度或关系，“冰箱”不搭配。"}, {"text": "生产关系", "is_correct": true, "explanation": "生产关系：物质生产中的社会关系，决定分配、决定谁拿多少东西，符合语境。"}], "explanations": {"汽车": "语义：汽车不能决定分配，不符合“决定谁拿多少东西”的语境。", "牙膏": "语义：牙膏与分配东西毫无关系，不能作“决定谁拿多少东西”的主语。", "冰箱": "搭配：“决定谁拿多少东西”的主语要是制度或关系，“冰箱”不搭配。", "生产关系": "生产关系：物质生产中的社会关系，决定分配、决定谁拿多少东西，符合语境。"}, "sentence_index": 6, "correct_answer": "生产关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新机器提高了生产关系。", "explanation": "这里应该用〈生产力〉。机器提高的是生产力，生产关系是人与人之间的关系，不能被机器提高。"}, {"text": "这种生产关系很好吃。", "explanation": "这里不能用“好吃”描述关系。“好吃”只用于食物，生产关系不能吃。"}, {"text": "生产关系跑得很快。", "explanation": "这里应该用〈运动员〉。生产关系是人与人之间的关系，不会跑步，“跑得很快”只能用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条新的生产关系出现了。", "corrected_sentence": "一种新的生产关系出现了。", "error_description": "错误在量词“条”。“生产关系”是抽象的关系，量词应用“种”，不用“条”，应说“一种新的生产关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条生产关系很特别。", "corrected_sentence": "这种生产关系很特别。", "error_description": "错误在量词“条”。“生产关系”的量词应用“种”，不用“条”，应说“这种生产关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墙上可以看到外面的那个口子。", "primary_collocate": null, "pronunciation": "chuāng kǒu", "ipa": "tʂʰuɑŋ⁵⁵ kʰou²¹⁴", "syllable_count": 2, "sentences": [{"text": "他坐在窗口,看着外面的雨。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口开着,房间里很凉快。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上窗口,晒太阳。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下大雨了，窗口的玻璃上全是水。", "target_word": "窗口", "complexity_tier": "T3", "furigana": "chuāng kǒu", "sentence_source": "generated"}, {"text": "窗口外面有一棵很大的树。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈站在窗口,等孩子回家。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子的窗口朝南,阳光很好。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从窗口吹进来,很舒服。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口太小了,屋里不太亮。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子趴在窗口,看楼下的小狗。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "窗口边", "label": "复合"}], "register": "中性", "sense_fingerprint": "墙上装窗、可以看到外面的开口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指墙上可以看到外面的开口，人可以坐在旁边看雨。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不能供人坐，与“坐在”的语境不合。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的书写板，不能用来坐。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“坐在”后接的是可以坐的地方，不说“坐在电视”。"}], "explanations": {"窗口": "正确：“窗口”指墙上可以看到外面的开口，人可以坐在旁边看雨。", "冰箱": "语义：“冰箱”不能供人坐，与“坐在”的语境不合。", "黑板": "语义：“黑板”是教室里的书写板，不能用来坐。", "电视": "搭配：“坐在”后接的是可以坐的地方，不说“坐在电视”。"}, "sentence_index": 0, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业写在窗口上，一写就是一晚上。", "explanation": "这里应该用〈纸〉或〈本子〉。“窗口”指墙上的开口，不能当作写字的地方。"}, {"text": "天亮了，窗口拉开了。", "explanation": "这里应该用〈窗帘〉。窗口是墙上的开口，不能拉开，拉开的是窗帘。"}, {"text": "这个窗口很可爱，每天都会摇尾巴。", "explanation": "这里应该用〈小狗〉。窗口是墙上的开口，不会摇尾巴，应说“小狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指屋子的墙上可以透光、通风的开口，可以朝南。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”没有朝向，不能说“朝南”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”没有朝向，与“朝南，阳光很好”的语境不合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“朝南”用于房屋、窗户等有朝向的事物，“声音”不说朝向。"}], "explanations": {"窗口": "正确：“窗口”指屋子的墙上可以透光、通风的开口，可以朝南。", "价格": "语义：“价格”没有朝向，不能说“朝南”。", "名字": "语义：“名字”没有朝向，与“朝南，阳光很好”的语境不合。", "声音": "搭配：“朝南”用于房屋、窗户等有朝向的事物，“声音”不说朝向。"}, "sentence_index": 6, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用窗口切了一块西瓜。", "explanation": "这里应该用〈刀〉。窗口是墙上的开口，不能用来切东西。"}, {"text": "一个窗口挂在墙上，很好看。", "explanation": "这里应该用〈画〉。窗口是墙上的开口，不能挂在墙上。"}, {"text": "我家的窗口很爱笑，每天都很开心。", "explanation": "这里应该用〈孩子〉。窗口是墙上的开口，不会笑，应说“孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的窗口一直开了着，屋里很凉快。", "corrected_sentence": "我家的窗口一直开着，屋里很凉快。", "error_description": "错误形式：“我家的窗口一直开了着”；正确形式：“我家的窗口一直开着”。同一个动词不能同时带体标“了”和“着”，“开”后多余的“了”应删去，保留“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子的墙上开了一只窗口。", "corrected_sentence": "屋子的墙上开了一个窗口。", "error_description": "错误形式：“一只窗口”；正确形式：“一个窗口”。“窗口”的量词应用“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
