INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "办事时对外办理业务的小窗口，如银行、车站的服务台。", "primary_collocate": null, "pronunciation": "chuāng kǒu", "ipa": "tʂʰuɑŋ⁵⁵ kʰou²¹⁴", "syllable_count": 2, "sentences": [{"text": "银行的窗口十点才开门。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到三号窗口办手续。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在火车站的窗口买了两张票。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的窗口前有很多人在排队。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去窗口问一下,工作人员会告诉你。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个窗口只办护照,不办身份证。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗口里的工作人员很热情。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午五点,窗口就关了。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗口交了钱,拿到了收据。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在窗口等了很久,还没轮到我。", "target_word": "窗口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "服务窗口", "label": "复合"}], "register": "中性", "sense_fingerprint": "银行、车站等办理业务的服务窗口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c29758d1-831e-4793-b2b0-aaeb6aa6a2b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指银行办理业务的服务台，银行的窗口按时开门，符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“开门”与“饭”不搭配，说“开饭”才对。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不能开门，与银行营业的语境不合。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”不是营业场所，不能说它十点才开门。"}], "explanations": {"窗口": "正确：“窗口”指银行办理业务的服务台，银行的窗口按时开门，符合句意。", "饭": "搭配：“开门”与“饭”不搭配，说“开饭”才对。", "水果": "语义：“水果”不能开门，与银行营业的语境不合。", "小狗": "语义：“小狗”不是营业场所，不能说它十点才开门。"}, "sentence_index": 0, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把窗口搬到超市去买了一斤苹果。", "explanation": "这里应该用〈篮子〉。窗口是墙上的开口或办事的小窗，不能搬走，也不能用来装东西。"}, {"text": "他推开医院的窗口，走进了大厅。", "explanation": "这里应该用〈大门〉。服务窗口不能推开走进去，进大厅要用门。"}, {"text": "这个窗口很会唱歌，大家都很喜欢。", "explanation": "这里应该用〈歌手〉。窗口是办事的小窗，不会唱歌，应说“歌手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗口", "is_correct": true, "explanation": "正确：“窗口”指办事的服务台，窗口里的工作人员很热情，符合句意。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：“鱼缸”里不能有办事的工作人员，与句意不合。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”装不下工作人员，与句意不合。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“里”前的场所要能容纳办事人员，“垃圾桶”不能用于办事，这种说法不通。"}], "explanations": {"窗口": "正确：“窗口”指办事的服务台，窗口里的工作人员很热情，符合句意。", "鱼缸": "语义：“鱼缸”里不能有办事的工作人员，与句意不合。", "口袋": "语义：“口袋”装不下工作人员，与句意不合。", "垃圾桶": "搭配：“里”前的场所要能容纳办事人员，“垃圾桶”不能用于办事，这种说法不通。"}, "sentence_index": 6, "correct_answer": "窗口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用窗口切了一块蛋糕。", "explanation": "这里应该用〈刀〉。窗口是办事的小窗或墙上的开口，不能用来切东西。"}, {"text": "我在窗口跳了很久的舞，还没停。", "explanation": "这里应该用〈广场〉。窗口是办事的小窗或墙上的开口，不是跳舞的地方。"}, {"text": "他在窗口里踢了一场足球。", "explanation": "这里应该用〈操场〉。窗口不是足球场，不能在里面踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只窗口只办理身份证业务。", "corrected_sentence": "这个窗口只办理身份证业务。", "error_description": "错误形式：“这只窗口”；正确形式：“这个窗口”。“窗口”的量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我窗口领了一张表格。", "corrected_sentence": "我在窗口领了一张表格。", "error_description": "错误形式：“我窗口领”；正确形式：“我在窗口领”。表示动作发生的地点，要用介词“在”引出“窗口”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7044f9db-b551-4e90-b34b-7aacaa34182d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
