INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因犯罪行为而被确定的名称。", "primary_collocate": null, "pronunciation": "zuì míng", "ipa": "tsweɪ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法院说他的罪名是盗窃。", "target_word": "罪名", "complexity_tier": "T3", "furigana": "fǎyuàn shuō tā de zuìmíng shì dàoqiè", "sentence_source": "generated"}, {"text": "警察告诉他，他的罪名是抢劫。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官念出了三个罪名。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不承认这个罪名，要请律师。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个罪名很重，他要坐很多年牢。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着他的罪名是诈骗。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院最后撤销了这个罪名。", "target_word": "罪名", "complexity_tier": "T3", "furigana": "fǎyuàn zuìhòu chèxiāo le zhège zuìmíng", "sentence_source": "generated"}, {"text": "律师说这个罪名不对，他没有做过那件事。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律上每个罪名都有不同的处罚。", "target_word": "罪名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个罪名，一个是盗窃，一个是故意伤害。", "target_word": "罪名", "complexity_tier": "T3", "furigana": "tā yǒu liǎng gè zuìmíng yí gè shì dàoqiè yí gè shì gùyì shānghài", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个罪名", "label": "量词"}], "register": "中性", "sense_fingerprint": "法律上确定的犯罪名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa43149-2bed-4ace-a420-196d5d97c406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罪名", "is_correct": true, "explanation": "“罪名”指法律上确定的犯罪名称，与“盗窃”搭配，能说明他被认定的罪行。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是人或事物的称呼，不指法律上确定的犯罪名称。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是年数，不能说“他的年龄是盗窃”，与句意不合。"}, {"text": "罪犯", "is_correct": false, "explanation": "语义：“罪犯”指犯罪的人，不是犯罪的名称。"}], "explanations": {"罪名": "“罪名”指法律上确定的犯罪名称，与“盗窃”搭配，能说明他被认定的罪行。", "名字": "语义：“名字”是人或事物的称呼，不指法律上确定的犯罪名称。", "年龄": "语义：“年龄”是年数，不能说“他的年龄是盗窃”，与句意不合。", "罪犯": "语义：“罪犯”指犯罪的人，不是犯罪的名称。"}, "sentence_index": 0, "correct_answer": "罪名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的罪名是《买卖合同》。", "explanation": "这里应该用〈名称〉。罪名专指法律上认定的犯罪名称，合同的名字要用名称。"}, {"text": "这本书的罪名很好听。", "explanation": "这里应该用〈名字〉。罪名只指法律认定的罪名，书的名字不能叫罪名。"}, {"text": "他在比赛中拿到了一个荣誉罪名。", "explanation": "这里应该用〈称号〉。荣誉称号是授予的好名号，罪名只指法律认定的犯罪名称，不能用于荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罪名", "is_correct": true, "explanation": "“罪名”指法律上确定的犯罪名称，可以被法院撤销。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：“午餐”是饭食，法院不会撤销它。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“撤销”一般不与“照片”搭配。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物品，不能被法院撤销。"}], "explanations": {"罪名": "“罪名”指法律上确定的犯罪名称，可以被法院撤销。", "午餐": "语义：“午餐”是饭食，法院不会撤销它。", "照片": "搭配：“撤销”一般不与“照片”搭配。", "钥匙": "语义：“钥匙”是物品，不能被法院撤销。"}, "sentence_index": 6, "correct_answer": "罪名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在的罪名是教授。", "explanation": "这里应该用〈职称〉。罪名指法律认定的犯罪名称，专业技术人员的称号要用职称。"}, {"text": "这种植物的罪名是龙葵。", "explanation": "这里应该用〈学名〉。罪名指法律认定的犯罪名称，植物的科学名称要用学名。"}, {"text": "这种药的罪名是阿莫西林。", "explanation": "这里应该用〈药名〉。罪名指犯罪名称，药物的名称要用药名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检察院给他定了一张罪名，案子下周开庭。", "corrected_sentence": "检察院给他定了一个罪名，案子下周开庭。", "error_description": "量词错误：“罪名”应配量词“个”，写成“一张罪名”是错误的，“张”用于纸、桌子等平面物。正确说法是“一个罪名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察很快就查下了他的罪名。", "corrected_sentence": "警察很快就查出了他的罪名。", "error_description": "补语错误：“查”与“罪名”搭配时补语应为“出”，表示查明、找出；说“查下”是错误的。正确说法是“查出了他的罪名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1183b02d-f9e0-4e1b-8af2-43fc8e20a19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
