INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家里年纪大的人和年纪小的孩子。", "primary_collocate": null, "pronunciation": "lǎo xiǎo", "ipa": "lɑʊ˨˩˦ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "过年时，一家老小都回来了。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他要养活一家老小。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，他带着一家老小跑了出来。", "target_word": "老小", "complexity_tier": "T3", "furigana": "dì zhèn shí tā dài zhe yī jiā lǎo xiǎo pǎo le chū lái", "sentence_source": "generated"}, {"text": "老小都爱吃妈妈做的菜。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们带着一家老小去公园。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人照顾着家里的老小。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨，老小都没出门。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶和孩子，老小都在家等你。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大年夜，全家老小围着桌子吃饭。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的老小都靠他挣钱。", "target_word": "老小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "家中的老人和孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa434ef8-d894-447b-8602-18a3814af4db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老小", "is_correct": true, "explanation": "正确：「一家老小」指一家的老人和孩子，与「都回来了」吻合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：「外人」不是家里人，与「一家」和「回来」不协调。"}, {"text": "客人", "is_correct": false, "explanation": "语义：客人不会「回来」，与「都回来了」矛盾。"}, {"text": "夫妻", "is_correct": false, "explanation": "搭配：「一家」不说「一家夫妻」，夫妻只指两个人。"}], "explanations": {"老小": "正确：「一家老小」指一家的老人和孩子，与「都回来了」吻合。", "外人": "语义：「外人」不是家里人，与「一家」和「回来」不协调。", "客人": "语义：客人不会「回来」，与「都回来了」矛盾。", "夫妻": "搭配：「一家」不说「一家夫妻」，夫妻只指两个人。"}, "sentence_index": 0, "correct_answer": "老小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的老小都很用功。", "explanation": "这里应该用〈学生〉。老小指家里的老人和孩子，学校里的学生不能叫老小。"}, {"text": "这位老小每天都去公园散步。", "explanation": "这里应该用〈老人〉。老小指老人和孩子合称，只说一位老人要用老人。"}, {"text": "这座城市的老小越来越多。", "explanation": "这里应该用〈居民〉。老小只指家中的老人和孩子，不能泛指城市里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老小", "is_correct": true, "explanation": "正确：「一场大雨，老小都没出门」指家里的老人和孩子，都能出门，符合句意。"}, {"text": "花草", "is_correct": false, "explanation": "语义：花草不会出门，与「一场大雨，……都没出门」不协调。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：「出门」的主体一般是人或动物，家具不说出门。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会出门，句子说不通。"}], "explanations": {"老小": "正确：「一场大雨，老小都没出门」指家里的老人和孩子，都能出门，符合句意。", "花草": "语义：花草不会出门，与「一场大雨，……都没出门」不协调。", "家具": "搭配：「出门」的主体一般是人或动物，家具不说出门。", "石头": "语义：石头不会出门，句子说不通。"}, "sentence_index": 6, "correct_answer": "老小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里的老小都很努力。", "explanation": "这里应该用〈学生〉。老小专指家里的老人和孩子，学校里的学生不能叫老小。"}, {"text": "公司的老小都很努力。", "explanation": "这里应该用〈员工〉。老小指家里的老人和孩子，公司的员工不能叫老小。"}, {"text": "幼儿园的老小都很活泼。", "explanation": "这里应该用〈儿童〉。老小包括老人，幼儿园里的儿童不能叫老小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶带着一个老小去了海边。", "corrected_sentence": "奶奶带着一家老小去了海边。", "error_description": "错误：「老小」前的量词应用「家」，不能用「个」。正确说法是「一家老小」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一家老小们都搬到了新城。", "corrected_sentence": "他们一家老小都搬到了新城。", "error_description": "错误：「老小」是集合名词，后面不能再加「们」。正确说法是「一家老小都搬到了新城」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9c069f-0075-4a5f-b277-33484bac4c10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
