INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生意或事情变得越来越好。", "primary_collocate": null, "pronunciation": "xīng", "ipa": "ɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "家和万事兴。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小饭馆生意一年比一年兴。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家兴，人民的日子才会好。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店在他手里又兴了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里修了路，买卖就兴了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说，人旺家才兴。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他种的花卖得好，这几年买卖越来越兴。", "target_word": "兴", "complexity_tier": "T3", "furigana": "tā zhòng de huā mài de hǎo, zhè jǐ nián mǎi mai yuè lái yuè xīng.", "sentence_source": "generated"}, {"text": "厂子换了新老板，生意慢慢兴了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的店越开越多，这条街兴了。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要大家努力，我们的小店一定会兴。", "target_word": "兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "興", "label": "繁体"}, {"form": "兴旺", "label": "复合词"}, {"form": "兴了", "label": "体标"}], "register": "口语", "sense_fingerprint": "兴：生意、家业、国家等变得越来越好、越来越旺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95273, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴（xīng，第一声）：兴旺，生意或事情变得越来越好，是本词的读音。"}, {"text": "新", "is_correct": false, "explanation": "新（xīn）：韵尾不同（n 与 ng），意思是新旧的新。"}, {"text": "西", "is_correct": false, "explanation": "西（xī）：比 xīng 少了韵尾 ng，意思是西方。"}, {"text": "形", "is_correct": false, "explanation": "形（xíng，第二声）：与 xīng 声调不同，意思是形状。"}, {"text": "行", "is_correct": false, "explanation": "行（xíng，第二声）：与 xīng 声调不同，意思是行走、可以。"}], "explanations": {"兴": "兴（xīng，第一声）：兴旺，生意或事情变得越来越好，是本词的读音。", "新": "新（xīn）：韵尾不同（n 与 ng），意思是新旧的新。", "西": "西（xī）：比 xīng 少了韵尾 ng，意思是西方。", "形": "形（xíng，第二声）：与 xīng 声调不同，意思是形状。", "行": "行（xíng，第二声）：与 xīng 声调不同，意思是行走、可以。"}, "sentence_index": null, "correct_answer": "兴"}, "level_3": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴：兴旺，家和则事业顺利，符合“家和万事……”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指饮食，“家和万事吃”说不通。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”不接“万事”，“万事摘”不是说法。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与家和事成的意思不符，句意不通。"}], "explanations": {"兴": "兴：兴旺，家和则事业顺利，符合“家和万事……”的句意。", "吃": "语义：“吃”指饮食，“家和万事吃”说不通。", "摘": "搭配：“摘”不接“万事”，“万事摘”不是说法。", "扔": "语义：“扔”是丢弃，与家和事成的意思不符，句意不通。"}, "sentence_index": 0, "correct_answer": "兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村里今年兴修了一条路，大家出门方便多了。", "explanation": "这里应该用〈修〉。“兴”在此指兴修、兴建，属于另一个义项，不表示生意变好。"}, {"text": "他的头脑很兴，学什么都快。", "explanation": "这里应该用〈发达〉。“兴”指生意、事业、家业变得兴旺，不用来形容人的头脑。"}, {"text": "他身上的火气特别兴。", "explanation": "这里应该用〈旺〉。“兴”指事业、生意等越来越好，不用来形容火气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95273, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴（xīng，第一声）：兴旺，生意或事情变得越来越好，是本词的读音。"}, {"text": "醒", "is_correct": false, "explanation": "醒（xǐng，第三声）：与 xīng 声调不同，意思是醒来。"}, {"text": "清", "is_correct": false, "explanation": "清（qīng）：声母不同（q 与 x），意思是清楚、干净。"}, {"text": "听", "is_correct": false, "explanation": "听（tīng）：声母不同（t 与 x），意思是听见。"}, {"text": "惊", "is_correct": false, "explanation": "惊（jīng）：声母不同（j 与 x），意思是吃惊。"}], "explanations": {"兴": "兴（xīng，第一声）：兴旺，生意或事情变得越来越好，是本词的读音。", "醒": "醒（xǐng，第三声）：与 xīng 声调不同，意思是醒来。", "清": "清（qīng）：声母不同（q 与 x），意思是清楚、干净。", "听": "听（tīng）：声母不同（t 与 x），意思是听见。", "惊": "惊（jīng）：声母不同（j 与 x），意思是吃惊。"}, "sentence_index": null, "correct_answer": "兴"}, "level_3": {"options": [{"text": "兴", "is_correct": true, "explanation": "兴：兴旺，生意越来越好，符合“买卖越来越……”的句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，“买卖越来越修”说不通。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”不接“买卖”，“送买卖”不是说法。"}, {"text": "涂", "is_correct": false, "explanation": "语义：“涂”是涂抹，与买卖的状况无关，句意不通。"}], "explanations": {"兴": "兴：兴旺，生意越来越好，符合“买卖越来越……”的句意。", "修": "语义：“修”是修理，“买卖越来越修”说不通。", "送": "搭配：“送”不接“买卖”，“送买卖”不是说法。", "涂": "语义：“涂”是涂抹，与买卖的状况无关，句意不通。"}, "sentence_index": 6, "correct_answer": "兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府打算在山区兴修水库。", "explanation": "这里应该用〈修〉。“兴”在此指兴修、兴建，属于另一个义项，不表示生意变好。"}, {"text": "他立志在村里兴办一所学校。", "explanation": "这里的“兴”指兴办、创办，属于另一个义项，与生意变好无关。"}, {"text": "这几年兴养多肉植物。", "explanation": "这里的“兴”是“流行”的意思，属于另一个义项，与“生意或事业变得越来越好”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的饭馆生意越来兴。", "corrected_sentence": "他的饭馆生意越来越兴。", "error_description": "错误：“越来越”是固定格式，不能漏掉一个“越”。应说“越来越兴”，不说“越来兴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家小店生意慢慢兴下来了。", "corrected_sentence": "这家小店生意慢慢兴起来了。", "error_description": "补语错误：“兴”表示事业、生意由弱变强，趋向补语应用“起来”，不能用“下来”（“下来”表示由高到低、由动到静）。应说“慢慢兴起来了”，不说“慢慢兴下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
