INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近的几年。", "primary_collocate": null, "pronunciation": "jìn nián", "ipa": "tɕin˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "近年，这个城市的人越来越多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年天气比以前热了不少。", "target_word": "近年", "complexity_tier": "T3", "furigana": "jìn nián", "sentence_source": "generated"}, {"text": "近年他一直在国外工作。", "target_word": "近年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "近年，我们学校买了很多新电脑。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店近年生意很好，客人不少。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年出生的孩子，从小就会用手机。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近年写过几本关于旅行的书。", "target_word": "近年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年的物价比十年前高了很多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河近年变干净了，常有人来钓鱼。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她近年很少回老家，因为工作太忙。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年来", "label": "复合"}], "register": "书面", "sense_fingerprint": "与以前相对的最近几年这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近几年，与“这个城市的人越来越多”这种长期变化相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指人的少年时期，与这座城市的人口增长不搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}], "explanations": {"近年": "正确：近年指最近几年，与“这个城市的人越来越多”这种长期变化相符。", "童年": "语义：“童年”指人的少年时期，与这座城市的人口增长不搭配。", "眼睛": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。", "地铁": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}, "sentence_index": 0, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年他感冒了，一直在家休息。", "explanation": "这里应该用〈近来〉。近年指最近几年，几天内的感冒要用近来。"}, {"text": "近年我们要去北京旅行。", "explanation": "这里应该用〈将来〉。近年指过去到现在的几年，计划将来的事要用将来。"}, {"text": "近年他刚下飞机。", "explanation": "这里应该用〈刚才〉。近年指几年，不能与“刚”这种表示刚刚发生的副词搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近几年，与“写过几本关于旅行的书”的长期经历相符。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：“黎明”指天刚亮的一刻，与“写过几本书”的长时段经历不合。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”指一段很短的时间，不能说明写过几本书的经历。"}, {"text": "当下", "is_correct": false, "explanation": "搭配：“当下”指眼前这一刻，不与表示经历的“写过”搭配。"}], "explanations": {"近年": "正确：近年指最近几年，与“写过几本关于旅行的书”的长期经历相符。", "黎明": "语义：“黎明”指天刚亮的一刻，与“写过几本书”的长时段经历不合。", "傍晚": "语义：“傍晚”指一段很短的时间，不能说明写过几本书的经历。", "当下": "搭配：“当下”指眼前这一刻，不与表示经历的“写过”搭配。"}, "sentence_index": 6, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近年今天她突然离开了老家。", "explanation": "这里应该用〈近日〉。近年指几年，今天这种一天的时间要用近日之类的表达。"}, {"text": "她近年在十几年前就去了北京。", "explanation": "这里应该用〈早年〉。近年指最近几年，十几年前的事要用早年。"}, {"text": "近年她上个月就去了北京。", "explanation": "这里应该用〈近期〉。近年指最近几年，一个月内的事要用近期之类的词，近年不能指一个月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近年的，这个城市的房价涨了很多。", "corrected_sentence": "近年，这个城市的房价涨了很多。", "error_description": "“近年”作时间状语后不能直接加“的”（“近年的，”）；应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年的这座城市的房价涨了很多。", "corrected_sentence": "近年这座城市的房价涨了很多。", "error_description": "“近年”后直接加“的”修饰“这座城市”（“近年的这座城市”）不通；应说“近年这座城市的房价……”。", "correct_sentence_indices": [6, 8, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
