INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最近这几年。", "primary_collocate": null, "pronunciation": "jìn nián", "ipa": "tɕin˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "近年，坐高铁出门的人越来越多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年这里的变化特别大。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近年身体不太好，常去医院。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年，网上买东西成了我的习惯。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山近年总有外国客人来玩。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我近年爱上了跑步，每周跑三次。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年的夏天，一年比一年热。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们近年一直在这个小镇做生意。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年，老师给我们的作业少了很多。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年很多年轻人喜欢上了喝茶。", "target_word": "近年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年来", "label": "复合"}], "register": "书面", "sense_fingerprint": "说话时刻之前不久的这几年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近这几年，与“坐高铁出门的人越来越多”这种近几年的变化相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指人的少年时期，与“坐高铁出门的人越来越多”这种近年的变化不搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}], "explanations": {"近年": "正确：近年指最近这几年，与“坐高铁出门的人越来越多”这种近几年的变化相符。", "童年": "语义：“童年”指人的少年时期，与“坐高铁出门的人越来越多”这种近年的变化不搭配。", "眼睛": "搭配：“眼睛”是身体器官，不能作时间状语，句子不通。", "地铁": "语义：“地铁”是交通工具，不能作时间状语，句子不通。"}, "sentence_index": 0, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年我感冒了，一直在家休息。", "explanation": "这里应该用〈近来〉。近年指最近几年，感冒只持续几天，要用近来。"}, {"text": "近年我们明天就要去外地出差。", "explanation": "这里应该用〈将来〉。近年指过去到现在的几年，安排明天的事要用将来。"}, {"text": "近年一大早，我们就出发去爬山。", "explanation": "这里应该用〈今天〉。近年指几年，一大早这样的具体时刻要用今天之类的时间词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正确：近年指最近几年，与“的夏天，一年比一年热”的逐年变化相符。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”指一天中的一段时间，不能说明逐年变热的情况。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”是一个时刻，不能与“一年比一年热”的逐年变化搭配。"}, {"text": "今宵", "is_correct": false, "explanation": "语域：“今宵”是书面说法，且只指一晚，与逐年变热不合。"}], "explanations": {"近年": "正确：近年指最近几年，与“的夏天，一年比一年热”的逐年变化相符。", "清晨": "语义：“清晨”指一天中的一段时间，不能说明逐年变热的情况。", "午夜": "语义：“午夜”是一个时刻，不能与“一年比一年热”的逐年变化搭配。", "今宵": "语域：“今宵”是书面说法，且只指一晚，与逐年变热不合。"}, "sentence_index": 6, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近年几天很多年轻人都喜欢喝茶。", "explanation": "这里应该用〈近日〉。近年指几年，几天这样很短的时间要用近日。"}, {"text": "近年很多年轻人在十几年前就喜欢上了喝茶。", "explanation": "这里应该用〈早年〉。近年指最近几年，十几年前的事要用早年。"}, {"text": "近年的昨天，很多年轻人喜欢上了喝茶。", "explanation": "这里应该用〈前几天〉。近年指几年，昨天这种一天的时间要用前几天之类的表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近年的，网上订餐成了很多人的习惯。", "corrected_sentence": "近年，网上订餐成了很多人的习惯。", "error_description": "“近年”作时间状语后不能直接加“的”（“近年的，”）；应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年的我身边的朋友都喜欢喝茶。", "corrected_sentence": "近年我身边的朋友都喜欢喝茶。", "error_description": "“近年”后直接加“的”修饰“我”（“近年的我”）不通；应说“近年我身边的朋友……”。", "correct_sentence_indices": [2, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
