INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友对妈妈的女性朋友，或年纪比妈妈小的成年女性的叫法。", "primary_collocate": null, "pronunciation": "ā yí", "ipa": "a˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "阿姨，你好，我叫小明。", "target_word": "阿姨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈的朋友是一位很漂亮的阿姨。", "target_word": "阿姨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阿姨给我买了一个新玩具。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友，快叫阿姨好！", "target_word": "阿姨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位阿姨每天都来我家玩。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阿姨，你能给我讲个故事吗？", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很喜欢那个会画画的阿姨。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阿姨今天穿着一条红裙子。", "target_word": "阿姨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去阿姨家吃饭。", "target_word": "阿姨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阿姨笑着对我说：“你真乖。”", "target_word": "阿姨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "小朋友称呼妈妈的女性朋友或比妈妈年轻的女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阿姨", "is_correct": true, "explanation": "正确：“阿姨”是小朋友对年纪比妈妈小的女性的称呼，可用来向陌生女性问候。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：“妈妈”指说话人自己的母亲，不能用来向陌生人自我介绍。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”不是人，不能用作打招呼的称呼。"}, {"text": "宝宝", "is_correct": false, "explanation": "语域：“宝宝”是亲昵称呼，不用于初次见面的问候。"}], "explanations": {"阿姨": "正确：“阿姨”是小朋友对年纪比妈妈小的女性的称呼，可用来向陌生女性问候。", "妈妈": "语义：“妈妈”指说话人自己的母亲，不能用来向陌生人自我介绍。", "老虎": "语义：“老虎”不是人，不能用作打招呼的称呼。", "宝宝": "语域：“宝宝”是亲昵称呼，不用于初次见面的问候。"}, "sentence_index": 0, "correct_answer": "阿姨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸的弟弟是我的阿姨。", "explanation": "这里应该用〈叔叔〉。阿姨指女性，不能指爸爸的弟弟。"}, {"text": "我爸爸的妈妈是我的阿姨。", "explanation": "这里应该用〈奶奶〉。阿姨指妈妈的女性朋友或年纪比妈妈小的成年女性，不能指爸爸的妈妈。"}, {"text": "阿姨在医院里生下了我。", "explanation": "这里应该用〈妈妈〉。“生下”孩子的是母亲，阿姨不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阿姨", "is_correct": true, "explanation": "正确：“阿姨”指女性，符合“会画画的”这一描述。"}, {"text": "作品", "is_correct": false, "explanation": "语义：“作品”是物，不能说“会画画”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，不能说“会画画的房子”。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是物，不能说“会画画”。"}], "explanations": {"阿姨": "正确：“阿姨”指女性，符合“会画画的”这一描述。", "作品": "语义：“作品”是物，不能说“会画画”。", "房子": "语义：“房子”不是人，不能说“会画画的房子”。", "颜料": "语义：“颜料”是物，不能说“会画画”。"}, "sentence_index": 6, "correct_answer": "阿姨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的阿姨和我同岁，我们在一个班里上课。", "explanation": "这里应该用〈同学〉。阿姨指年纪比小朋友大的女性，不能和说话人同岁、同班。"}, {"text": "她是我的阿姨，才三岁。", "explanation": "这里应该用〈女儿〉。阿姨是成年女性的称呼，三岁的孩子不能是阿姨。"}, {"text": "我的阿姨是一位留着胡子的老先生，他每天给我讲故事。", "explanation": "这里应该用〈爷爷〉。阿姨指女性，不能用来称呼男性老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只阿姨，她会弹钢琴。", "corrected_sentence": "我有一位阿姨，她会弹钢琴。", "error_description": "量词错误：“阿姨”指人，应用量词“位”（或“个”）。“只”用于动物，应改为“一位阿姨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很漂亮阿姨每天都来我家玩。", "corrected_sentence": "这位很漂亮的阿姨每天都来我家玩。", "error_description": "修饰语漏掉“的”。“很漂亮”修饰“阿姨”时，应说“很漂亮的阿姨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
