INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95303, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "嘴巴一下子咬或喝的那么多。", "primary_collocate": null, "pronunciation": "yī kǒu", "ipa": "i˥˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我咬了一口苹果。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你喝一口水。", "target_word": "一口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他尝了一口汤，说太咸。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我吃一口饭再去玩。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯茶太烫，我只喝了一口。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟大大地咬了一口蛋糕，嘴里都是奶油。", "target_word": "一口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包子很好吃，让我再咬一口。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起杯子，喝了一口咖啡。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗咬了我一口，我很疼。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那块肉很香，我吃了一口还想吃。", "target_word": "一口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一小口", "label": "复合"}, {"form": "一大口", "label": "复合"}], "register": "口语", "sense_fingerprint": "嘴巴一次咬、喝、吃的量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口（yī kǒu）：嘴巴一次咬、喝、吃下的量。"}, {"text": "衣扣", "is_correct": false, "explanation": "衣扣（yī kòu）与 kǒu 声调不同，kòu 是第四声，意思是衣服上的纽扣。"}, {"text": "衣篓", "is_correct": false, "explanation": "衣篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是装衣物的篓子。"}, {"text": "一篓", "is_correct": false, "explanation": "一篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是一篓（盛装的量）。"}], "explanations": {"一口": "一口（yī kǒu）：嘴巴一次咬、喝、吃下的量。", "衣扣": "衣扣（yī kòu）与 kǒu 声调不同，kòu 是第四声，意思是衣服上的纽扣。", "衣篓": "衣篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是装衣物的篓子。", "一篓": "一篓（yī lǒu）与 kǒu 声母不同，l 与 k 不同，意思是一篓（盛装的量）。"}, "sentence_index": null, "correct_answer": "一口"}, "level_3": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口：一次咬下的量，与“咬”搭配。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“本”用于书籍，不用于计量咬苹果的动作。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”多用于平面的东西，咬苹果不能用“张”。"}, {"text": "一场", "is_correct": false, "explanation": "语义：“场”指一次活动或比赛，与咬下一次的动作不合。"}], "explanations": {"一口": "一口：一次咬下的量，与“咬”搭配。", "一本": "搭配：“本”用于书籍，不用于计量咬苹果的动作。", "一张": "搭配：“张”多用于平面的东西，咬苹果不能用“张”。", "一场": "语义：“场”指一次活动或比赛，与咬下一次的动作不合。"}, "sentence_index": 0, "correct_answer": "一口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你轻轻碰一口门。", "explanation": "这里应该用〈一下〉。“一口”只指一次咬、喝、吃的量，碰门要说“碰一下”。"}, {"text": "他在河边捡了一口石头。", "explanation": "这里应该用〈一块〉或〈一颗〉。“一口”只用于咬、喝、吃的量，石头要用量词“块”或“颗”。"}, {"text": "我买了一口书。", "explanation": "这里应该用〈一本〉。“一口”只用于咬、喝、吃的量，书要用量词“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一口", "is_correct": true, "explanation": "一口：一次咬下的量，与“咬”搭配。"}, {"text": "一股", "is_correct": false, "explanation": "搭配：“股”多用于气味或力气，不用于咬东西的量。"}, {"text": "一阵", "is_correct": false, "explanation": "语义：“阵”指一段时间或一阵子，与咬下一次的动作不合。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于一只手能握住的量，咬东西不用“把”。"}], "explanations": {"一口": "一口：一次咬下的量，与“咬”搭配。", "一股": "搭配：“股”多用于气味或力气，不用于咬东西的量。", "一阵": "语义：“阵”指一段时间或一阵子，与咬下一次的动作不合。", "一把": "搭配：“把”用于一只手能握住的量，咬东西不用“把”。"}, "sentence_index": 6, "correct_answer": "一口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抓了一口米。", "explanation": "这里应该用〈一把〉。“一口”指咬、喝、吃的量，抓取要用“一把”。"}, {"text": "她养了一口猫。", "explanation": "这里应该用〈一只〉。“一口”只用于咬、喝、吃的量，猫要用量词“只”。"}, {"text": "我修好了一口手机。", "explanation": "这里应该用〈一部〉。“一口”只用于咬、喝、吃的量，手机要用量词“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喝了大一口牛奶。", "corrected_sentence": "他喝了一大口牛奶。", "error_description": "错误：“大一口”；正确：“一大口”。修饰“口”的“大”要放在数量短语“一口”的前面，说“一大口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹看了一口饼干。", "corrected_sentence": "妹妹咬了一口饼干。", "error_description": "错误：“看了一口饼干”；正确：“咬了一口饼干”。“一口”指咬、喝、吃下的量，不能与动词“看”搭配，应说“咬了一口饼干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
