INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不同意法院的决定，请更高的法院再看一次。", "primary_collocate": null, "pronunciation": "shàng sù", "ipa": "ʂɑŋ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "他不同意法院的决定，决定上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不服法院的判决，马上上诉了。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以向更高的法院上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不服一审判决，准备向更高的法院上诉。", "target_word": "上诉", "complexity_tier": "T3", "furigana": "shàng sù", "sentence_source": "generated"}, {"text": "公司对这个决定不满意，准备上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前上诉过一次，可是没有成功。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院的决定让他很生气，他说一定要上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不同意法院的决定，可以上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师告诉我们，十五天以内可以上诉。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生上诉到了更高的法院。", "target_word": "上诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上诉了", "label": "体标"}, {"form": "上诉过", "label": "体标"}, {"form": "上诉人", "label": "复合"}], "register": "正式", "sense_fingerprint": "不同意法院的决定，请更高的法院再审一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上诉", "is_correct": true, "explanation": "正确：上诉指不服法院决定、请上级法院再审，正好与“不同意法院的决定”相合。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”与前文的“不同意”直接矛盾。"}, {"text": "执行", "is_correct": false, "explanation": "语义：执行意味着照办，与“不同意”的态度相反。"}, {"text": "道歉", "is_correct": false, "explanation": "搭配：道歉表示认错，与前文表示不同意、决定采取行动的语境不搭配。"}], "explanations": {"上诉": "正确：上诉指不服法院决定、请上级法院再审，正好与“不同意法院的决定”相合。", "同意": "语义：“同意”与前文的“不同意”直接矛盾。", "执行": "语义：执行意味着照办，与“不同意”的态度相反。", "道歉": "搭配：道歉表示认错，与前文表示不同意、决定采取行动的语境不搭配。"}, "sentence_index": 0, "correct_answer": "上诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决定向法院上诉这家公司。", "explanation": "这里应该用“起诉”。上诉针对已经作出的判决，要求上级法院再审；首次把对方告上法院要用起诉。"}, {"text": "他向警察上诉，说有人偷了他的钱。", "explanation": "这里应该用“报案”。上诉是对法院判决提出再审请求，向警察反映被盗要用报案。"}, {"text": "学校的决定让他很不满，他写了一封信上诉。", "explanation": "这里应该用“申诉”。上诉只用于不服法院判决、请上级法院再审；对学校的决定提出异议要用申诉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上诉", "is_correct": true, "explanation": "正确：上诉表示生气后仍要请上级法院再审，与“他说一定要”的坚持语气相合。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：感谢需要感谢的对象作宾语，这里“一定要感谢”后面没有宾语，句子不完整。"}, {"text": "投降", "is_correct": false, "explanation": "语义：投降是认输、放弃抵抗，与“一定要”的坚持态度矛盾。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：他正在生气，“一定要微笑”与前文的情绪直接矛盾。"}], "explanations": {"上诉": "正确：上诉表示生气后仍要请上级法院再审，与“他说一定要”的坚持语气相合。", "感谢": "配价：感谢需要感谢的对象作宾语，这里“一定要感谢”后面没有宾语，句子不完整。", "投降": "语义：投降是认输、放弃抵抗，与“一定要”的坚持态度矛盾。", "微笑": "语义：他正在生气，“一定要微笑”与前文的情绪直接矛盾。"}, "sentence_index": 6, "correct_answer": "上诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明上诉到了五楼的教室。", "explanation": "这里应该用“上楼”。上诉是法律用语，指不服判决请上级法院再审，不能表示上楼。"}, {"text": "她把委屈向妈妈上诉了一番。", "explanation": "这里应该用“诉苦”。上诉是法律程序，向家人倾诉委屈要用诉苦。"}, {"text": "她在报纸上上诉了一篇文章。", "explanation": "这里应该用“发表”。上诉的对象是法院判决，文章在报纸上要用发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不服判决，决定向法院上诉着。", "corrected_sentence": "他不服判决，决定向法院上诉。", "error_description": "错误：“上诉”后多加了“着”。上诉是一次性的动作，不能带“着”，应说“决定向法院上诉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "李女士上诉了最高的法院。", "corrected_sentence": "李女士上诉到了最高的法院。", "error_description": "错误：“上诉”后漏掉了“到”。上诉表示向上级法院提出请求，应说“上诉到最高的法院”，“上诉了最高的法院”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
