INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95310, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不符合标准或规范。", "primary_collocate": null, "pronunciation": "bù biāo zhǔn", "ipa": "pu˥˩ pjɑʊ˥ ʈʂwən˨˩", "syllable_count": 3, "sentences": [{"text": "他的发音不标准，我听不太懂。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个尺寸不标准，门装不上。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表的格式不标准，要重新做。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我写的字不标准。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法不标准，会有危险。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的普通话还不标准。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的大小不标准，不能寄。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛用的球不标准，大家都不满意。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的动作不标准，教练让他再做一次。", "target_word": "不标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地址的格式不标准，快递送不到。", "target_word": "不标准", "complexity_tier": "T3", "furigana": "zhè gè dì zhǐ de gé shì bù biāo zhǔn, kuài dì sòng bu dào.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不標準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不符合标准或规范", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10b2f6b-6e2b-4fc3-8a1e-105a8b61b983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不标准", "is_correct": true, "explanation": "“不标准”说发音不合规范，正好解释了后句“我听不太懂”的原因。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”说发音明白易懂，与后句“我听不太懂”矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列或队伍有序，不用来形容发音。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材外形，不能用来形容发音。"}], "explanations": {"不标准": "“不标准”说发音不合规范，正好解释了后句“我听不太懂”的原因。", "清晰": "语义：“清晰”说发音明白易懂，与后句“我听不太懂”矛盾。", "整齐": "搭配：“整齐”说排列或队伍有序，不用来形容发音。", "高大": "体貌：“高大”形容人的身材外形，不能用来形容发音。"}, "sentence_index": 0, "correct_answer": "不标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的数字很不标准，需要重新核对。", "explanation": "这里应该用〈不准确〉。不标准指不符合标准或规范，多用于发音、尺寸、做法；数字的对错要说不准确。"}, {"text": "这个要求很不标准，我们不能接受。", "explanation": "这里应该用〈不合理〉。不标准用于可以对照规定的事物；要求有没有道理要说不合理。"}, {"text": "他这次投资的眼光很不标准，亏了很多钱。", "explanation": "这里应该用〈不准〉。不标准指不符合规定，判断对不对、准不准要说不准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不标准", "is_correct": true, "explanation": "“不标准”说大小不符合规定，正好解释了“不能寄”的原因。"}, {"text": "合适", "is_correct": false, "explanation": "语义：“合适”说大小正好，与后句“不能寄”矛盾。"}, {"text": "宽松", "is_correct": false, "explanation": "搭配：“宽松”多用于衣服或空间，不用来形容箱子的大小。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外观好看，不能用来描述箱子的大小。"}], "explanations": {"不标准": "“不标准”说大小不符合规定，正好解释了“不能寄”的原因。", "合适": "语义：“合适”说大小正好，与后句“不能寄”矛盾。", "宽松": "搭配：“宽松”多用于衣服或空间，不用来形容箱子的大小。", "漂亮": "体貌：“漂亮”说外观好看，不能用来描述箱子的大小。"}, "sentence_index": 6, "correct_answer": "不标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的情节很不标准，让人看不下去。", "explanation": "这里应该用〈不精彩〉。不标准指不符合规定，情节好不好要说不精彩。"}, {"text": "这次会议的时间很不标准，大家都没来。", "explanation": "这里应该用〈不合适〉。不标准指不符合规定，时间安排是否妥当要说不合适。"}, {"text": "他的笑容很不标准，看起来有点假。", "explanation": "这里应该用〈不自然〉。不标准指不符合规定，笑得自不自然要说不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张卡片的尺寸不标准的，放不进盒子。", "corrected_sentence": "这张卡片的尺寸不标准，放不进盒子。", "error_description": "错误形式：不标准的；正确形式：不标准。作谓语的形容词后面多加了“的”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份申请表填写的不标准，需要改一下。", "corrected_sentence": "这份申请表填写得不标准，需要改一下。", "error_description": "错误形式：填写的不标准；正确形式：填写得不标准。动作之后说明程度或结果的补语要用“得”连接，用“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa67c596-f682-4c12-8a7a-11802c00d547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
