INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用中国老办法，比如草药，给人看病的医生。", "primary_collocate": null, "pronunciation": "zhōng yī", "ipa": "ʈʂʊŋ⁵⁵ i⁵⁵", "syllable_count": 2, "sentences": [{"text": "我去看中医，医生给我开了草药。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中医给病人把了脉。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的病是一位老中医治好的。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一名中医。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位中医问我睡得好不好。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近有一位很有名的中医。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医说我最近上火，要少吃辣的。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去找中医看咳嗽。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是中医，每天在诊所给人看病。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老中医开的药方要用水煮着喝。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老中医", "label": "复合词"}, {"form": "中醫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用草药等传统方法给人看病的医生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：中医，指用草药等传统方法给人看病的医生。"}, {"text": "周一", "is_correct": false, "explanation": "zhōu 与 zhōng 的韵母不同，意思是星期一。"}, {"text": "中意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是满意、喜欢。"}, {"text": "中西", "is_correct": false, "explanation": "xī 与 yī 的声母不同，意思是中国和西方。"}, {"text": "中期", "is_correct": false, "explanation": "qī 与 yī 的声母不同，意思是一段时期的中间。"}], "explanations": {"中医": "正确：中医，指用草药等传统方法给人看病的医生。", "周一": "zhōu 与 zhōng 的韵母不同，意思是星期一。", "中意": "yì（第四声）与 yī（第一声）声调不同，意思是满意、喜欢。", "中西": "xī 与 yī 的声母不同，意思是中国和西方。", "中期": "qī 与 yī 的声母不同，意思是一段时期的中间。"}, "sentence_index": null, "correct_answer": "中医"}, "level_3": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：“看中医”指去找用草药治病的医生，符合后半句“医生给我开了草药”。"}, {"text": "西医", "is_correct": false, "explanation": "语义：西医一般不开草药，与“医生给我开了草药”的描述不符。"}, {"text": "中文", "is_correct": false, "explanation": "搭配：“看”后面接的是人或医疗机构，“中文”指语言，不能说“看中文”。"}, {"text": "中学", "is_correct": false, "explanation": "语义：中学是学校，不是看病的地方，也不能给人开草药。"}], "explanations": {"中医": "正确：“看中医”指去找用草药治病的医生，符合后半句“医生给我开了草药”。", "西医": "语义：西医一般不开草药，与“医生给我开了草药”的描述不符。", "中文": "搭配：“看”后面接的是人或医疗机构，“中文”指语言，不能说“看中文”。", "中学": "语义：中学是学校，不是看病的地方，也不能给人开草药。"}, "sentence_index": 0, "correct_answer": "中医"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃了一位中医。", "explanation": "这里应该用〈药〉。“吃”的对象是药或饭，“中医”指医生，不能吃。"}, {"text": "他找了一张中医。", "explanation": "这里应该用〈位〉。指人的量词用“位”，“张”用于平面的东西，不能用来数医生。"}, {"text": "他住进了中医。", "explanation": "这里应该用〈医院〉。“住进”的对象是医院等场所，“中医”指医生，不能当作场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：“中医”是能给建议的医生，符合“说我最近上火，要少吃辣的”。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间词，不会说话，也不会给出饮食建议。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是致病的微生物，不会说话，也不会给出饮食建议。"}, {"text": "中国", "is_correct": false, "explanation": "搭配：“说”的主语应是能说话的人，“中国”是国家，不能这样搭配。"}], "explanations": {"中医": "正确：“中医”是能给建议的医生，符合“说我最近上火，要少吃辣的”。", "中午": "语义：“中午”是时间词，不会说话，也不会给出饮食建议。", "病毒": "语义：病毒是致病的微生物，不会说话，也不会给出饮食建议。", "中国": "搭配：“说”的主语应是能说话的人，“中国”是国家，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "中医"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认识了一颗中医。", "explanation": "这里应该用〈位〉。指人的量词用“位”，“颗”用于颗粒状的东西，不能用来数医生。"}, {"text": "这件中医很漂亮。", "explanation": "这里应该用〈衣服〉。“中医”指医生或医学体系，不能当作衣服来形容。"}, {"text": "他躺在中医里休息。", "explanation": "这里应该用〈病房〉。“躺在……里”的对象是房间或场所，“中医”指医生，不是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想请一张中医看看。", "corrected_sentence": "我想请一位中医看看。", "error_description": "错误：“一张中医”。正确：“一位中医”。指人的量词用“位”，“张”用于平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爷爷请过一中医。", "corrected_sentence": "我爷爷请过一位中医。", "error_description": "错误：“一中医”。正确：“一位中医”。指人的量词用“位”，数量词和名词之间要有量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
