INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以中国传统医学理论和方法治病的医学，也指这类医生。", "primary_collocate": null, "pronunciation": "zhōng yī", "ipa": "ʈʂʊŋ⁵⁵ i⁵⁵", "syllable_count": 2, "sentences": [{"text": "中医讲究整体调理身体。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外国人对中医很感兴趣。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学的是中医。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医常用草药和针灸治病。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医认为人要顺着季节养生。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院既有中医，也有西医。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶相信中医，不太喜欢吃西药。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医的历史有几千年。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医和西医在治病方法上有不同。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去中国学习中医。", "target_word": "中医", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中醫", "label": "繁体"}, {"form": "中医学", "label": "复合词"}], "register": "中性", "sense_fingerprint": "中国传统医学体系及其治病方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67f8dfb-e267-437b-9944-79bb6626f076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：中医，指以中国传统医学理论治病的体系。"}, {"text": "周一", "is_correct": false, "explanation": "zhōu 与 zhōng 的韵母不同，意思是星期一。"}, {"text": "中意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是满意、喜欢。"}, {"text": "中西", "is_correct": false, "explanation": "xī 与 yī 的声母不同，意思是中国和西方。"}, {"text": "中期", "is_correct": false, "explanation": "qī 与 yī 的声母不同，意思是一段时期的中间。"}], "explanations": {"中医": "正确：中医，指以中国传统医学理论治病的体系。", "周一": "zhōu 与 zhōng 的韵母不同，意思是星期一。", "中意": "yì（第四声）与 yī（第一声）声调不同，意思是满意、喜欢。", "中西": "xī 与 yī 的声母不同，意思是中国和西方。", "中期": "qī 与 yī 的声母不同，意思是一段时期的中间。"}, "sentence_index": null, "correct_answer": "中医"}, "level_3": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：“中医”指以中国传统医学治病的体系，“讲究整体调理”正是它的特点。"}, {"text": "西医", "is_correct": false, "explanation": "语义：西医注重化验和手术，不强调整体调理身体，与句子的描述不符。"}, {"text": "中文", "is_correct": false, "explanation": "搭配：“讲究”后面接的是理论或方法，“中文”指语言，不能这样搭配。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间词，不能作为讲究的治病理论或方法。"}], "explanations": {"中医": "正确：“中医”指以中国传统医学治病的体系，“讲究整体调理”正是它的特点。", "西医": "语义：西医注重化验和手术，不强调整体调理身体，与句子的描述不符。", "中文": "搭配：“讲究”后面接的是理论或方法，“中文”指语言，不能这样搭配。", "中午": "语义：“中午”是时间词，不能作为讲究的治病理论或方法。"}, "sentence_index": 0, "correct_answer": "中医"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝一碗中医。", "explanation": "这里应该用〈中药〉。“中药”指药材和药剂，可以“喝一碗”；“中医”指医学体系或医生，不是饮品。"}, {"text": "他买了一服中医。", "explanation": "这里应该用〈汤药〉。“服”是计量汤药的量词，“中医”指医学体系，不能像药剂一样买来计量。"}, {"text": "他每天在窗台上晒中医。", "explanation": "这里应该用〈草药〉。“晒”用于草药、粮食等实物，“中医”指医学体系，不能晒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中医", "is_correct": true, "explanation": "正确：“中医”是奶奶相信的治病体系，与后半句“不太喜欢吃西药”形成对比。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间词，不能作为“相信”的对象。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是致病的微生物，不是可以相信的对象，与句子的意思不符。"}, {"text": "中学", "is_correct": false, "explanation": "搭配：“相信”后面接的是可以相信的人或观念，“中学”指学校阶段，不能这样搭配。"}], "explanations": {"中医": "正确：“中医”是奶奶相信的治病体系，与后半句“不太喜欢吃西药”形成对比。", "中午": "语义：“中午”是时间词，不能作为“相信”的对象。", "病毒": "语义：病毒是致病的微生物，不是可以相信的对象，与句子的意思不符。", "中学": "搭配：“相信”后面接的是可以相信的人或观念，“中学”指学校阶段，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "中医"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开了一张中医。", "explanation": "这里应该用〈药方〉。“开”和“张”搭配的是药方，“中医”是医学体系，不能当作开出的东西。"}, {"text": "她收了两块中医。", "explanation": "这里应该用〈药材〉，说“收了两味药材”。“中医”是医学体系，不是可以收的实物。"}, {"text": "他这次得了一场中医。", "explanation": "这里应该用〈病〉。“得”后面接的是疾病，“一场”也用于病，“中医”是医学体系，不能当作病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学过一张中医。", "corrected_sentence": "他学过一门中医。", "error_description": "错误：“一张中医”。正确：“一门中医”。“张”用于平面的东西，学科、技艺一类用“门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是中医地特点。", "corrected_sentence": "这是中医的特点。", "error_description": "错误：定语标记“的”误用为“地”。“地”用于修饰动词、形容词，名词定语要用“的”，应写作“中医的特点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bd675e3-c938-486a-bec4-7c7114a7efcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
