INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古时候，晚上的第二段时间，大约是半夜前。", "primary_collocate": null, "pronunciation": "èr gēng", "ipa": "aɚ˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "古时候，二更是半夜前的时间。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二更天，书生还在灯下读书。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打更的人在二更敲了两下。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二更到了，大家都该休息了。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了二更，村里的灯一盏盏灭了。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天二更时，下起了小雨。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们二更出门，三更才回来。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人说的二更，现在是晚上十点左右。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二更时，月亮已经升得很高。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她等到二更，朋友还没回来。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二更天", "label": "复合"}], "register": "书面", "sense_fingerprint": "古时夜里的第二段时间，约在半夜之前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二更", "is_correct": true, "explanation": "正确：二更是半夜之前的时段，与句中的定义一致。"}, {"text": "三更", "is_correct": false, "explanation": "语义：三更即子时（约23时至次日1时），正处在半夜前后，与指半夜前时段的二更不同。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜就是半夜，不在半夜之前。"}, {"text": "鸡鸣", "is_correct": false, "explanation": "语义：鸡鸣指凌晨快天亮的时候，并不是半夜前的时段。"}], "explanations": {"二更": "正确：二更是半夜之前的时段，与句中的定义一致。", "三更": "语义：三更即子时（约23时至次日1时），正处在半夜前后，与指半夜前时段的二更不同。", "午夜": "语义：午夜就是半夜，不在半夜之前。", "鸡鸣": "语义：鸡鸣指凌晨快天亮的时候，并不是半夜前的时段。"}, "sentence_index": 0, "correct_answer": "二更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凌晨两点，二更的鼓声响了，街上一片寂静。", "explanation": "这里不能用〈二更〉。“二更”指半夜前大约十点左右的时段，凌晨两点已是更晚的时间，应说〈四更〉。"}, {"text": "我们二更吃完午饭，就到地里干活去了。", "explanation": "这里应该用〈中午〉。“二更”指半夜前大约十点左右，吃午饭的时间应在白天，不能用“二更”。"}, {"text": "太阳出来以后，我们二更才起床。", "explanation": "这里不能用〈二更〉。“二更”指夜里约十点，太阳出来以后起床应说〈早上〉，二更与日出矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二更", "is_correct": true, "explanation": "正确：二更在三更之前，与“三更才回来”的顺序相符。"}, {"text": "五更", "is_correct": false, "explanation": "语义：五更在三更之后，出门的时间晚于“三更才回来”，前后矛盾。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：黎明在三更之后，出门的时间晚于“三更才回来”，前后矛盾。"}, {"text": "晨曦", "is_correct": false, "explanation": "语义：晨曦指天快亮时的光线，时间在三更之后，出门时间晚于“三更才回来”，前后矛盾。"}], "explanations": {"二更": "正确：二更在三更之前，与“三更才回来”的顺序相符。", "五更": "语义：五更在三更之后，出门的时间晚于“三更才回来”，前后矛盾。", "黎明": "语义：黎明在三更之后，出门的时间晚于“三更才回来”，前后矛盾。", "晨曦": "语义：晨曦指天快亮时的光线，时间在三更之后，出门时间晚于“三更才回来”，前后矛盾。"}, "sentence_index": 6, "correct_answer": "二更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二更，村口的鸡开始打鸣，大家都醒了。", "explanation": "这里应该用〈清晨〉。“二更”是夜里的时段，鸡打鸣、大家醒来的情景应说〈清晨〉。"}, {"text": "二更时，我们开始下地干活。", "explanation": "这里应该用〈日出〉。“二更”在夜里，下地干活应在日出之后。"}, {"text": "他二更就烧好了水，准备做早饭。", "explanation": "这里应该用〈清早〉。“二更”是夜里的时段，烧水做早饭应在清早，不能用“二更”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一个二更时关了门。", "corrected_sentence": "他在二更时关了门。", "error_description": "“二更”是时间名词，前面不能加数量短语“一个”，应说“二更”，不能说“一个二更”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二更的之前，村里的人都睡下了。", "corrected_sentence": "二更之前，村里的人都睡下了。", "error_description": "“之前”前面的时间词后面直接接“之前”，中间不能插入“的”。应说“二更之前”，不能说“二更的之前”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
