INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时把一夜分为五更，第二更约在晚上九点至十一点。", "primary_collocate": null, "pronunciation": "èr gēng", "ipa": "aɚ˥˩ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "旧时候，晚上九点到十一点叫二更。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二更的时候，街上已经没有人了。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打更人敲了二更的鼓。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，现在是二更天了。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "二更一过，城里就安静了。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了二更，他才回到家。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里写着：“二更时分，月亮升起来了。”", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时一夜分为五更，二更在晚上。", "target_word": "二更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二更到了，店铺都关门了。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读书读到二更才睡。", "target_word": "二更", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "二更天", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时五更计时中的第二更，约晚上九点到十一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二更", "is_correct": true, "explanation": "正确：二更指夜里九点到十一点，与句中的时段一致。"}, {"text": "三更", "is_correct": false, "explanation": "语义：三更指夜里十一点到凌晨一点，与“九点到十一点”对不上。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜指半夜十二点前后，不在九点到十一点之间。"}, {"text": "大半夜", "is_correct": false, "explanation": "语域：“大半夜”是口语说法，与这种书面定义句的语体不合，而且它指很深的夜，不是九点到十一点。"}], "explanations": {"二更": "正确：二更指夜里九点到十一点，与句中的时段一致。", "三更": "语义：三更指夜里十一点到凌晨一点，与“九点到十一点”对不上。", "午夜": "语义：午夜指半夜十二点前后，不在九点到十一点之间。", "大半夜": "语域：“大半夜”是口语说法，与这种书面定义句的语体不合，而且它指很深的夜，不是九点到十一点。"}, "sentence_index": 0, "correct_answer": "二更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他二更才吃午饭，饿得不行。", "explanation": "这里应该用〈中午〉。“二更”专指夜里九点到十一点，吃午饭的时间是白天，不能用“二更”。"}, {"text": "我吃完早饭，二更就出门上班了。", "explanation": "这里应该用〈早上〉。“二更”专指夜里九点到十一点，吃完早饭后出门应是清晨，不能用“二更”。"}, {"text": "二更的阳光很暖和，我们在院子里晒太阳。", "explanation": "这里应该用〈午后〉。“二更”是夜里的时段，夜里没有阳光，应说“午后的阳光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二更", "is_correct": true, "explanation": "正确：二更是夜里的时段，与“月亮升起来了”的夜景一致。"}, {"text": "正午", "is_correct": false, "explanation": "语义：正午是白天最亮的时候，与夜里“月亮升起来”的书面意境不合。"}, {"text": "晌午", "is_correct": false, "explanation": "语域：“晌午”是口语或方言说法，与书面引文的语体不合，而且也指白天。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是白天，与“月亮升起来”的情景对不上。"}], "explanations": {"二更": "正确：二更是夜里的时段，与“月亮升起来了”的夜景一致。", "正午": "语义：正午是白天最亮的时候，与夜里“月亮升起来”的书面意境不合。", "晌午": "语域：“晌午”是口语或方言说法，与书面引文的语体不合，而且也指白天。", "中午": "语义：中午是白天，与“月亮升起来”的情景对不上。"}, "sentence_index": 6, "correct_answer": "二更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天二更起床，跑步一个小时。", "explanation": "这里应该用〈早晨〉。“二更”是夜里的时段，不用来说起床的早上时间。"}, {"text": "学生们二更在操场上做早操，大家都很精神。", "explanation": "这里应该用〈清晨〉。“二更”是夜里的时段，做早操是清晨的活动，二更不合。"}, {"text": "二更时，炊烟升起来了，家家都在做饭。", "explanation": "这里应该用〈黄昏〉。炊烟和做饭多在黄昏，“二更”是夜里的时段，说炊烟升起来就不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上的人在一只二更时都回家了。", "corrected_sentence": "街上的人在二更时都回家了。", "error_description": "量词“只”用于动物或成对的器物，不能用来修饰时间词“二更”。应直接说“在二更时”，不说“在一只二更时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们聊天聊到的二更才散。", "corrected_sentence": "我们聊天聊到二更才散。", "error_description": "助词位置错误：动词“聊到”后面直接接时间词，中间不能插入“的”。应说“聊到二更才散”，不能说“聊到的二更才散”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
