INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "居住的地方。", "primary_collocate": null, "pronunciation": "zhù dì", "ipa": "ʈʂu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这里是工人们的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的住地很简单，可是很干净。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们终于在河边找到了新住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子是他们祖辈的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想为家人换一个好住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友的住地靠近公园。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把住地打扫得很干净。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些民工的住地条件不太好。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你们在北京的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们看了工人的住地。", "target_word": "住地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个住地", "label": "量词"}], "register": "中性", "sense_fingerprint": "居住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住地", "is_correct": true, "explanation": "正确：住地指居住的地方，“这里是工人们的……”指的正是他们住的地方。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不是场所，不能说“这里是工人们的工资”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是场所，不能说“这里是工人们的年龄”。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“这里是……的”要接地点或场所，身份证是证件，不能这样说。"}], "explanations": {"住地": "正确：住地指居住的地方，“这里是工人们的……”指的正是他们住的地方。", "工资": "语义：工资是收入，不是场所，不能说“这里是工人们的工资”。", "年龄": "语义：年龄是岁数，不是场所，不能说“这里是工人们的年龄”。", "身份证": "搭配：“这里是……的”要接地点或场所，身份证是证件，不能这样说。"}, "sentence_index": 0, "correct_answer": "住地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里是茶叶的住地。", "explanation": "这里应该用〈产地〉。住地指人居住的地方，茶叶不住人，要说“产地”。"}, {"text": "这里是长江的住地。", "explanation": "这里应该用〈发源地〉。住地指人居住的地方，长江不住人，要说“发源地”。"}, {"text": "这片树林是老人安葬的住地。", "explanation": "这里应该用〈墓地〉。住地指人居住的地方，安葬之处要说“墓地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住地", "is_correct": true, "explanation": "正确：“打扫”的对象可以是住的地方，“打扫住地”很自然。"}, {"text": "脸", "is_correct": false, "explanation": "语义：“打扫”的对象是房间、场所，不能是脸。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场所，水果要说“洗”，不能说“打扫水果”。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“打扫”搭配地方或物品，“头发”应说“洗”。"}], "explanations": {"住地": "正确：“打扫”的对象可以是住的地方，“打扫住地”很自然。", "脸": "语义：“打扫”的对象是房间、场所，不能是脸。", "水果": "搭配：“打扫”的对象是房间、场所，水果要说“洗”，不能说“打扫水果”。", "头发": "搭配：“打扫”搭配地方或物品，“头发”应说“洗”。"}, "sentence_index": 6, "correct_answer": "住地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片住地是用来踢球的。", "explanation": "这里应该用〈场地〉。住地指人居住的地方，踢球的地方要说“场地”。"}, {"text": "这里是火箭的住地。", "explanation": "这里应该用〈发射场〉。住地指人居住的地方，火箭不住人，要说“发射场”。"}, {"text": "演出的住地在剧院。", "explanation": "这里应该用〈演出地点〉。住地指人居住的地方，演出不是人住的，要说“演出地点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里有一只住地。", "corrected_sentence": "这里有一处住地。", "error_description": "量词错误：“只”不能用来数“住地”，应改为“处”，说“一处住地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位住地是他们自己盖的。", "corrected_sentence": "这个住地是他们自己盖的。", "error_description": "量词错误：“位”用于人，不能用来数“住地”。应改为“个”，说“这个住地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
