INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95321, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来说明别的资料的资料。", "primary_collocate": null, "pronunciation": "yuán zī liào", "ipa": "ɥɛn˧˥ tsɨ˥ ljɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这份元资料说明了文件的来源。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆为每本电子书都建立了元资料。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元资料可以帮助我们快速找到需要的文件。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片的元资料里有拍摄的时间和地点。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查一下这些元资料对不对。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网站上添加了文章的元资料。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有元资料，我们很难知道这份资料是谁写的。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元资料就是说明资料的资料。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员正在整理图书的元资料。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统会自动记录每个文件的元资料。", "target_word": "元资料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "说明其他资料的资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午餐", "is_correct": false, "explanation": "语义：午餐是食物，无法说明文件的来源。"}, {"text": "元资料", "is_correct": true, "explanation": "元资料指说明其他资料的资料，正好说明文件的来源。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声是声音，不能用来说明文件的来源。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色只用来描述人的面部状态，不能用于文件。"}], "explanations": {"午餐": "语义：午餐是食物，无法说明文件的来源。", "元资料": "元资料指说明其他资料的资料，正好说明文件的来源。", "笑声": "语义：笑声是声音，不能用来说明文件的来源。", "脸色": "体貌：脸色只用来描述人的面部状态，不能用于文件。"}, "sentence_index": 0, "correct_answer": "元资料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份元资料讲了一个关于春天的故事。", "explanation": "这里应该用〈散文〉。元资料只描述其他资料的属性和来源，不讲述故事之类的内容。"}, {"text": "我买了一只元资料。", "explanation": "这里量词应该用〈份〉。“元资料”是资料类名词，只能用“份”，不能用“只”。"}, {"text": "这份元资料分析了今年的销售情况。", "explanation": "这里应该用〈报告〉。元资料只描述数据的属性和来源，不分析销售等具体内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙用来开锁，与资料的作者无关，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，不能用来指资料。"}, {"text": "元资料", "is_correct": true, "explanation": "元资料说明资料的属性和来源，正好符合“没有它就很难知道作者”的语境。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞与资料无关，句子无法成立。"}], "explanations": {"钥匙": "语义：钥匙用来开锁，与资料的作者无关，句子不通。", "身材": "体貌：身材描述人的体型，不能用来指资料。", "元资料": "元资料说明资料的属性和来源，正好符合“没有它就很难知道作者”的语境。", "雨伞": "语义：雨伞与资料无关，句子无法成立。"}, "sentence_index": 6, "correct_answer": "元资料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上写元资料，记录当天的事情。", "explanation": "这里应该用〈日记〉。元资料是描述数据属性的资料，不用来记录个人的日常经历。"}, {"text": "这份元资料画出了城市的道路。", "explanation": "这里应该用〈地图〉。元资料只描述其他资料的属性和来源，不画出道路等地理内容。"}, {"text": "这份元资料列出了今天的菜价。", "explanation": "这里应该用〈菜单〉。元资料不列出价格等具体内容，它只说明其他资料的属性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下载了一只元资料，里面有文件的作者和日期。", "corrected_sentence": "我下载了一份元资料，里面有文件的作者和日期。", "error_description": "“元资料”是资料类名词，量词应用“份”，说“一只元资料”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书管理员每天整理新的元资料们。", "corrected_sentence": "图书管理员每天整理新的元资料。", "error_description": "“元资料”是资料类名词，不能加“们”表示复数，应直接说“元资料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
