INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究身体里面生了什么病、怎样不用开刀来治的学问。", "primary_collocate": null, "pronunciation": "nèi kē xué", "ipa": "nei˥˩ kʰɤ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "内科学不用开刀治病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐正在学内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学研究身体里的病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当医生，所以学内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学课在星期三上午。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学的老师很会讲课。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本内科学课本太厚了。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学和外科学不一样。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对内科学特别有兴趣。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆看内科学的书。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內科學", "label": "繁体"}], "register": "专业", "sense_fingerprint": "研究身体内部疾病及不开刀治法的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。内科学以非手术治疗为主，符合“不用开刀治病”的说法。"}, {"text": "外科学", "is_correct": false, "explanation": "语义：外科学研究开刀治疗，与“不用开刀”矛盾。"}, {"text": "手术刀", "is_correct": false, "explanation": "语义：手术刀本身是用来开刀的工具，与“不用开刀”矛盾。"}, {"text": "病房", "is_correct": false, "explanation": "搭配：“治病”的施事应是医生或疗法，“病房”是场所，不能作主语治病。"}], "explanations": {"内科学": "正确。内科学以非手术治疗为主，符合“不用开刀治病”的说法。", "外科学": "语义：外科学研究开刀治疗，与“不用开刀”矛盾。", "手术刀": "语义：手术刀本身是用来开刀的工具，与“不用开刀”矛盾。", "病房": "搭配：“治病”的施事应是医生或疗法，“病房”是场所，不能作主语治病。"}, "sentence_index": 0, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打算学内科学，专门负责做手术。", "explanation": "这里应该用〈外科学〉。内科学以非手术治疗为主，做手术要学外科学。"}, {"text": "我上学期调到了内科学，负责门诊。", "explanation": "这里应该用〈内科〉。内科学指学问，不是科室；人员调到科室要说“调到内科”。"}, {"text": "她小时候得了内科学，住了一个月院。", "explanation": "这里应该用〈肺炎〉之类的病名。内科学是学问，不是疾病名称，不能说“得了内科学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。这里指内科学的课本，“这本”修饰书籍，符合句意。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能作课本的主题。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能作课本的主题。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“本”用于计量书籍，书包不能用“这本”计量。"}], "explanations": {"内科学": "正确。这里指内科学的课本，“这本”修饰书籍，符合句意。", "饼干": "语义：饼干是食品，不能作课本的主题。", "窗户": "语义：窗户是建筑部件，不能作课本的主题。", "书包": "搭配：“本”用于计量书籍，书包不能用“这本”计量。"}, "sentence_index": 6, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是很好的内科学，每天都在病房里工作。", "explanation": "这里应该用〈内科医生〉。内科学指学问，不指人；表示医生要说“内科医生”。"}, {"text": "他下周要去内科学报到，负责病房。", "explanation": "这里应该用〈内科〉。内科学是学问，不是科室；去科室报到要说“去内科”。"}, {"text": "他去年冬天得了内科学，咳嗽了很久。", "explanation": "这里应该用〈肺炎〉之类的病名。内科学是学问，不是疾病名称，不能说“得了内科学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐正在学一条内科学。", "corrected_sentence": "我姐姐正在学一门内科学。", "error_description": "错误在目标词的量词。“条”用于细长的东西，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在图书馆认真学习一位内科学。", "corrected_sentence": "他在图书馆认真学习一门内科学。", "error_description": "错误在目标词的量词。“位”用于人，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
