INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医学的一个分支，研究内脏疾病的诊断与非手术治疗。", "primary_collocate": null, "pronunciation": "nèi kē xué", "ipa": "nei˥˩ kʰɤ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "他在大学里学内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学研究内脏的疾病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对内科学很感兴趣。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学是医学的一个分支。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本内科学的书很厚。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王医生是内科学的专家。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学内科学要记很多知识。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内科学一般不用开刀治病。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明年想考内科学的研究生。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在医院研究内科学。", "target_word": "内科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內科學", "label": "繁体"}], "register": "专业", "sense_fingerprint": "医学分支，研究内脏疾病的诊断和非手术治疗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e57d5e-0600-40a5-bf17-17abc02ebec0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。内科学是医学的一个学科，可以在大学里学习，符合句意。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是可以学习的学科。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是需要治疗的人，不是学习的内容。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“学”后面要接知识或学科，“体温”是身体指标，不能说学体温。"}], "explanations": {"内科学": "正确。内科学是医学的一个学科，可以在大学里学习，符合句意。", "食堂": "语义：食堂是吃饭的地方，不是可以学习的学科。", "病人": "语义：病人是需要治疗的人，不是学习的内容。", "体温": "搭配：“学”后面要接知识或学科，“体温”是身体指标，不能说学体温。"}, "sentence_index": 0, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近得了内科学，要住院治疗。", "explanation": "这里应该用〈肺炎〉之类的病名。内科学是学问，不是疾病名称，不能说“得了内科学”。"}, {"text": "他这个月调到了内科学，负责病房。", "explanation": "这里应该用〈内科〉。内科学指学问，不是科室；人员调到科室要说“调到内科”。"}, {"text": "我姐姐是内科学。", "explanation": "这里应该用〈内科医生〉。内科学指学问，不指人，表示人要说“内科医生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。内科学需要记忆大量知识，符合句中“要记很多知识”的语境。"}, {"text": "药房", "is_correct": false, "explanation": "语义：药房是买药的地方，不是可以学习的学科。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不是学习的内容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“学”后面不能接身高这类身体特征。"}], "explanations": {"内科学": "正确。内科学需要记忆大量知识，符合句中“要记很多知识”的语境。", "药房": "语义：药房是买药的地方，不是可以学习的学科。", "沙发": "语义：沙发是家具，不是学习的内容。", "身高": "搭配：“学”后面不能接身高这类身体特征。"}, "sentence_index": 6, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想跟老师学内科学，将来能开刀。", "explanation": "这里应该用〈外科学〉。内科学以非手术治疗为主，不教开刀；开刀要学外科学。"}, {"text": "这位护士被分到内科学，负责发药。", "explanation": "这里应该用〈内科〉。内科学是学问，不是科室；护士分到科室要说“分到内科”。"}, {"text": "他是一名很厉害的内科学，经常给病人治病。", "explanation": "这里应该用〈内科医生〉。内科学指学问，不指人；表示医生要说“内科医生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下学期打算选一只内科学。", "corrected_sentence": "我下学期打算选一门内科学。", "error_description": "错误在目标词的量词。“只”用于动物等，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他决定在大学里认真学一座内科学。", "corrected_sentence": "他决定在大学里认真学一门内科学。", "error_description": "错误在目标词的量词。“座”用于山、楼房等大型固定物，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1aa0cdb8-5c9f-4351-9ef8-5b17def290c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
