INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对已经处理过的事物再次加工处理。", "primary_collocate": null, "pronunciation": "zài chǔ lǐ", "ipa": "tsaɪ˥˩ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "工厂把用过的水再处理，然后用来浇花。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水已经处理过，还要再处理一次才能排放。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧油经过一次处理后，工人又对它进行再处理。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核电站用完的燃料需要再处理。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批旧纸已经处理过一次，现在要再处理。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再处理后的垃圾，可以变成有用的东西。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污泥再处理以后，可以当成肥料用。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把处理过的废钢再处理，做成新的钢板。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做废电池的再处理工作。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次处理后水还不干净，只好再处理了一遍。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再处理了", "label": "完成体"}, {"form": "再处理过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对已处理过的废料、材料等再次加工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对已用过的水再加工，与“然后用来浇花”衔接自然。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：水丢弃之后又用来浇花，前后矛盾。"}, {"text": "喝掉", "is_correct": false, "explanation": "语义：水喝掉以后就不能再用来浇花了，前后不通。"}, {"text": "晒干", "is_correct": false, "explanation": "语义：水晒干之后就没有水了，不能再用来浇花，前后矛盾。"}], "explanations": {"再处理": "正确：再处理指对已用过的水再加工，与“然后用来浇花”衔接自然。", "丢弃": "语义：水丢弃之后又用来浇花，前后矛盾。", "喝掉": "语义：水喝掉以后就不能再用来浇花了，前后不通。", "晒干": "语义：水晒干之后就没有水了，不能再用来浇花，前后矛盾。"}, "sentence_index": 0, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批刚运来的新鲜木材，要再处理一下才能用。", "explanation": "这里应该用〈处理〉。“再处理”指对已经加工过的东西再加工，刚运来的木材还没有加工过。"}, {"text": "这只小狗很可爱，我们要再处理它，让它吃饱。", "explanation": "这里应该用〈喂养〉。“再处理”只用于废料、材料等物品，不能用于动物。"}, {"text": "这把坏了的椅子要再处理一下，才能坐人。", "explanation": "这里应该用〈修理〉。“再处理”是对废料、材料的再加工，不指修复坏了的家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对污泥再加工，才能再当成肥料用。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：污泥吃掉之后就没有了，不能再当成肥料用。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：污泥扔掉之后就没有了，不能再当成肥料用，前后矛盾。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：玩耍是娱乐的意思，与“处理后当成肥料用”毫不相关。"}], "explanations": {"再处理": "正确：再处理指对污泥再加工，才能再当成肥料用。", "吃掉": "语义：污泥吃掉之后就没有了，不能再当成肥料用。", "扔掉": "语义：污泥扔掉之后就没有了，不能再当成肥料用，前后矛盾。", "玩耍": "语义：玩耍是娱乐的意思，与“处理后当成肥料用”毫不相关。"}, "sentence_index": 6, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服脏了，我得再处理一遍。", "explanation": "这里应该用〈清洗〉。“再处理”指对已加工过的废料、材料再加工，衣服脏了不是这个意思。"}, {"text": "妈妈每天要再处理生病的爷爷。", "explanation": "这里应该用〈照顾〉。“再处理”不用于人，不能用来说照顾老人。"}, {"text": "这本英文书要再处理成中文。", "explanation": "这里应该用〈翻译〉。“再处理”指对物料的再加工，不指语言之间的转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧塑料瓶要送去再处理着。", "corrected_sentence": "这些旧塑料瓶要送去再处理。", "error_description": "“要……去”表示将要进行的动作，与表示持续状态的“着”不搭。应说“要送去再处理”，不能说“要送去再处理着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把废料再处理了一个遍。", "corrected_sentence": "工厂把废料再处理了一遍。", "error_description": "“遍”是动量词，前面的数词“一”后面直接接“遍”，不能加“个”，应说“再处理了一遍”，不能说“再处理了一个遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入国", "is_correct": true, "explanation": "入国与出国意思相反，指进入一个国家。"}, {"text": "散步", "is_correct": false, "explanation": "散步与出国没有反义关系，只是一种日常活动。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与出国没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与出国没有反义关系。"}], "correct_answer": "入国", "explanations": {"入国": "入国与出国意思相反，指进入一个国家。", "散步": "散步与出国没有反义关系，只是一种日常活动。", "睡觉": "睡觉与出国没有反义关系。", "唱歌": "唱歌与出国没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入国", "is_correct": true, "explanation": "入国与出国意思相反，指进入一个国家。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与出国没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书与出国没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与出国没有反义关系。"}], "correct_answer": "入国", "explanations": {"入国": "入国与出国意思相反，指进入一个国家。", "吃饭": "吃饭与出国没有反义关系。", "读书": "读书与出国没有反义关系。", "跑步": "跑步与出国没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开自己的国家，到别的国家去。", "primary_collocate": null, "pronunciation": "chū guó", "ipa": "ʈʂʰu˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "小王下个月就要出国了。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国以后，她每个星期给家里打电话。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有出国，所以不会说外语。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了学习艺术而出国。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办出国手续要花很多时间。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都来机场欢送他出国。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先工作两年再出国。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来没有出国，很想去看看。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想不想出国生活？", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国前把房子卖了。", "target_word": "出国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出过国", "label": "体标"}, {"form": "出国旅游", "label": "复合"}, {"form": "出國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "离开自己的国家去别国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出国", "is_correct": true, "explanation": "出国读作 chū guó，指离开自己的国家到别的国家去。"}, {"text": "出锅", "is_correct": false, "explanation": "guō（第一声）与 guó（第二声）声调不同，出锅意思是从锅里端出来。"}, {"text": "诸国", "is_correct": false, "explanation": "zhū 与 chū 声母不同（zh 与 ch），诸国意思是各个国家。"}, {"text": "出过", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，出过意思是曾经出去过。"}, {"text": "楚国", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，楚国是古代的国名。"}], "explanations": {"出国": "出国读作 chū guó，指离开自己的国家到别的国家去。", "出锅": "guō（第一声）与 guó（第二声）声调不同，出锅意思是从锅里端出来。", "诸国": "zhū 与 chū 声母不同（zh 与 ch），诸国意思是各个国家。", "出过": "guò（第四声）与 guó（第二声）声调不同，出过意思是曾经出去过。", "楚国": "chǔ（第三声）与 chū（第一声）声调不同，楚国是古代的国名。"}, "sentence_index": null, "correct_answer": "出国"}, "level_3": {"options": [{"text": "出国", "is_correct": true, "explanation": "正确：出国指离开本国到外国去，符合「就要……了」的语境。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：「出版」的对象须是书刊，不能用于「小王」这样的人。"}, {"text": "出血", "is_correct": false, "explanation": "语义：「出血」指身体流血，与「下个月就要」说不通。"}, {"text": "出笼", "is_correct": false, "explanation": "语义：「出笼」指蒸好的食物从蒸笼里拿出，不能用于人。"}], "explanations": {"出国": "正确：出国指离开本国到外国去，符合「就要……了」的语境。", "出版": "搭配：「出版」的对象须是书刊，不能用于「小王」这样的人。", "出血": "语义：「出血」指身体流血，与「下个月就要」说不通。", "出笼": "语义：「出笼」指蒸好的食物从蒸笼里拿出，不能用于人。"}, "sentence_index": 0, "correct_answer": "出国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们出国去郊外爬山。", "explanation": "这里应该用〈出城〉。郊外在本国境内，应说出城；出国指离开本国到外国去。"}, {"text": "晚饭后他出国看电视。", "explanation": "这里应该用〈回家〉。在家看电视不涉及离开本国，应说回家。"}, {"text": "我妈妈在英国工作十年，去年终于出国。", "explanation": "这里应该用〈回国〉。她已身在国外，回到本国应说回国；出国是从本国前往外国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出国", "is_correct": true, "explanation": "正确：出国指离开本国到外国去，与「再」和「工作两年」的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指降生，「工作两年再出生」说不通。"}, {"text": "出院", "is_correct": false, "explanation": "搭配：「出院」指病人离开医院，不能与「工作两年」搭配。"}, {"text": "出糗", "is_correct": false, "explanation": "语义：「出糗」指出丑，与「工作两年再」搭配不通。"}], "explanations": {"出国": "正确：出国指离开本国到外国去，与「再」和「工作两年」的语境相符。", "出生": "语义：「出生」指降生，「工作两年再出生」说不通。", "出院": "搭配：「出院」指病人离开医院，不能与「工作两年」搭配。", "出糗": "语义：「出糗」指出丑，与「工作两年再」搭配不通。"}, "sentence_index": 6, "correct_answer": "出国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下个月出国去北京开会。", "explanation": "这里应该用〈出差〉。去北京开会是国内出行，出国指离开本国到外国去。"}, {"text": "他的病好了，今天终于出国了。", "explanation": "这里应该用〈出院〉。出国指离开本国到外国去；病好后离开医院应说出院。"}, {"text": "早上七点他出国散步。", "explanation": "这里应该用〈出门〉。早上出门散步是在本地，出国指离开本国到外国去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年出着一次国。", "corrected_sentence": "她去年出过一次国。", "error_description": "体标「着」表示持续状态，不能用于已完成的一次性经历，应改为「过」：出过一次国。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出国过，去过英国。", "corrected_sentence": "他出过国，去过英国。", "error_description": "体标「过」应紧跟动词「出」，说「出过国」，不能说「出国过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
