INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把书做好，再印出来卖的地方。", "primary_collocate": null, "pronunciation": "chū bǎn shè", "ipa": "ʈʂʰu˥ pan˨˩ ʂɤ˥˩", "syllable_count": 3, "sentences": [{"text": "这家出版社的书很便宜。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校旁边有一家出版社。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社把他的书印了一万本。", "target_word": "出版社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的第一本书是在这家出版社出的。", "target_word": "出版社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典是一家大出版社印的。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给出版社打电话，问书什么时候能买到。", "target_word": "出版社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社门口有个小书店。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥想开一家自己的出版社。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家出版社专门印旅游书。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个出版社的书，纸好，字也大。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "大学出版社", "label": "复合"}], "register": "通用", "sense_fingerprint": "把书做好再印出来卖的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版社", "is_correct": true, "explanation": "出版社：把书做好再印出来卖的地方，“这家出版社的书”指这类机构出的书，符合句意。"}, {"text": "食品厂", "is_correct": false, "explanation": "语义：食品厂生产食品，不出版书籍，“这家食品厂的书很便宜”读不通。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不出版书籍，“这家理发店的书很便宜”与其经营内容无关。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“很便宜”说的是书的售价，银行不卖书，二者搭配不当。"}], "explanations": {"出版社": "出版社：把书做好再印出来卖的地方，“这家出版社的书”指这类机构出的书，符合句意。", "食品厂": "语义：食品厂生产食品，不出版书籍，“这家食品厂的书很便宜”读不通。", "理发店": "语义：理发店不出版书籍，“这家理发店的书很便宜”与其经营内容无关。", "银行": "搭配：“很便宜”说的是书的售价，银行不卖书，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "出版社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家出版社画了一幅画。", "explanation": "这里应该把主语改为〈画家〉。出版社做书、印书，不画画，画画的是画家。"}, {"text": "他在一只出版社工作。", "explanation": "这里应该用〈家〉。出版社是机构，量词要用“家”，不能用“只”。"}, {"text": "这家出版社拍了一部电影。", "explanation": "这里应该用〈电影公司〉。出版社印书卖书，不拍电影，拍电影的是电影公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出版社", "is_correct": true, "explanation": "出版社：把书做好再印出来卖的地方，“出版社门口有个小书店”描述的是这类机构旁边的书店，符合句意。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“门口”要求处所名词，“西瓜”不能用作有门口的地方，搭配不当。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会有门，“石头门口有个小书店”读不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然景观，不能说它有门口和书店，句意不通。"}], "explanations": {"出版社": "出版社：把书做好再印出来卖的地方，“出版社门口有个小书店”描述的是这类机构旁边的书店，符合句意。", "西瓜": "搭配：“门口”要求处所名词，“西瓜”不能用作有门口的地方，搭配不当。", "石头": "语义：石头不会有门，“石头门口有个小书店”读不通。", "大海": "语义：大海是自然景观，不能说它有门口和书店，句意不通。"}, "sentence_index": 6, "correct_answer": "出版社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出版社教了很多学生。", "explanation": "这里应该用〈学校〉。出版社印书卖书，不教学生，教学生是学校的工作。"}, {"text": "出版社治好了很多病人。", "explanation": "这里应该用〈医院〉。出版社不治病，治好病人是医院的工作。"}, {"text": "出版社的菜很好吃。", "explanation": "这里应该用〈餐厅〉。出版社出书，不做菜，菜好吃说的是餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只出版社印了一套百科全书。", "corrected_sentence": "那家出版社印了一套百科全书。", "error_description": "量词用错：出版社是机构，应用“家”，不能用“只”。应说“那家出版社”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她出版社实习过。", "corrected_sentence": "她在出版社实习过。", "error_description": "“出版社”作处所时前面要加“在”。应说“她在出版社实习过”，不能省去“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
