INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去加入一场比赛。", "primary_collocate": null, "pronunciation": "cān sài", "ipa": "tsʰan˥ sai˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校的篮球队明天去外地参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报名了，下个月要去北京参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李因为受伤，不能参赛了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次有二十个国家的选手来参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学游泳，今年第一次参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想参赛的话，要先在网上报名。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人一起去参赛，一定很有意思。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的中文不错，可以去参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前参赛过两次，不太紧张。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛明天开始，参赛的人都到了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参赛了", "label": "体标（了）"}, {"form": "参赛过", "label": "体标（过）"}, {"form": "参赛者", "label": "复合词"}, {"form": "参赛队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "前往并加入某一场具体的比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：去加入比赛，与“去外地”和“篮球队”的语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：篮球队去外地的目的是比赛，“生病”与句意不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“去外地睡觉”没有合理目的，与球队出行的语境冲突。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是身体反应，不能作为“去外地”的目的动作。"}], "explanations": {"参赛": "参赛：去加入比赛，与“去外地”和“篮球队”的语境相符。", "生病": "语义：篮球队去外地的目的是比赛，“生病”与句意不符。", "睡觉": "语义：“去外地睡觉”没有合理目的，与球队出行的语境冲突。", "咳嗽": "搭配：“咳嗽”是身体反应，不能作为“去外地”的目的动作。"}, "sentence_index": 0, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的婚礼，他没参赛，因为生病了。", "explanation": "这里应该用〈参加〉。参赛只用于比赛，婚礼等场合要用参加。"}, {"text": "这次董事会，他没能参赛。", "explanation": "这里应该用〈出席〉。参赛只用于比赛，董事会要用出席。"}, {"text": "这件事他没有参赛。", "explanation": "这里应该用〈参与〉。参赛只用于比赛，泛指的事情要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：去加入比赛，符合“三个人一起去”的句意。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“去”后接“哭泣”这类情绪动作不成立，也与“很有意思”矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体不适，不会让人觉得“很有意思”。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体不适，与“一起去”的轻松语境不符。"}], "explanations": {"参赛": "参赛：去加入比赛，符合“三个人一起去”的句意。", "哭泣": "搭配：“去”后接“哭泣”这类情绪动作不成立，也与“很有意思”矛盾。", "感冒": "语义：感冒是身体不适，不会让人觉得“很有意思”。", "发烧": "语义：发烧是身体不适，与“一起去”的轻松语境不符。"}, "sentence_index": 6, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长选举的时候，他没有参赛。", "explanation": "这里应该用〈竞选〉。参赛指参加比赛，选班长要用竞选。"}, {"text": "我明天去医院参赛。", "explanation": "这里应该用〈看病〉。参赛只用于比赛，去医院就诊要用看病。"}, {"text": "妹妹明天去邮局参赛。", "explanation": "这里应该用〈寄〉。参赛只用于比赛，去邮局寄东西要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上个月没参赛了。", "corrected_sentence": "他上个月没参赛。", "error_description": "错误：“没”否定已发生的“参赛”时，句末不能再加“了”。正确说法是“没参赛”，不说“没参赛了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次他被参赛了。", "corrected_sentence": "这次他被选中参赛了。", "error_description": "错误：“参赛”是主动加入比赛的动作，不能直接用“被”引出。正确说法是“被选中参赛”，由“选中”表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
