INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加比赛。", "primary_collocate": null, "pronunciation": "cān sài", "ipa": "tsʰan˥ sai˥˩", "syllable_count": 2, "sentences": [{"text": "参赛的选手请先到一楼报到。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他代表我们班参赛，大家都给他加油。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，一共有一百多支队伍参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想参赛，可是时间不够。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地参赛，不在乎能不能赢。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个参赛的人都会得到一份小礼物。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不参赛？你唱得那么好。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备了很久，终于可以参赛了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队有五个人参赛，其中两个是女生。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参赛的那天，我一定去看你。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参赛了", "label": "体标（了）"}, {"form": "参赛过", "label": "体标（过）"}, {"form": "参赛者", "label": "复合词"}, {"form": "参赛队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "作为选手或队伍参加比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：指选手加入比赛，修饰“选手”，符合句意。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑的选手不会到一楼报到，与句意冲突。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：失踪的人无法到一楼报到，与句意冲突。"}, {"text": "退赛", "is_correct": false, "explanation": "搭配：“退赛的选手”指已退出比赛的人，与“请先到一楼报到”的要求矛盾。"}], "explanations": {"参赛": "参赛：指选手加入比赛，修饰“选手”，符合句意。", "逃跑": "语义：逃跑的选手不会到一楼报到，与句意冲突。", "失踪": "语义：失踪的人无法到一楼报到，与句意冲突。", "退赛": "搭配：“退赛的选手”指已退出比赛的人，与“请先到一楼报到”的要求矛盾。"}, "sentence_index": 0, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的派对，我没参赛，因为有点累。", "explanation": "这里应该用〈参加〉。参赛只用于比赛，派对要用参加。"}, {"text": "那场音乐会，爸爸没能参赛。", "explanation": "这里应该用〈出席〉。参赛指加入比赛，音乐会这类场合要用出席。"}, {"text": "这次讨论会，他很积极地参赛。", "explanation": "这里应该用〈参与〉。参赛只用于比赛，讨论会要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：指参加比赛，符合“你为什么不”后的劝说语境。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是可以选择做或不做的事，与“为什么不”的问法不合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是可以主动选择“不做”的事，与后句的称赞矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“为什么不哭”不是常见的劝说搭配，与后句“唱得那么好”也不合。"}], "explanations": {"参赛": "参赛：指参加比赛，符合“你为什么不”后的劝说语境。", "咳嗽": "语义：咳嗽不是可以选择做或不做的事，与“为什么不”的问法不合。", "生病": "语义：生病不是可以主动选择“不做”的事，与后句的称赞矛盾。", "哭": "搭配：“为什么不哭”不是常见的劝说搭配，与后句“唱得那么好”也不合。"}, "sentence_index": 6, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长选举那天，她没有参赛。", "explanation": "这里应该用〈竞选〉。参赛指参加比赛，选班长要用竞选。"}, {"text": "我妹妹明天要去医院参赛。", "explanation": "这里应该用〈看病〉。参赛只用于比赛，去医院就诊要用看病。"}, {"text": "我爸爸明天要去邮局参赛。", "explanation": "这里应该用〈寄〉。参赛只用于比赛，去邮局寄东西要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年没参赛了。", "corrected_sentence": "我去年没参赛。", "error_description": "错误：“没”否定已发生的“参赛”时，句末不能加“了”。正确说法是“没参赛”，不说“没参赛了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
