INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个词或一句话里藏着的意思。", "primary_collocate": null, "pronunciation": "hán yì", "ipa": "xan˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这句话有很深的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂他这句话的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话里有两层含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说这话是什么含义？", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的含义很深。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着看我，笑里有别的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你想一想这句话的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势有特别的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话，我过了很久才明白它的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话里还有别的含义，我一下子就听出来了。", "target_word": "含义", "complexity_tier": "T3", "furigana": "tā de huà lǐ hái yǒu bié de hányì, wǒ yíxiàzi jiù tīng chūlái le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "话语中藏着的、需要体会的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含义", "is_correct": true, "explanation": "正确。“含义”指话里藏着的意思，可以说“有很深的含义”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指看得见的色彩，一句话没有颜色，不能说“很深的颜色”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听得见的响动，与这句话的深意不合，不能说“很深的声音”。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：“深”形容意思、道理或造诣，“水平”一般说“高”或“低”，不说“水平很深”。"}], "explanations": {"含义": "正确。“含义”指话里藏着的意思，可以说“有很深的含义”。", "颜色": "语义：“颜色”指看得见的色彩，一句话没有颜色，不能说“很深的颜色”。", "声音": "语义：“声音”指听得见的响动，与这句话的深意不合，不能说“很深的声音”。", "水平": "搭配：“深”形容意思、道理或造诣，“水平”一般说“高”或“低”，不说“水平很深”。"}, "sentence_index": 0, "correct_answer": "含义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的含义很快。", "explanation": "这里应该用〈速度〉。“速度”指快慢，车可以说“很快”；“含义”指词句里藏着的意思，不能用来形容车。"}, {"text": "这是我的一点小含义。", "explanation": "“一点小意思”里的“意思”指送的小礼物，这里不能换成“含义”。"}, {"text": "这句话有一只含义。", "explanation": "量词用错。“含义”应用“层”或“个”，“只”用于动物或单个物件，不用于含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含义", "is_correct": true, "explanation": "正确。“请你想一想这句话的含义”中，“含义”指这句话包含的意思。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或事物的外表，一句话没有外貌，不能说“这句话的外貌”。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指人的神情气色，一句话没有脸色，这里不能用。"}, {"text": "气味", "is_correct": false, "explanation": "感官：“气味”是用鼻子闻到的，一句话没有气味，这里不能用。"}], "explanations": {"含义": "正确。“请你想一想这句话的含义”中，“含义”指这句话包含的意思。", "外貌": "体貌：“外貌”指人或事物的外表，一句话没有外貌，不能说“这句话的外貌”。", "脸色": "体貌：“脸色”指人的神情气色，一句话没有脸色，这里不能用。", "气味": "感官：“气味”是用鼻子闻到的，一句话没有气味，这里不能用。"}, "sentence_index": 6, "correct_answer": "含义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事要按他的含义办。", "explanation": "这里应该用〈意愿〉。“意愿”指想法和愿望，按别人的意愿办事要说“意愿”。"}, {"text": "我把这份含义送给老师。", "explanation": "这里应该用〈心意〉。送礼物时表达的情意是“心意”，“含义”不能拿来送人。"}, {"text": "这首诗有一张含义。", "explanation": "量词用错。“张”用于纸张、桌子等平面的物件，不用于含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌里藏着一只含义。", "corrected_sentence": "这首歌里藏着一层含义。", "error_description": "量词错误：“只”用于动物或单个物件，“含义”应用“层”或“个”。正确说“一层含义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个符号的含义深很。", "corrected_sentence": "这个符号的含义很深。", "error_description": "“很”的位置错误：形容词前面要加“很”，应说“很深”，不说“深很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
