INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "词句等所包含的意义。", "primary_collocate": null, "pronunciation": "hán yì", "ipa": "xan˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这个词有两个含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个词的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字的含义是什么？", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "词典里写着这个成语的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在中国有好的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个词，在不同的句子里含义不同。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查了词典，才知道这个词的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了“福”字的含义。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字的含义是“平安”。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的含义不一样。", "target_word": "含义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层", "label": "量词"}], "register": "中性", "sense_fingerprint": "词语、句子、名字等本身包含的意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含义", "is_correct": true, "explanation": "正确。“含义”指词句所包含的意义，可以说“这个词有两个含义”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指看得见的色彩，词没有颜色，不能说“两个颜色”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，词没有身材，不能这样说。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热的程度，词没有温度，这里说不通。"}], "explanations": {"含义": "正确。“含义”指词句所包含的意义，可以说“这个词有两个含义”。", "颜色": "语义：“颜色”指看得见的色彩，词没有颜色，不能说“两个颜色”。", "身材": "体貌：“身材”指人的体形，词没有身材，不能这样说。", "温度": "语义：“温度”指冷热的程度，词没有温度，这里说不通。"}, "sentence_index": 0, "correct_answer": "含义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的含义很兴奋。", "explanation": "这里应该用〈心情〉。“心情”指情绪，人的心情可以很兴奋；“含义”指词句所包含的意思，不能用来形容人的情绪。"}, {"text": "我把这份含义交给了老师。", "explanation": "这里应该用〈材料〉。“材料”指文件、资料，要说“交材料”；“含义”指词句包含的意思，不能拿来交给别人。"}, {"text": "这是我的一点含义，请您收下。", "explanation": "这里应该用〈心意〉。“一点心意”是送礼时的客气话，“含义”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含义", "is_correct": true, "explanation": "正确。“查词典才知道这个词的含义”，“含义”指这个词包含的意义。"}, {"text": "文采", "is_correct": false, "explanation": "语域：“文采”是书面的文学用语，查词典后说“知道含义”时不这样用。"}, {"text": "辞章", "is_correct": false, "explanation": "语域：“辞章”是书面的文学用语，日常说话时不这样用。"}, {"text": "主人", "is_correct": false, "explanation": "配价：“主人”要指能支配某物的人，“词”不能有“主人”，这里说不通。"}], "explanations": {"含义": "正确。“查词典才知道这个词的含义”，“含义”指这个词包含的意义。", "文采": "语域：“文采”是书面的文学用语，查词典后说“知道含义”时不这样用。", "辞章": "语域：“辞章”是书面的文学用语，日常说话时不这样用。", "主人": "配价：“主人”要指能支配某物的人，“词”不能有“主人”，这里说不通。"}, "sentence_index": 6, "correct_answer": "含义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事要按大家的含义来决定。", "explanation": "这里应该用〈意愿〉。“意愿”指大家的想法和愿望，按大家的意愿决定事情要说“意愿”。"}, {"text": "这个词有一张含义。", "explanation": "量词用错。“张”用于纸张、桌子等平面的物件，不用于含义。"}, {"text": "这把椅子的含义很舒服。", "explanation": "这里应该用〈舒适〉。“舒适”形容物品让人觉得舒服；“含义”指词句包含的意思，不能用来形容椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章有两只含义。", "corrected_sentence": "这篇文章有两层含义。", "error_description": "量词错误：“只”用于动物或单个物件，“含义”应用“层”或“个”。正确说“两层含义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个字有两条含义。", "corrected_sentence": "这个字有两层含义。", "error_description": "量词错误：“条”用于细长的物件，不能用来数“含义”。正确说“两层含义”或“两个含义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
