INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95347, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "没想到会这样，和我想的不一样。", "primary_collocate": null, "pronunciation": "nǎ zhī dào", "ipa": "na˨˩ ʈʂɻ̩˥ taʊ̯˥˩", "syllable_count": 3, "sentences": [{"text": "我以为饭很便宜，哪知道要一百块。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上去很凶，哪知道人特别好。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想坐地铁去，哪知道今天停开了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家店很好，哪知道菜又冷又贵。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他是新人，哪知道他工作十年了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说马上到，哪知道一个小时后才来。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我准备了礼物，哪知道今天不是他生日。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影前我很开心，哪知道电影太无聊了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点出门，哪知道手机坏了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家以为会赢，哪知道最后输了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "说明实际情况和自己原来的想法不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c26939-6725-4f6a-bb31-b15d2945697c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪知道", "is_correct": true, "explanation": "正确：“哪知道”表示没想到的情况，与前面“以为很便宜”的想法相反。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，不能表示价格与想法不一样。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“要一百块”的现状不符。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”表示庆幸，与“要一百块”这种令人意外的价格不搭配。"}], "explanations": {"哪知道": "正确：“哪知道”表示没想到的情况，与前面“以为很便宜”的想法相反。", "马上": "语义：“马上”表示立即，不能表示价格与想法不一样。", "曾经": "语义：“曾经”表示过去的经历，与“要一百块”的现状不符。", "幸好": "搭配：“幸好”表示庆幸，与“要一百块”这种令人意外的价格不搭配。"}, "sentence_index": 0, "correct_answer": "哪知道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上先去了超市，哪知道下午又去了银行。", "explanation": "这里应该用〈然后〉。“哪知道”表示出乎意料，而“先去超市、下午去银行”是正常的先后安排，没有意外之处。"}, {"text": "听说那家店很好，哪知道菜又好又便宜。", "explanation": "这里“哪知道”表示与预想相反，而“菜又好又便宜”与“听说很好”的预想相符，应改用〈果真〉之类表示如所料的说法。"}, {"text": "我以为这家店很贵，哪知道价钱真的很高。", "explanation": "这里应该用〈果真〉。“哪知道”表示与预想相反，而“以为很贵”与“价钱真的很高”相符，不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪知道", "is_correct": true, "explanation": "正确：“哪知道”表示与想法不一样，句中“准备了礼物”的想法与实际情况相反。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示确定，不能表示与想法相反的情况。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已完成，与“今天不是他生日”的情况搭配不当。"}, {"text": "早就", "is_correct": false, "explanation": "搭配：“早就”表示先前已发生，与“今天不是他生日”不搭配。"}], "explanations": {"哪知道": "正确：“哪知道”表示与想法不一样，句中“准备了礼物”的想法与实际情况相反。", "一定": "语义：“一定”表示确定，不能表示与想法相反的情况。", "已经": "搭配：“已经”表示已完成，与“今天不是他生日”的情况搭配不当。", "早就": "搭配：“早就”表示先前已发生，与“今天不是他生日”不搭配。"}, "sentence_index": 6, "correct_answer": "哪知道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家以为会赢，哪知道最后果然赢了。", "explanation": "这里“哪知道”表示与预想相反，而句中的结果与“以为会赢”的预想相符，应改用〈果真〉之类表示如所料的说法。"}, {"text": "老师说今天有测验，哪知道今天真的有测验。", "explanation": "这里应该用〈果真〉。“哪知道”表示与预想相反，而“老师说有测验”与“真的有测验”相符，不能用。"}, {"text": "大家早就知道会输，哪知道最后输了。", "explanation": "这里应该用〈果然〉。大家早就知道会输，最后输了是意料之中，“哪知道”表示出乎意料，不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为他很忙，哪知道的他一点事都没有。", "corrected_sentence": "我以为他很忙，哪知道他一点事都没有。", "error_description": "助词错误：“哪知道”后面不能加“的”。应说“哪知道他一点事都没有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我本以为能按时到，哪知道了路上堵车了。", "corrected_sentence": "我本以为能按时到，哪知道路上堵车了。", "error_description": "助词错误：“哪知道”后面不能加“了”。应说“哪知道路上堵车了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7aeff772-539d-4f47-b284-c068f2a7122c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
