INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95350, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示不满、不屑的叹词。", "primary_collocate": null, "pronunciation": "hēng", "ipa": "xəŋ˥", "syllable_count": 1, "sentences": [{"text": "“哼！我才不信你的话。”", "target_word": "哼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他看了我一眼，说：“哼，没什么了不起。”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“哼！你每次都这样说。”", "target_word": "哼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹生气了，大声说：“哼，我不和你玩了！”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“哼，他以为自己最聪明。”", "target_word": "哼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王撇撇嘴，说：“哼，这种东西谁稀罕！”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“哼！这么贵的东西，我才不买。”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说：“哼，你不说我也知道。”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“哼，谁要你帮忙！”", "target_word": "哼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老王听完，冷笑着说：“哼，他那点本事也敢吹？”", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示不满不屑的叹词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36dfc1c3-bfed-4839-928d-9a6989dfa483') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼（hēng）：表示不满、不屑的叹词。"}, {"text": "横", "is_correct": false, "explanation": "横（héng）与 hēng 声调不同，是第二声，意思是横向。"}, {"text": "坑", "is_correct": false, "explanation": "坑（kēng）与 hēng 声母不同，k 与 h 不同，意思是坑洞。"}, {"text": "轰", "is_correct": false, "explanation": "轰（hōng）与 hēng 韵母不同，o 与 e 不同，意思是轰隆的声音。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng）与 hēng 声母不同，sh 与 h 不同，意思是出生、生活。"}], "explanations": {"哼": "哼（hēng）：表示不满、不屑的叹词。", "横": "横（héng）与 hēng 声调不同，是第二声，意思是横向。", "坑": "坑（kēng）与 hēng 声母不同，k 与 h 不同，意思是坑洞。", "轰": "轰（hōng）与 hēng 韵母不同，o 与 e 不同，意思是轰隆的声音。", "生": "生（shēng）与 hēng 声母不同，sh 与 h 不同，意思是出生、生活。"}, "sentence_index": null, "correct_answer": "哼"}, "level_3": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼：表示不满、不屑的叹词，与“我才不信”的语气相合。"}, {"text": "啊", "is_correct": false, "explanation": "语义：“啊”表示恍然或惊叹，与“我才不信你的话”的否定语气不合。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，与“不信”的态度不合。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：“嗨”是招呼或喊人的声音，与表示不满的否定语气不合。"}], "explanations": {"哼": "哼：表示不满、不屑的叹词，与“我才不信”的语气相合。", "啊": "语义：“啊”表示恍然或惊叹，与“我才不信你的话”的否定语气不合。", "哇": "语义：“哇”表示惊叹，与“不信”的态度不合。", "嗨": "语义：“嗨”是招呼或喊人的声音，与表示不满的否定语气不合。"}, "sentence_index": 0, "correct_answer": "哼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他握着救命恩人的手，哽咽着说：“哼，我真不知道怎么感谢你！”", "explanation": "这里应该用〈谢谢〉。哽咽着道谢表示感激，“哼”表示不满或不屑，不能用在这里。"}, {"text": "妈妈摸着孩子的头，温柔地说：“哼，宝贝，晚安。”", "explanation": "这里应该删去“哼”。温柔的道别与“哼”表示的不满或不屑相反。"}, {"text": "他恭敬地向台下深深鞠躬，说：“哼，各位老师好。”", "explanation": "这里应该删去“哼”，直接说〈各位老师好〉。恭敬的问候与“哼”表示的不满或不屑相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95350, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼（hēng）：表示不满、不屑的叹词。"}, {"text": "恒", "is_correct": false, "explanation": "恒（héng）与 hēng 声调不同，是第二声，意思是长久、不变。"}, {"text": "烘", "is_correct": false, "explanation": "烘（hōng）与 hēng 韵母不同，o 与 e 不同，意思是用火或热气使干燥。"}, {"text": "烹", "is_correct": false, "explanation": "烹（pēng）与 hēng 声母不同，p 与 h 不同，意思是烹饪。"}, {"text": "哄", "is_correct": false, "explanation": "哄（hōng）与 hēng 韵母不同，o 与 e 不同，意思是哄劝。"}], "explanations": {"哼": "哼（hēng）：表示不满、不屑的叹词。", "恒": "恒（héng）与 hēng 声调不同，是第二声，意思是长久、不变。", "烘": "烘（hōng）与 hēng 韵母不同，o 与 e 不同，意思是用火或热气使干燥。", "烹": "烹（pēng）与 hēng 声母不同，p 与 h 不同，意思是烹饪。", "哄": "哄（hōng）与 hēng 韵母不同，o 与 e 不同，意思是哄劝。"}, "sentence_index": null, "correct_answer": "哼"}, "level_3": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼：表示不满、不屑的叹词，与“我才不买”的语气相合。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：“嗨”是打招呼或兴奋的声音，与表示不满的语气不合。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”是咳嗽或清嗓的声音，与这句的语气不合。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是招呼或喊人的声音，与对价格的评价不合。"}], "explanations": {"哼": "哼：表示不满、不屑的叹词，与“我才不买”的语气相合。", "嗨": "语义：“嗨”是打招呼或兴奋的声音，与表示不满的语气不合。", "咳": "语义：“咳”是咳嗽或清嗓的声音，与这句的语气不合。", "喂": "语义：“喂”是招呼或喊人的声音，与对价格的评价不合。"}, "sentence_index": 6, "correct_answer": "哼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位老友久别重逢，热泪盈眶，哼了一声说：“好久不见。”", "explanation": "这里应该用〈啊〉。久别重逢的感叹要用“啊”，“哼”表示的不满或不屑与热泪盈眶的情境相反。"}, {"text": "她恭敬地走到领导面前，哼了一声说：“早上好！”", "explanation": "这里应该删去“哼”。对上级的恭敬问候与“哼”表示的不满或不屑相反。"}, {"text": "他抱着生病的小狗，眼眶湿润，哼了一声说：“别怕，我在这儿。”", "explanation": "这里应该删去“哼”。安慰的语气与“哼”表示的不满或不屑相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“哼了，你以为你是谁！”", "corrected_sentence": "“哼，你以为你是谁！”", "error_description": "错误：“哼了”；正确：“哼”。叹词后面不能加“了”，“了”只用于动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“哼地，这种话谁信啊！”", "corrected_sentence": "“哼，这种话谁信啊！”", "error_description": "错误：“哼地”；正确：“哼”。叹词后面不能加结构助词“地”，“地”只用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b1ace79-53a1-4242-a2e2-e2b35734789e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已婚", "is_correct": true, "explanation": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。"}, {"text": "悠闲", "is_correct": false, "explanation": "非反义：“悠闲”形容生活节奏慢，与婚姻状况没有相对关系。"}, {"text": "热情", "is_correct": false, "explanation": "非反义：“热情”形容待人态度，与是否有伴侣无关。"}, {"text": "清楚", "is_correct": false, "explanation": "非反义：“清楚”形容明白或分明，与婚姻状况没有相对关系。"}], "correct_answer": "已婚", "explanations": {"已婚": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。", "悠闲": "非反义：“悠闲”形容生活节奏慢，与婚姻状况没有相对关系。", "热情": "非反义：“热情”形容待人态度，与是否有伴侣无关。", "清楚": "非反义：“清楚”形容明白或分明，与婚姻状况没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已婚", "is_correct": true, "explanation": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。"}, {"text": "繁华", "is_correct": false, "explanation": "非反义：“繁华”形容地方热闹兴旺，与婚姻状况没有相对关系。"}, {"text": "认真", "is_correct": false, "explanation": "非反义：“认真”形容做事专注，与是否有伴侣无关。"}, {"text": "温和", "is_correct": false, "explanation": "非反义：“温和”形容性情或气候平和，与婚姻状况没有相对关系。"}], "correct_answer": "已婚", "explanations": {"已婚": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。", "繁华": "非反义：“繁华”形容地方热闹兴旺，与婚姻状况没有相对关系。", "认真": "非反义：“认真”形容做事专注，与是否有伴侣无关。", "温和": "非反义：“温和”形容性情或气候平和，与婚姻状况没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有结婚，也没有一起住的另一半。", "primary_collocate": null, "pronunciation": "dān shēn", "ipa": "tan˥˥ ʂən˥˥", "syllable_count": 2, "sentences": [{"text": "我现在单身，没有女朋友，也没有结婚。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是单身，下班后回家没有人等他。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她三十五岁了，单身，没有男朋友。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，单身的年轻人越来越多。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他单身，所以一个人住在小房子里。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你单身吗？有没有喜欢的人？", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟还单身，妈妈天天让他找女朋友。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单身生活很自由，但是有时候很孤单。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她单身，周末常常和朋友出去玩。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格上要写你是单身还是已婚。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "单身汉", "label": "复合"}, {"form": "单身贵族", "label": "复合"}, {"form": "單身", "label": "繁体"}], "register": "中性", "sense_fingerprint": "未婚且没有同居伴侣的感情状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单身", "is_correct": true, "explanation": "“单身”指没有伴侣，与“没有女朋友，也没有结婚”的语境相符。"}, {"text": "恩爱", "is_correct": false, "explanation": "语义：“恩爱”指夫妻或恋人感情好，与“没有女朋友”的语境矛盾。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音或场面，不用来形容人的感情状况。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：年幼的人不会谈恋爱或结婚，与句中的语境冲突。"}], "explanations": {"单身": "“单身”指没有伴侣，与“没有女朋友，也没有结婚”的语境相符。", "恩爱": "语义：“恩爱”指夫妻或恋人感情好，与“没有女朋友”的语境矛盾。", "吵闹": "搭配：“吵闹”形容声音或场面，不用来形容人的感情状况。", "年幼": "语义：年幼的人不会谈恋爱或结婚，与句中的语境冲突。"}, "sentence_index": 0, "correct_answer": "单身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈在一个单身工作，每天很忙。", "explanation": "这里应该用〈单位〉。单位指工作的机构，“单身”不能指工作场所，两词只是字形相近。"}, {"text": "这种生活很单身，没有变化。", "explanation": "这里应该用〈单调〉。单调形容生活或内容没有变化，“单身”说的是婚姻状况。"}, {"text": "他的想法很单身，总是相信别人。", "explanation": "这里应该用〈单纯〉。单纯形容想法简单、不复杂，“单身”只说婚姻状况，不能用来形容想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单身", "is_correct": true, "explanation": "“单身”指没有伴侣，与“妈妈天天让他找女朋友”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不用来形容一个人的婚姻状况。"}, {"text": "幼小", "is_correct": false, "explanation": "语义：“幼小”指年纪很小，与“找女朋友”的语境不符。"}, {"text": "童稚", "is_correct": false, "explanation": "语义：“童稚”指孩子气，与成年人找女朋友的语境冲突。"}], "explanations": {"单身": "“单身”指没有伴侣，与“妈妈天天让他找女朋友”的语境相符。", "热闹": "搭配：“热闹”形容场面，不用来形容一个人的婚姻状况。", "幼小": "语义：“幼小”指年纪很小，与“找女朋友”的语境不符。", "童稚": "语义：“童稚”指孩子气，与成年人找女朋友的语境冲突。"}, "sentence_index": 6, "correct_answer": "单身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很单身，不保暖。", "explanation": "这里应该用〈单薄〉。单薄形容衣服或身体薄，“单身”只说人的婚姻状况，不能用来形容衣服。"}, {"text": "我买了一张单身床，很便宜。", "explanation": "这里应该用〈单人〉。单人床指一个人睡的床，“单身”不能修饰床。"}, {"text": "这种药的成分很单身，只有一种。", "explanation": "这里应该用〈单一〉。单一指只有一种、不复杂，“单身”只说婚姻状况，不能用来形容成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表姐三十岁还的单身，家里人都在催她。", "corrected_sentence": "我表姐三十岁还单身，家里人都在催她。", "error_description": "错误：“还的单身”。副词“还”后面不能直接加“的”修饰名词，应去掉“的”，说“还单身”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我堂哥一直单身在现在，家里人都很担心他。", "corrected_sentence": "我堂哥一直单身到现在，家里人都很担心他。", "error_description": "错误：“单身在现在”。表示状态持续到某个时间，要用介词“到”，应说“一直单身到现在”，不能用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95352, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "已婚", "is_correct": true, "explanation": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。"}, {"text": "热闹", "is_correct": false, "explanation": "非反义：“热闹”形容场面，与婚姻状况没有相对关系。"}, {"text": "高兴", "is_correct": false, "explanation": "非反义：“高兴”指心情，与是否有配偶无关。"}, {"text": "健壮", "is_correct": false, "explanation": "非反义：“健壮”形容身体强健，与婚姻状况没有相对关系。"}], "correct_answer": "已婚", "explanations": {"已婚": "反义：“单身”指没有配偶，“已婚”指已有配偶，二者正好相对。", "热闹": "非反义：“热闹”形容场面，与婚姻状况没有相对关系。", "高兴": "非反义：“高兴”指心情，与是否有配偶无关。", "健壮": "非反义：“健壮”形容身体强健，与婚姻状况没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
