INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95352, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有配偶的；独自一人。", "primary_collocate": null, "pronunciation": "dān shēn", "ipa": "tan˥˥ ʂən˥˥", "syllable_count": 2, "sentences": [{"text": "他今年三十岁，还是单身。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐单身很多年了，但她过得很开心。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单身的人周末常常一个人去看电影。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师是单身，没有丈夫，也没有孩子。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司有很多单身的年轻人。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直单身，说自己一个人生活很自由。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生离婚以后一直单身。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人单身一辈子，没有结过婚。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友想找对象，不想再单身了。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单身的时候，我每天都自己做饭。", "target_word": "单身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "单身汉", "label": "复合"}, {"form": "单身贵族", "label": "复合"}, {"form": "單身", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没有配偶，独自一人生活的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd704c3d5-d131-4402-9bb4-f26ec0ee93c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单身", "is_correct": true, "explanation": "“单身”指没有配偶，与“还是”和“三十岁”的语境相符。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：三十岁已是成年人，不能说年幼，与句中“三十岁”相冲突。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不用来说一个人的婚姻状况。"}, {"text": "幼小", "is_correct": false, "explanation": "语义：“幼小”指年纪很小，与句中“三十岁”矛盾。"}], "explanations": {"单身": "“单身”指没有配偶，与“还是”和“三十岁”的语境相符。", "年幼": "语义：三十岁已是成年人，不能说年幼，与句中“三十岁”相冲突。", "热闹": "搭配：“热闹”形容场面或气氛，不用来说一个人的婚姻状况。", "幼小": "语义：“幼小”指年纪很小，与句中“三十岁”矛盾。"}, "sentence_index": 0, "correct_answer": "单身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张单身床很舒服，我每天晚上都睡得很好。", "explanation": "这里应该用〈单人〉。单人床指只供一人睡的床，“单身”只说人的婚姻状况，不能用来修饰床。"}, {"text": "这个孩子很单身，什么话都直接说。", "explanation": "这里应该用〈单纯〉。单纯形容人性格简单、不复杂，“单身”只说婚姻状况，不能用来形容孩子的性格。"}, {"text": "老人每天的饮食很单身，只吃青菜。", "explanation": "这里应该用〈单一〉。单一指种类只有一种，形容饮食要用“单一”；“单身”不能用来形容饮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单身", "is_correct": true, "explanation": "“单身”指没有配偶，与“离婚以后”的情境相符。"}, {"text": "恩爱", "is_correct": false, "explanation": "语义：“恩爱”指夫妻感情好，与“离婚以后”的情境矛盾。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容头脑，与句中说的婚姻状况不相关。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音或场面，不用来形容人的婚姻状况。"}], "explanations": {"单身": "“单身”指没有配偶，与“离婚以后”的情境相符。", "恩爱": "语义：“恩爱”指夫妻感情好，与“离婚以后”的情境矛盾。", "聪明": "语义：“聪明”形容头脑，与句中说的婚姻状况不相关。", "吵闹": "搭配：“吵闹”形容声音或场面，不用来形容人的婚姻状况。"}, "sentence_index": 6, "correct_answer": "单身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天穿得太单身，容易感冒。", "explanation": "这里应该用〈单薄〉。单薄形容衣服或身体薄，“单身”只说人的婚姻状况，不能用来形容衣服。"}, {"text": "这份工作每天都很单身，一点变化也没有。", "explanation": "这里应该用〈单调〉。单调形容内容或生活没有变化，不能用来形容工作，“单身”说的是婚姻状况。"}, {"text": "我每天八点去单身上班。", "explanation": "这里应该用〈单位〉。单位指工作的机构，“单身”不能指工作场所，两词只是字形相近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥一直的单身，家里人都替他着急。", "corrected_sentence": "表哥一直单身，家里人都替他着急。", "error_description": "错误：“一直的单身”。副词“一直”后面不能直接加“的”修饰名词，应去掉“的”，说“一直单身”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7937752-e703-4b5d-9a4a-a9a1ce602180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
