INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95353, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "忽然明白了，发出的声音。", "primary_collocate": null, "pronunciation": "ò", "ipa": "ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "噢，我想起来了，今天是你的生日！", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢！原来钥匙在我的口袋里。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，我知道了，是你把门关上的。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那张照片，他叫了一声：“噢！”", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，难怪这么冷，窗户没关。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，我明白了，你就是小王的妹妹。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，对了，我还没给妈妈打电话。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了半天，忽然说：“噢，是你啊！”", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，原来是我记错了时间。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，我懂了，这个字应该这样写。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "忽然想起或恍然大悟时发出的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9854624b-8070-4f99-8ae6-f7429f171087') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "噢", "is_correct": true, "explanation": "噢 ò：忽然想起或恍然大悟时发出的声音，即目标词。"}, {"text": "饿", "is_correct": false, "explanation": "ò 与 è 韵母不同（o 与 e），意思是饿。"}, {"text": "破", "is_correct": false, "explanation": "声母：pò 与 ò 仅声母不同（p 与零声母），意思是破。"}, {"text": "握", "is_correct": false, "explanation": "wò 比 ò 多了声母 w，意思是握住。"}], "explanations": {"噢": "噢 ò：忽然想起或恍然大悟时发出的声音，即目标词。", "饿": "ò 与 è 韵母不同（o 与 e），意思是饿。", "破": "声母：pò 与 ò 仅声母不同（p 与零声母），意思是破。", "握": "wò 比 ò 多了声母 w，意思是握住。"}, "sentence_index": null, "correct_answer": "噢"}, "level_3": {"options": [{"text": "噢", "is_correct": true, "explanation": "噢：忽然想起时发出的声音，符合“我想起来了”的句意。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是招呼语，不表示忽然想起。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃，不符合欣喜想起生日的语气。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与“我想起来了”的句意冲突。"}], "explanations": {"噢": "噢：忽然想起时发出的声音，符合“我想起来了”的句意。", "喂": "语义：“喂”是招呼语，不表示忽然想起。", "呸": "语域：“呸”表示唾弃，不符合欣喜想起生日的语气。", "嘘": "语义：“嘘”表示让人安静，与“我想起来了”的句意冲突。"}, "sentence_index": 0, "correct_answer": "噢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "噢，我的脚好疼！", "explanation": "这里应该用〈哎哟〉。噢表示忽然明白，表示疼痛要用哎哟。"}, {"text": "噢，我还是想不起来他是谁。", "explanation": "这里应该用〈哎呀〉。噢表示忽然想起，句中说仍想不起来，与之矛盾；懊恼、困惑时用哎呀。"}, {"text": "噢，我完全不明白你的意思。", "explanation": "这里应该用〈哎〉。噢表示忽然明白，句中说完全不明白，与之矛盾；表示困惑用哎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噢", "is_correct": true, "explanation": "噢：忽然想起时发出的声音，符合“对了”的句意。"}, {"text": "哼", "is_correct": false, "explanation": "语域：“哼”带不满或轻蔑的口气，不符合恍然想起的语气。"}, {"text": "呵", "is_correct": false, "explanation": "语义：“呵”是笑声，不表示忽然想起。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与“对了”的回想语境不合。"}], "explanations": {"噢": "噢：忽然想起时发出的声音，符合“对了”的句意。", "哼": "语域：“哼”带不满或轻蔑的口气，不符合恍然想起的语气。", "呵": "语义：“呵”是笑声，不表示忽然想起。", "嘘": "语义：“嘘”表示让人安静，与“对了”的回想语境不合。"}, "sentence_index": 6, "correct_answer": "噢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "噢，我的天哪，我还是没想起这件事。", "explanation": "这里应该用〈哎呀〉。噢表示忽然想起，句中说仍没想起，与之矛盾；惊讶、懊恼要用哎呀。"}, {"text": "噢，我一直没听明白你要做什么。", "explanation": "这里应该用〈哎〉。噢表示忽然明白，句中说一直没听明白，与之矛盾；困惑要用哎。"}, {"text": "噢，我还是没明白他为什么走。", "explanation": "这里应该用〈哎呀〉。噢表示忽然明白，句中说还没明白，与之矛盾；着急、懊恼要用哎呀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我噢想起来了，你的书在桌子上。", "corrected_sentence": "噢，我想起来了，你的书在桌子上。", "error_description": "错误：“噢”是叹词，应放在句首独立使用，不能插在“我”和“想起来了”之间。正确说法是“噢，我想起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "噢了，对了，我还没给爸爸打电话。", "corrected_sentence": "噢，对了，我还没给爸爸打电话。", "error_description": "错误：“噢”是叹词，后面不能加“了”。正确说法是“噢，对了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbe1ffd8-a3dc-44be-8085-b68b09c3db6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
