INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家的元首，是国家最高的职位之一。", "primary_collocate": null, "pronunciation": "guó jiā zhǔ xí", "ipa": "kuo˧˥ tɕja˥ ʈʂu˨˩ ɕi˧˥", "syllable_count": 4, "sentences": [{"text": "国家主席是国家最高的职位之一。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作了很多年，后来成了国家主席。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选国家主席的会议在北京开。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席要代表国家接待外国客人。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席的工作非常忙。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国家主席是一位女士。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席由全国人民代表大会选举产生。", "target_word": "国家主席", "complexity_tier": "T3", "furigana": "guó jiā zhǔ xí yóu quán guó rén mín dài biǎo dà huì xuǎn jǔ chǎn shēng", "sentence_source": "generated"}, {"text": "他不想做国家主席，只想当老师。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席的任期是五年。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国的国家主席来我们学校参观了。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位国家主席", "label": "量词"}, {"form": "國家主席", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家元首的职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家主席", "is_correct": true, "explanation": "正确：国家主席是国家的元首，是国家最高的职位之一。"}, {"text": "首都", "is_correct": false, "explanation": "语义：「首都」指首都城市，不是国家职位。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：「厨师」是职业，不是国家最高的职位。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：「公园」是游览场所，不能与「职位」搭配。"}], "explanations": {"国家主席": "正确：国家主席是国家的元首，是国家最高的职位之一。", "首都": "语义：「首都」指首都城市，不是国家职位。", "厨师": "语义：「厨师」是职业，不是国家最高的职位。", "公园": "搭配：「公园」是游览场所，不能与「职位」搭配。"}, "sentence_index": 0, "correct_answer": "国家主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家主席要代表本市接待外国客人。", "explanation": "这里应该用〈市长〉。市长代表本市接待客人；国家主席代表国家，不能只代表一个城市。"}, {"text": "国家主席要代表学校接待外国客人。", "explanation": "这里应该用〈校长〉。校长代表学校接待客人；国家主席是国家元首，不能代表一所学校。"}, {"text": "这个社团的国家主席明天要去参加比赛。", "explanation": "这里应该用〈社长〉。社团的负责人应说社长，国家主席指国家最高领导人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家主席", "is_correct": true, "explanation": "正确：国家主席由全国人民代表大会选举产生，符合句中的语境。"}, {"text": "大熊猫", "is_correct": false, "explanation": "配价：「选举产生」要求人或团体作主体，大熊猫不能被选举。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是场所，不能由代表大会选举产生。"}, {"text": "电视剧", "is_correct": false, "explanation": "语义：「电视剧」是影视作品，不能由代表大会选举产生。"}], "explanations": {"国家主席": "正确：国家主席由全国人民代表大会选举产生，符合句中的语境。", "大熊猫": "配价：「选举产生」要求人或团体作主体，大熊猫不能被选举。", "图书馆": "语义：「图书馆」是场所，不能由代表大会选举产生。", "电视剧": "语义：「电视剧」是影视作品，不能由代表大会选举产生。"}, "sentence_index": 6, "correct_answer": "国家主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的国家主席下个月去德国出差。", "explanation": "这里应该用〈董事长〉。公司的负责人应说董事长，国家主席指国家元首。"}, {"text": "我们班的国家主席每天都帮老师发作业。", "explanation": "这里应该用〈班长〉。班级的负责人应说班长，国家主席指国家元首。"}, {"text": "病房里的国家主席每天给病人量体温。", "explanation": "这里应该用〈护士〉。给病人量体温的人应说护士，国家主席指国家元首。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于当了上国家主席。", "corrected_sentence": "他终于当上了国家主席。", "error_description": "补语错误：「上」应紧跟动词「当」，说「当上」，「了」放在「上」后面，应说「当上了国家主席」，不能说「当了上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校曾经接待过过国家主席。", "corrected_sentence": "我们学校曾经接待过国家主席。", "error_description": "体标「过」重复：「接待过」已带体标「过」，不能再加一个「过」，应说「接待过国家主席」，不能说「接待过过国家主席」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家开办）相对，是反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑，与国营的所有制意义无关，不是反义词。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家开办）相对，是反义词。", "寒冷": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。", "聪明": "“聪明”形容头脑，与国营的所有制意义无关，不是反义词。", "漂亮": "“漂亮”形容外貌，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
