INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由国家来开的，不是个人开的。", "primary_collocate": null, "pronunciation": "guó yíng", "ipa": "kwo˧˥ jiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家商店是国营的，不是私人开的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前在一家国营工厂工作。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国营饭店的菜又好吃又便宜。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，城里的大商店大多是国营的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营书店里有很多旧书。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有一家国营医院。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是国营农场，不是个人的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸在国营商店卖了三十年东西。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司是私人的，不是国营的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常去国营百货商店买糖。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国营企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家开办的，不是私人开办的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5590457-323a-4f29-a55c-1e85319d3532') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外观，与“是国营还是私人开的”的语境无关。"}, {"text": "国营", "is_correct": true, "explanation": "国营指由国家开办，不是私人开办，与句中“不是私人开的”相符。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描述高度，不能用来说明商店由谁开办。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”是私人经营，与“不是私人开的”正相矛盾。"}], "explanations": {"漂亮": "语义：“漂亮”说外观，与“是国营还是私人开的”的语境无关。", "国营": "国营指由国家开办，不是私人开办，与句中“不是私人开的”相符。", "矮": "体貌：“矮”描述高度，不能用来说明商店由谁开办。", "私营": "语义：“私营”是私人经营，与“不是私人开的”正相矛盾。"}, "sentence_index": 0, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口的那棵大树是国营的。", "explanation": "这里把“国营”误用成了〈公共〉的意思。国营说的是由国家经营的单位，树不是单位，不能这样说。"}, {"text": "他爸爸是国营的，每天在家做饭。", "explanation": "这里把“国营”误用来形容人，误成了〈职业身份〉的意思。国营只说明单位的所有制，不能修饰人。"}, {"text": "这次考试是国营的，所有学生都要参加。", "explanation": "这里把“国营”误用成了〈全国性〉的意思。国营说的是单位由国家经营，考试不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”说温度，不能修饰农场，句子不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身形，不能修饰农场。"}, {"text": "国营", "is_correct": true, "explanation": "国营农场指由国家开办的农场，与“不是个人的”相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不能用来修饰农场。"}], "explanations": {"寒冷": "语义：“寒冷”说温度，不能修饰农场，句子不通。", "瘦": "体貌：“瘦”形容人或动物的身形，不能修饰农场。", "国营": "国营农场指由国家开办的农场，与“不是个人的”相符。", "聪明": "语义：“聪明”形容人的头脑，不能用来修饰农场。"}, "sentence_index": 6, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上那朵云是国营的，谁都能看见。", "explanation": "这里把“国营”误用成了〈公开〉的意思。国营说的是由国家经营的单位，云不是单位，不能这样说。"}, {"text": "我养的那只小狗是国营的，很听话。", "explanation": "这里把“国营”误用来指动物，误成了〈私养〉的意思。国营说的是单位由国家经营，小狗不是单位。"}, {"text": "我和她的友谊是国营的，很长久。", "explanation": "这里把“国营”误用成了〈共同〉的意思。国营只修饰由国家经营的单位，友谊不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店很国营的，价格比较低。", "corrected_sentence": "这家饭店是国营的，价格比较低。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；作谓语时要说“是国营的”，不能把“是”换成“很”，说成“很国营的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市有一家很国营剧院，每周都演出。", "corrected_sentence": "这座城市有一家国营剧院，每周都演出。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；修饰名词时前面不能加“很”，应说“一家国营剧院”，不能说“一家很国营剧院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家投资经营）相对，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白或清晰，与国营的所有制意义无关，不是反义词。"}, {"text": "宽广", "is_correct": false, "explanation": "“宽广”形容面积或范围大，与国营的所有制意义无关，不是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家投资经营）相对，是反义词。", "清楚": "“清楚”形容明白或清晰，与国营的所有制意义无关，不是反义词。", "宽广": "“宽广”形容面积或范围大，与国营的所有制意义无关，不是反义词。", "迟钝": "“迟钝”形容反应慢，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f92986f4-e2ef-4f74-b8c7-f309337bf38e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
